window.ETSDATA=window.ETSDATA||{};window.ETSDATA[4]={"lc":{"p1":[{"n":1,"opts":["She's crossing a busy street.","She's removing her eyeglasses.","She's standing next to a bin.","She's getting into a taxicab."],"vi":["Cô ấy đang băng qua một con phố đông đúc.","Cô ấy đang tháo kính mắt.","Cô ấy đang đứng bên cạnh một thùng rác.","Cô ấy đang lên taxi."],"ans":"C","a":"E26-T04-01.mp3","img":"q1.jpg"},{"n":2,"opts":["Some trucks have stopped at a traffic signal.","Some lights are being installed above a garage door.","A garden is being planted along a fence.","Several vehicles are parked outside a building."],"vi":["Một số xe tải đã dừng tại tín hiệu giao thông.","Một số đèn đang được lắp đặt phía trên cửa gara.","Một khu vườn đang được trồng dọc theo hàng rào.","Một số phương tiện đang đậu ngoài một tòa nhà."],"ans":"D","a":"E26-T04-02.mp3","img":"q2.jpg"},{"n":3,"opts":["A woman is following a man down a corridor.","A woman is putting together some cardboard boxes.","A man is emptying a large container.","A man is climbing up a ladder."],"vi":["Một người phụ nữ đang đi theo một người đàn ông dọc hành lang.","Một người phụ nữ đang ghép các hộp carton lại với nhau.","Một người đàn ông đang đổ rỗng một thùng chứa lớn.","Một người đàn ông đang leo lên thang."],"ans":"A","a":"E26-T04-03.mp3","img":"q3.jpg"},{"n":4,"opts":["He's clearing some snow off a path.","He's pulling a cart on a walkway.","He's leaning over to tie his shoe.","He's taking some items out of a basket."],"vi":["Anh ấy đang dọn tuyết khỏi lối đi.","Anh ấy đang kéo một chiếc xe đẩy trên lối đi bộ.","Anh ấy đang cúi xuống để buộc dây giày.","Anh ấy đang lấy một số vật dụng ra khỏi giỏ."],"ans":"B","a":"E26-T04-04.mp3","img":"q4.jpg"},{"n":5,"opts":["One of the women is carrying a bag on her shoulder.","One of the women is placing her luggage on a scale.","Some suitcases have been lined up against the wall.","Some clothes are being packed in a bag."],"vi":["Một trong những người phụ nữ đang mang túi trên vai.","Một trong những người phụ nữ đang đặt hành lý lên cân.","Một số vali đã được xếp dọc theo tường.","Một số quần áo đang được đóng gói vào túi."],"ans":"A","a":"E26-T04-05.mp3","img":"q5.jpg"},{"n":6,"opts":["Some customers are drinking from coffee cups.","Some coffee cups have been placed on a counter.","Some aprons are hanging from hooks.","One of the workers is wiping down a counter."],"vi":["Một số khách hàng đang uống từ cốc cà phê.","Một số cốc cà phê đã được đặt trên quầy.","Một số tạp dề đang treo trên móc.","Một trong những công nhân đang lau chùi quầy."],"ans":"B","a":"E26-T04-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Will you let me know when the catering order arrives?","qvi":"Bạn sẽ cho tôi biết khi đơn hàng dịch vụ ăn uống đến chứ?","opts":["A reservation for two.","The front office.","Sure, I'll text you."],"vi":["Đặt chỗ cho hai người.","Văn phòng phía trước.","Chắc chắn rồi, tôi sẽ nhắn tin cho bạn."],"ans":"C","a":"E26-T04-07.mp3"},{"n":8,"q":"Why is the manager being replaced?","qvi":"Tại sao quản lý bị thay thế?","opts":["Let's do that.","I prefer working with a team.","Because she's leaving the company."],"vi":["Hãy làm điều đó.","Tôi thích làm việc với nhóm.","Bởi vì cô ấy đang rời khỏi công ty."],"ans":"C","a":"E26-T04-08.mp3"},{"n":9,"q":"Ms. Cho should close the store early on Friday.","qvi":"Cô Cho nên đóng cửa hàng sớm vào thứ Sáu.","opts":["I prefer a salad.","Cash register four.","Yes, I agree."],"vi":["Tôi thích salad hơn.","Máy tính tiền số bốn.","Vâng, tôi đồng ý."],"ans":"C","a":"E26-T04-09.mp3"},{"n":10,"q":"Why did you decide to become a pilot?","qvi":"Tại sao bạn quyết định trở thành phi công?","opts":["Is there free Internet access?","I enjoy traveling.","He's on vacation in Argentina."],"vi":["Có truy cập Internet miễn phí không?","Tôi thích du lịch.","Anh ấy đang nghỉ phép ở Argentina."],"ans":"B","a":"E26-T04-10.mp3"},{"n":11,"q":"Have you always commuted by train?","qvi":"Bạn có luôn đi làm bằng tàu không?","opts":["The training starts at two o'clock.","I think the station is on Mulberry Avenue.","Yes, because I don't have a car."],"vi":["Buổi đào tạo bắt đầu lúc hai giờ.","Tôi nghĩ ga ở trên đại lộ Mulberry.","Vâng, vì tôi không có xe hơi."],"ans":"C","a":"E26-T04-11.mp3"},{"n":12,"q":"When does your manager usually come in?","qvi":"Quản lý của bạn thường đến lúc nào?","opts":["Early in the morning.","No, I just left it there.","I haven't—thanks."],"vi":["Sáng sớm.","Không, tôi vừa để nó ở đó.","Tôi chưa—cảm ơn."],"ans":"A","a":"E26-T04-12.mp3"},{"n":13,"q":"Isn't there a discount on this computer monitor?","qvi":"Không có giảm giá cho màn hình máy tính này sao?","opts":["Yes, a ten percent discount.","An inventory check.","Mine is broken."],"vi":["Có, giảm 10 phần trăm.","Kiểm tra hàng tồn kho.","Cái của tôi bị hỏng."],"ans":"A","a":"E26-T04-13.mp3"},{"n":14,"q":"How is the new group of interns doing?","qvi":"Nhóm thực tập sinh mới thế nào?","opts":["No, we have five people in total.","I haven't heard any negative feedback at all.","Let's pose for a group photo over there."],"vi":["Không, chúng tôi có tổng cộng năm người.","Tôi chưa nghe phản hồi tiêu cực nào cả.","Hãy chụp ảnh nhóm ở đằng kia."],"ans":"B","a":"E26-T04-14.mp3"},{"n":15,"q":"They're carrying those boxes to the storage room.","qvi":"Họ đang mang những hộp đó đến phòng lưu trữ.","opts":["That's a good price.","No, the store opens at noon today.","I'll go with them."],"vi":["Đó là giá tốt.","Không, cửa hàng mở cửa lúc trưa nay.","Tôi sẽ đi với họ."],"ans":"C","a":"E26-T04-15.mp3"},{"n":16,"q":"Where can I send the money?","qvi":"Tôi có thể gửi tiền đến đâu?","opts":["To my bank account.","I think that's expensive, too.","By next Tuesday."],"vi":["Đến tài khoản ngân hàng của tôi.","Tôi nghĩ cái đó cũng đắt.","Trước thứ Ba tuần tới."],"ans":"A","a":"E26-T04-16.mp3"},{"n":17,"q":"Who's coming in tomorrow to help us prepare for the grand opening?","qvi":"Ai sẽ đến vào ngày mai để giúp chúng ta chuẩn bị cho lễ khai trương?","opts":["Rebecca and Malik.","An online job posting.","Some sales data."],"vi":["Rebecca và Malik.","Một bài đăng tuyển dụng trực tuyến.","Một số dữ liệu bán hàng."],"ans":"A","a":"E26-T04-17.mp3"},{"n":18,"q":"How often does the bus stop at this location?","qvi":"Xe buýt dừng ở vị trí này bao lâu một lần?","opts":["I'll be visiting the office.","About every twenty minutes.","A city council meeting."],"vi":["Tôi sẽ đến thăm văn phòng.","Khoảng mỗi hai mươi phút.","Một cuộc họp hội đồng thành phố."],"ans":"B","a":"E26-T04-18.mp3"},{"n":19,"q":"What's the candidate review process?","qvi":"Quy trình xem xét ứng viên là gì?","opts":["We review the résumés first.","A few good reviews.","OK—I'll just follow them."],"vi":["Chúng tôi xem xét sơ yếu lý lịch trước.","Một vài đánh giá tốt.","Được rồi—Tôi sẽ chỉ theo họ."],"ans":"A","a":"E26-T04-19.mp3"},{"n":20,"q":"There's coffee in the break room, right?","qvi":"Có cà phê trong phòng nghỉ, phải không?","opts":["That shift starts at noon.","We decided to paint this room gray.","Yes—I just made a fresh pot."],"vi":["Ca làm việc đó bắt đầu lúc trưa.","Chúng tôi quyết định sơn phòng này màu xám.","Vâng—Tôi vừa pha một bình mới."],"ans":"C","a":"E26-T04-20.mp3"},{"n":21,"q":"Who's going to the company picnic today?","qvi":"Ai sẽ đi dã ngoại công ty hôm nay?","opts":["About two hours long.","I'm leaving in a few minutes.","A two-year maintenance contract."],"vi":["Khoảng hai giờ.","Tôi sẽ rời đi trong vài phút.","Hợp đồng bảo trì hai năm."],"ans":"B","a":"E26-T04-21.mp3"},{"n":22,"q":"Will the bakery be open tomorrow?","qvi":"Tiệm bánh sẽ mở cửa ngày mai chứ?","opts":["No, it's closed until mid-August.","Have you checked the oven?","The pound cake is delicious."],"vi":["Không, đóng cửa đến giữa tháng Tám.","Bạn đã kiểm tra lò nướng chưa?","Bánh pound ngon."],"ans":"A","a":"E26-T04-22.mp3"},{"n":23,"q":"Are you installing the new software on Monday or Tuesday?","qvi":"Bạn đang cài đặt phần mềm mới vào thứ Hai hay thứ Ba?","opts":["Thanks, but they already have one.","I'll be out of the office all week.","It was an older model laptop."],"vi":["Cảm ơn, nhưng họ đã có một cái.","Tôi sẽ vắng văn phòng cả tuần.","Đó là mẫu laptop cũ hơn."],"ans":"B","a":"E26-T04-23.mp3"},{"n":24,"q":"Let me find a sales associate to help you.","qvi":"Để tôi tìm nhân viên bán hàng giúp bạn.","opts":["At the top of the list.","My article is ready to be uploaded.","I just found what I'm looking for."],"vi":["Ở đầu danh sách.","Bài viết của tôi sẵn sàng để tải lên.","Tôi vừa tìm thấy thứ tôi đang tìm."],"ans":"C","a":"E26-T04-24.mp3"},{"n":25,"q":"You're offering discounts to students, right?","qvi":"Bạn đang cung cấp giảm giá cho sinh viên, phải không?","opts":["No, that's not my wallet.","You'll need valid identification.","I'm doing inventory this weekend."],"vi":["Không, đó không phải ví của tôi.","Bạn sẽ cần giấy tờ tùy thân hợp lệ.","Tôi đang kiểm kê hàng tồn kho cuối tuần này."],"ans":"B","a":"E26-T04-25.mp3"},{"n":26,"q":"The sales department posted an advertisement for an assistant.","qvi":"Bộ phận bán hàng đã đăng quảng cáo tuyển trợ lý.","opts":["I didn't know they were hiring.","An additional charge for shipping.","No, I haven't been there."],"vi":["Tôi không biết họ đang tuyển dụng.","Phí vận chuyển bổ sung.","Không, tôi chưa từng đến đó."],"ans":"A","a":"E26-T04-26.mp3"},{"n":27,"q":"Does the new accounting software work well?","qvi":"Phần mềm kế toán mới có hoạt động tốt không?","opts":["I haven't downloaded it yet.","We're not offering a discount.","That was my reaction too."],"vi":["Tôi chưa tải xuống.","Chúng tôi không cung cấp giảm giá.","Đó cũng là phản ứng của tôi."],"ans":"A","a":"E26-T04-27.mp3"},{"n":28,"q":"When's the finance department going to confirm our first-quarter budget?","qvi":"Bộ phận tài chính sẽ xác nhận ngân sách quý đầu tiên của chúng ta khi nào?","opts":["Their deadline is next week.","Yes, I'll be there.","In the mail room."],"vi":["Hạn chót của họ là tuần tới.","Vâng, tôi sẽ ở đó.","Trong phòng thư."],"ans":"A","a":"E26-T04-28.mp3"},{"n":29,"q":"Who canceled the conference call?","qvi":"Ai đã hủy cuộc gọi hội nghị?","opts":["The upstairs conference room.","It's been rescheduled.","Yes, you can."],"vi":["Phòng hội nghị tầng trên.","Nó đã được lên lịch lại.","Vâng, bạn có thể."],"ans":"B","a":"E26-T04-29.mp3"},{"n":30,"q":"Can you please transfer the service to my new phone?","qvi":"Bạn có thể chuyển dịch vụ sang điện thoại mới của tôi không?","opts":["Let's put it in the backseat.","At the Maple Street station.","There is a processing fee."],"vi":["Hãy đặt nó ở ghế sau.","Tại ga Maple Street.","Có phí xử lý."],"ans":"C","a":"E26-T04-30.mp3"},{"n":31,"q":"How was today's manufacturing seminar?","qvi":"Buổi hội thảo sản xuất hôm nay thế nào?","opts":["A new pair of shoes.","We didn't get there in time.","There's a user's manual in the drawer."],"vi":["Một đôi giày mới.","Chúng tôi không đến kịp giờ.","Có hướng dẫn sử dụng trong ngăn kéo."],"ans":"B","a":"E26-T04-31.mp3"}],"p3":[{"ns":[32,34],"script":[["W","Good morning. Thanks for coming to tour this apartment building.","Chào buổi sáng. Cảm ơn vì đã đến tham quan tòa nhà chung cư này."],["M","I'm glad I could visit in person. I've always wanted to live in this neighborhood—it's so beautiful. This building is brand-new, isn't it?","Tôi rất vui vì có thể đến trực tiếp. Tôi luôn muốn sống ở khu phố này—nó thật đẹp. Tòa nhà này là mới xây, phải không?"],["W","Yes. In fact, you'd be among the very first tenants if you decide to move here. Before you look at some apartments, would you please sign your name here in our guest book?","Đúng vậy. Thực ra, nếu bạn quyết định chuyển đến đây, bạn sẽ là một trong những người thuê đầu tiên. Trước khi xem một số căn hộ, bạn vui lòng ký tên vào sổ khách ở đây chứ?"],["M","Oh, of course.","Ồ, tất nhiên."]],"qs":[{"n":32,"q":"Who most likely is the woman?","qvi":"Người phụ nữ có khả năng là ai?","opts":["A landscape architect","An interior designer","A real estate agent","A building inspector"],"vi":["Kiến trúc sư cảnh quan","Nhà thiết kế nội thất","Nhân viên môi giới bất động sản","Thanh tra xây dựng"],"ans":"C"},{"n":33,"q":"What is the man looking forward to?","qvi":"Người đàn ông đang mong chờ điều gì?","opts":["Living in a particular area","Walking to work","Going on vacation","Saving money for a house"],"vi":["Sống tại một khu vực cụ thể","Đi bộ đi làm","Đi nghỉ mát","Tiết kiệm tiền mua nhà"],"ans":"A"},{"n":34,"q":"What does the woman ask for?","qvi":"Người phụ nữ yêu cầu điều gì?","opts":["Some references","Some identification","A signature","A payment"],"vi":["Một số thư giới thiệu","Một số giấy tờ tùy thân","Một chữ ký","Một khoản thanh toán"],"ans":"C"}],"a":"E26-T04-32-34.mp3"},{"ns":[35,37],"script":[["W","Chen, I hope all is going well on your first day. I saw you have some scheduled seafood deliveries across the bay in the Morgan District. Why haven't you left yet?","Chen, hy vọng mọi thứ suôn sẻ trong ngày đầu tiên của bạn. Tôi thấy bạn có lịch giao hải sản qua vịnh đến Quận Morgan. Tại sao bạn chưa khởi hành?"],["M","I wasn't going to head over to that particular area for another hour. Do the restaurants in the Morgan District want their deliveries earlier than scheduled?","Tôi định một giờ nữa mới đi đến khu vực đó. Các nhà hàng ở Quận Morgan có muốn nhận hàng sớm hơn lịch không?"],["W","No, but I'm concerned about Bay Bridge traffic. It's routinely congested with vehicles. So you should always add at least an extra hour to your trip out there.","Không, nhưng tôi lo về tắc nghẽn trên Cầu Bay. Nó thường xuyên kẹt xe. Vì vậy bạn nên luôn thêm ít nhất một giờ nữa cho chuyến đi đến đó."],["M","Thanks for the tip. I'll also check traffic Webcams on the highway agency's Web site.","Cảm ơn lời khuyên. Tôi cũng sẽ kiểm tra webcam giao thông trên trang web của cơ quan đường cao tốc."]],"qs":[{"n":35,"q":"What most likely is the man's job?","qvi":"Công việc của người đàn ông có khả năng là gì?","opts":["Boat crew member","Restaurant owner","Seafood inspector","Delivery truck driver"],"vi":["Thành viên thủy thủ đoàn tàu","Chủ nhà hàng","Thanh tra hải sản","Tài xế giao hàng"],"ans":"D"},{"n":36,"q":"Why is the woman concerned?","qvi":"Tại sao người phụ nữ lo lắng?","opts":["A road has been temporarily closed.","A permit has expired.","Traffic may cause a delay.","Some supplies are no longer available."],"vi":["Một con đường đã bị đóng tạm thời","Giấy phép đã hết hạn","Giao thông có thể bị chậm","Một số vật tư không còn có sẵn"],"ans":"C"},{"n":37,"q":"What does the man say he will check?","qvi":"Người đàn ông nói rằng anh ấy sẽ kiểm tra gì?","opts":["Some webcams","A list of ingredients","An address","Some maps"],"vi":["Một số webcam","Danh sách nguyên liệu","Một địa chỉ","Một số bản đồ"],"ans":"A"}],"a":"E26-T04-35-37.mp3"},{"ns":[38,40],"script":[["M","This morning I got an e-mail from Pelicon, a local producer of beauty products. They're interested in purchasing lanolin from us to use in their new line of all-natural makeup.","Sáng nay tôi nhận được email từ Pelicon, một nhà sản xuất sản phẩm làm đẹp địa phương. Họ quan tâm đến việc mua lanolin từ chúng ta để sử dụng trong dòng trang điểm tự nhiên hoàn toàn mới."],["W","I'm not sure about that. We're a fairly small farm, and we already sell lanolin to another local business. I'm worried that we don't produce enough lanolin to meet the demand of another client. I don't want to expand and take on more wool production.","Tôi không chắc về điều đó. Chúng ta là một trang trại khá nhỏ, và chúng ta đã bán lanolin cho một doanh nghiệp địa phương khác. Tôi lo rằng chúng ta không sản xuất đủ lanolin để đáp ứng nhu cầu của một khách hàng khác. Tôi không muốn mở rộng và đảm nhận sản xuất len nhiều hơn."],["M","But our contract with the business we currently supply lanolin to has almost expired—there's no guarantee it will be renewed. I think you should at least read Pelicon's proposal.","Nhưng hợp đồng của chúng ta với doanh nghiệp mà chúng ta hiện đang cung cấp lanolin sắp hết hạn—không có gì đảm bảo sẽ được gia hạn. Tôi nghĩ bạn nên ít nhất đọc đề xuất của Pelicon."],["W","Sure. Can you forward me the e-mail?","Được rồi. Bạn có thể chuyển email cho tôi không?"]],"qs":[{"n":38,"q":"According to the man, what does Pelicon produce?","qvi":"Theo người đàn ông, Pelicon sản xuất gì?","opts":["Household cleaners","Cosmetics","Industrial textiles","Pharmaceuticals"],"vi":["Chất tẩy rửa gia dụng","Mỹ phẩm","Vải công nghiệp","Dược phẩm"],"ans":"B"},{"n":39,"q":"What does the woman say she is concerned about?","qvi":"Người phụ nữ nói cô ấy đang lo lắng về điều gì?","opts":["Hiring skilled workers","Securing a bank loan","Finding transportation","Making enough product"],"vi":["Tuyển dụng công nhân lành nghề","Đảm bảo khoản vay ngân hàng","Đảm bảo phương tiện vận chuyển","Làm đủ sản phẩm"],"ans":"D"},{"n":40,"q":"Why does the man recommend reading an e-mail?","qvi":"Tại sao người đàn ông đề nghị đọc một email?","opts":["To consider a business proposal","To prepare for a client meeting","To view some construction plans","To learn the details of a complaint"],"vi":["Để xem xét một đề xuất kinh doanh","Để chuẩn bị cho buổi gặp khách hàng","Để xem một số bản vẽ xây dựng","Để biết chi tiết của một khiếu nại"],"ans":"A"}],"a":"E26-T04-38-40.mp3"},{"ns":[41,43],"script":[["M","Nisreen? This is Lewis. I heard you're going to be working for our company overseas, in the New Zealand office. What a great opportunity!","Nisreen? Đây là Lewis. Tôi nghe nói bạn sẽ làm việc cho công ty chúng ta ở nước ngoài, tại văn phòng New Zealand. Thật là cơ hội tuyệt vời!"],["W","Yes, thank you. I start next month, and I'm really excited.","Vâng, cảm ơn. Tôi bắt đầu tháng tới, và tôi rất hào hứng."],["M","I'm calling to touch base with you about some of our vendor contracts. It's time to renew the contracts, and I wanted to ask you to take care of that before you left.","Tôi gọi để thảo luận với bạn về một số hợp đồng nhà cung cấp của chúng ta. Đã đến lúc gia hạn hợp đồng, và tôi muốn yêu cầu bạn xử lý việc đó trước khi đi."],["W","No problem. I know where those files are located on our shared computer drive. I'll just need the password to access them.","Không vấn đề. Tôi biết các tệp đó nằm ở đâu trên ổ đĩa máy tính chia sẻ của chúng ta. Tôi chỉ cần mật khẩu để truy cập chúng."]],"qs":[{"n":41,"q":"What will the woman do next month?","qvi":"Tháng tới người phụ nữ sẽ làm gì?","opts":["Reorganize a department","Attend a conference","Relocate to an overseas office","Take a vacation"],"vi":["Tái tổ chức một bộ phận","Tham dự hội nghị","Chuyển tới văn phòng nước ngoài","Nghỉ phép"],"ans":"C"},{"n":42,"q":"What does the man want the woman to do?","qvi":"Người đàn ông muốn người phụ nữ làm gì?","opts":["Help with some contracts","Prepare a project timeline","Update some software","Call a sales representative"],"vi":["Hỗ trợ xử lý hợp đồng","Chuẩn bị tiến độ dự án","Cập nhật phần mềm","Gọi cho đại diện bán hàng"],"ans":"A"},{"n":43,"q":"What does the woman ask the man for?","qvi":"Người phụ nữ yêu cầu người đàn ông cung cấp điều gì?","opts":["Some employee names","Some credit card information","A file password","A telephone number"],"vi":["Một số tên nhân viên","Một số thông tin thẻ tín dụng","Một mật khẩu tệp","Một số điện thoại"],"ans":"C"}],"a":"E26-T04-41-43.mp3"},{"ns":[44,46],"script":[["W","Hi. This is Giovanni Marino's agent. I'm calling to reschedule his planned appearance on the Sunday Morning Show.","Chào. Đây là đại diện của Giovanni Marino. Tôi gọi để lên lịch lại lịch xuất hiện đã lên kế hoạch của anh ấy trên Sunday Morning Show."],["M","Right. We have him booked to appear on the show in July to promote his new movie.","Đúng rồi. Chúng tôi đã đặt lịch cho anh ấy xuất hiện trên chương trình vào tháng Bảy để quảng bá bộ phim mới."],["W","Unfortunately, the movie he's acting in is behind schedule, and he'll now be on location through the end of August.","Thật không may, bộ phim anh ấy đang đóng bị chậm tiến độ, và anh ấy sẽ ở địa điểm quay đến cuối tháng Tám."],["M","Hmm, I see. Let me look at our guest calendar. I have a slot I'm looking to fill on September fourteenth—would that work?","Hmm, tôi hiểu rồi. Để tôi xem lịch khách mời. Tôi có một khoảng trống cần lấp vào ngày 14 tháng Chín—có được không?"],["W","Yes, that would be great, thanks.","Vâng, sẽ tuyệt vời, cảm ơn."],["M","All right. I'll update the contract with the new date and e-mail it to you.","Được rồi. Tôi sẽ cập nhật hợp đồng với ngày mới và gửi email cho bạn."]],"qs":[{"n":44,"q":"Why is the woman calling?","qvi":"Tại sao người phụ nữ gọi điện?","opts":["To negotiate a payment","To reschedule an appearance","To book a venue","To ask about security"],"vi":["Để thương lượng khoản thanh toán","Để sắp xếp lại một buổi xuất hiện","Để đặt phòng","Để hỏi về vấn đề an ninh"],"ans":"B"},{"n":45,"q":"Who most likely is Giovanni Marino?","qvi":"Giovanni Marino có khả năng là ai?","opts":["An actor","A politician","A writer","A photographer"],"vi":["Diễn viên","Chính trị gia","Nhà văn","Nhiếp ảnh gia"],"ans":"A"},{"n":46,"q":"What will the man send in an e-mail?","qvi":"Người đàn ông sẽ gửi gì qua email?","opts":["A revised contract","A reimbursement form","An invitation to a video conference","Directions to a location"],"vi":["Hợp đồng sửa đổi","Mẫu hoàn tiền","Lời mời tham gia cuộc họp trực tuyến","Chỉ đường đến một địa điểm"],"ans":"A"}],"a":"E26-T04-44-46.mp3"},{"ns":[47,49],"script":[["M1","Hello, Usha. Hi, Pablo.","Chào Usha. Chào Pablo."],["W","Hey, Konstantin. We're talking about our thoughts on the new company policy for remote workers. On the days I have to come into the office, I always worry about finding an appropriate workstation.","Chào Konstantin. Chúng tôi đang nói về suy nghĩ của mình về chính sách công ty mới dành cho nhân viên làm việc từ xa. Vào những ngày tôi phải đến văn phòng, tôi luôn lo lắng về việc tìm một chỗ làm việc phù hợp."],["M2","Yeah, I don't like the unpredictability either. Why can't we just sign up for our workstation sometime in advance? What do you think about it?","Vâng, tôi cũng không thích sự không chắc chắn đó. Tại sao chúng ta không thể đăng ký chỗ làm việc trước? Bạn nghĩ sao?"],["M1","These are good points. Let's all go to the director to discuss this with her.","Những điểm tốt đấy. Hãy cùng đến gặp giám đốc để thảo luận với bà ấy."],["M2","I believe she's in her office, so now's a good time.","Tôi tin bà ấy đang ở văn phòng, vậy bây giờ là lúc tốt."],["W","Oh, I can't go now. I have a report to finalize by noon.","Ồ, tôi không thể đi bây giờ. Tôi có báo cáo cần hoàn tất trước trưa."]],"qs":[{"n":47,"q":"What are the speakers discussing?","qvi":"Những người nói đang thảo luận về điều gì?","opts":["A conference schedule","A company policy","A catering menu","A supply order"],"vi":["Lịch hội nghị","Chính sách công ty","Thực đơn đặt tiệc","Đơn đặt hàng"],"ans":"B"},{"n":48,"q":"What do the men want to do?","qvi":"Những người đàn ông muốn làm gì?","opts":["Rent a car","Go to a restaurant","Speak with a manager","Change some flight reservations"],"vi":["Thuê một chiếc xe","Đi đến một nhà hàng","Nói chuyện với người quản lý","Thay đổi đặt vé máy bay"],"ans":"C"},{"n":49,"q":"What does the woman say she needs to do now?","qvi":"Người phụ nữ nói cô ấy cần làm gì bây giờ?","opts":["Work on a report","Meet with a client","Print some materials","Check her e-mails"],"vi":["Làm việc trong một báo cáo","Gặp khách hàng","In một số tài liệu","Kiểm tra email"],"ans":"A"}],"a":"E26-T04-47-49.mp3"},{"ns":[50,52],"script":[["W","OK, Mr. Jebreen. Here's your new library card. Remember that you can borrow books, CDs, and DVDs from our collection with it.","OK, ông Jebreen. Đây là thẻ thư viện mới của ông. Nhớ rằng ông có thể mượn sách, CD và DVD từ bộ sưu tập của chúng tôi bằng nó."],["M","Thank you. I read somewhere that people can also borrow digital items.","Cảm ơn. Tôi đọc đâu đó rằng mọi người cũng có thể mượn các mặt hàng kỹ thuật số."],["W","Yes! We offer the Cloud-Camel application. All you have to do is download the app and use the information on your card to set up an account.","Vâng! Chúng tôi cung cấp ứng dụng Cloud-Camel. Tất cả những gì ông phải làm là tải ứng dụng và sử dụng thông tin trên thẻ để thiết lập tài khoản."],["M","That's great. I go on a business trip every month, so having easy access to online content will be convenient.","Tuyệt vời. Tôi đi công tác mỗi tháng, vì vậy việc dễ dàng truy cập nội dung trực tuyến sẽ tiện lợi."]],"qs":[{"n":50,"q":"Who most likely is the woman?","qvi":"Người phụ nữ có khả năng là ai nhất?","opts":["A journalist","A librarian","A musician","A software developer"],"vi":["Một nhà báo","Một thủ thư","Một nhạc sĩ","Một nhà phát triển phần mềm"],"ans":"B"},{"n":51,"q":"What does the woman recommend that the man do?","qvi":"Người phụ nữ khuyên người đàn ông nên làm gì?","opts":["Consult a manual","Sign up for a class","Listen to some music","Use a particular mobile app"],"vi":["Tham khảo sách hướng dẫn","Đăng ký một lớp học","Nghe nhạc","Sử dụng một ứng dụng di động cụ thể"],"ans":"D"},{"n":52,"q":"What does the man say happens each month?","qvi":"Người đàn ông nói điều gì xảy ra mỗi tháng?","opts":["He publishes a blog post.","He meets with a social group.","He travels for work.","He volunteers for a community event."],"vi":["Anh ấy đăng một bài viết trên blog.","Anh ấy gặp gỡ một nhóm xã hội.","Anh ấy đi công tác.","Anh ấy tình nguyện tham gia một sự kiện cộng đồng."],"ans":"C"}],"a":"E26-T04-50-52.mp3"},{"ns":[53,55],"script":[["W","Have you reviewed the data from the workplace survey? You really should. It looks like most staff feel positive about the direction that the company is going in. But almost 40 percent feel like their individual contributions aren't being recognized.","Bạn đã xem xét dữ liệu từ cuộc khảo sát nơi làm việc chưa? Bạn thực sự nên làm vậy. Có vẻ như hầu hết nhân viên cảm thấy tích cực về hướng đi của công ty. Nhưng gần 40 phần trăm cảm thấy những đóng góp cá nhân của họ không được công nhận."],["M","Well, the company's certainly had other priorities. I wonder how the management team's going to respond.","Chà, công ty chắc chắn có những ưu tiên khác. Tôi tự hỏi đội ngũ quản lý sẽ phản ứng thế nào."],["W","I've suggested many times that they give out awards every quarter for exceptional performance. Maybe now they'll finally start doing it.","Tôi đã gợi ý nhiều lần rằng họ nên trao giải thưởng hàng quý cho hiệu suất xuất sắc. Có lẽ bây giờ họ cuối cùng sẽ bắt đầu làm điều đó."]],"qs":[{"n":53,"q":"What does the woman want the man to look at?","qvi":"Người phụ nữ muốn người đàn ông xem gì?","opts":["A marketing plan","A conference calendar","Schedule changes","Survey results"],"vi":["Kế hoạch tiếp thị","Lịch hội nghị","Thay đổi lịch trình","Kết quả khảo sát"],"ans":"D"},{"n":54,"q":"What does the man imply when he says, “the company's certainly had other priorities”?","qvi":"Người đàn ông ngụ ý gì khi nói, “Công ty chắc chắn đã có những ưu tiên khác”?","opts":["His workload has decreased.","He is not responsible for some results.","Some criticism is accurate.","Some decisions led to a successful outcome."],"vi":["Khối lượng công việc của anh ấy đã giảm.","Anh ấy không chịu trách nhiệm về một số kết quả.","Một số lời chỉ trích là chính xác.","Một số quyết định đã dẫn đến kết quả thành công."],"ans":"C"},{"n":55,"q":"What has the woman suggested in the past?","qvi":"Người phụ nữ đã đề xuất điều gì trong quá khứ?","opts":["Rewarding staff performance","Extending business hours","Encouraging professional development","Organizing team-building events"],"vi":["Khen thưởng thành tích của nhân viên","Kéo dài giờ làm việc","Khuyến khích phát triển chuyên môn","Tổ chức các sự kiện xây dựng đội nhóm"],"ans":"A"}],"a":"E26-T04-53-55.mp3"},{"ns":[56,58],"script":[["W1","Hi, Ajijola. As I mentioned on the phone, my colleague and I recently started a clothing company and are hoping your branding firm can help us promote our line of athletic apparel. You think we should focus on advertising on social media, right?","Chào, Ajijola. Như tôi đã đề cập qua điện thoại, đồng nghiệp của tôi và tôi gần đây đã thành lập một công ty quần áo và hy vọng công ty thương hiệu của bạn có thể giúp chúng tôi quảng bá dòng quần áo thể thao. Bạn nghĩ chúng ta nên tập trung vào quảng cáo trên mạng xã hội, phải không?"],["M","Right. Contrary to popular belief, television is definitely not the entire advertising landscape. Advertising on the Internet is also a great way for a company to increase its visibility.","Đúng vậy. Trái với niềm tin phổ biến, truyền hình chắc chắn không phải là toàn bộ bối cảnh quảng cáo. Quảng cáo trên Internet cũng là một cách tuyệt vời để công ty tăng khả năng hiển thị."],["W2","I heard you recommended working with an online influencer.","Tôi nghe bạn khuyến nghị làm việc với một người ảnh hưởng trực tuyến."],["M","Yes—Saskia Hoffman. Saskia's very knowledgeable about exercise, and lots of people use her online exercise routines. Her viewers will pay attention to what she recommends and wears.","Vâng—Saskia Hoffman. Saskia rất am hiểu về tập luyện, và nhiều người sử dụng các bài tập trực tuyến của cô ấy. Khán giả của cô ấy sẽ chú ý đến những gì cô ấy khuyến nghị và mặc."]],"qs":[{"n":56,"q":"What type of business do the women own?","qvi":"Những người phụ nữ sở hữu loại hình kinh doanh nào?","opts":["A hair salon","A recording studio","A clothing company","A fitness center"],"vi":["Tiệm làm tóc","Studio thu âm","Một công ty quần áo","Trung tâm thể hình"],"ans":"C"},{"n":57,"q":"What does the man say regarding television?","qvi":"Người đàn ông nói gì về truyền hình?","opts":["It is an industry he once worked in.","It reaches more people than magazines.","It needs more programs about sports.","It is not the only advertising platform available."],"vi":["Đó là ngành anh ấy từng làm việc","Nó tiếp cận được nhiều người hơn tạp chí","Nó cần nhiều chương trình về thể thao hơn","Nó không phải nền tảng quảng cáo duy nhất"],"ans":"D"},{"n":58,"q":"According to the man, why would Saskia Hoffman be a good choice?","qvi":"Theo người đàn ông, tại sao Saskia Hoffman là lựa chọn tốt?","opts":["She recently won an award.","She lives nearby.","She charges affordable rates.","She is well known in her field."],"vi":["Cô ấy vừa nhận giải thưởng","Cô ấy sống gần đây","Cô ấy tính giá phải chăng","Cô ấy nổi tiếng trong lĩnh vực của mình"],"ans":"D"}],"a":"E26-T04-56-58.mp3"},{"ns":[59,61],"script":[["W","Hi, Shinji. I wanted to ask you about the order we got from the department store chain. You know, the one that placed an order for 5,000 jigsaw puzzles?","Chào, Shinji. Tôi muốn hỏi bạn về đơn hàng chúng ta nhận được từ chuỗi cửa hàng bách hóa. Bạn biết đấy, cái đặt hàng 5.000 câu đố ghép hình?"],["M","Yes. They want the order in a week so they can stock them before the holiday.","Vâng. Họ muốn đơn hàng trong một tuần để có thể dự trữ trước kỳ nghỉ."],["W","A week is not a long time.","Một tuần không phải là thời gian dài."],["M","We've had short timelines before. Anyway, our illustrators sent some new puzzle illustrations, right? I heard they're making a special edition.","Chúng ta đã có thời hạn ngắn trước đây. Dù sao, các họa sĩ minh họa của chúng ta đã gửi một số hình minh họa xếp hình mới, phải không? Tôi nghe nói họ đang làm một phiên bản đặc biệt."],["W","Yes, and I'm so excited! I've got the sketches right here. Let me show you.","Vâng, và tôi rất hào hứng! Tôi có bản phác thảo ngay đây. Để tôi cho bạn xem."]],"qs":[{"n":59,"q":"What does the speakers' company manufacture?","qvi":"Công ty của những người nói sản xuất gì?","opts":["Art supplies","Puzzles","Shipping materials","Power tools"],"vi":["Vật liệu mỹ thuật","Trò chơi xếp hình","Vật liệu vận chuyển","Dụng cụ điện"],"ans":"B"},{"n":60,"q":"What does the woman imply when she says, “A week is not a long time”?","qvi":"Người phụ nữ ngụ ý điều gì khi nói “Một tuần không phải là lâu đâu”?","opts":["Some prices will likely increase.","Some temporary employees have been hired.","A colleague's work is excellent.","An order may not be filled."],"vi":["Giá có thể tăng","Một số nhân viên tạm thời đã được thuê","Một đồng nghiệp làm việc xuất sắc","Một đơn hàng có thể không được hoàn tất"],"ans":"D"},{"n":61,"q":"What will the woman do next?","qvi":"Người phụ nữ sẽ làm gì tiếp theo?","opts":["Review a contract","Print out an invoice","Share some illustrations","Confirm a client meeting"],"vi":["Xem lại hợp đồng","In hóa đơn","Chia sẻ một số hình minh họa","Xác nhận cuộc họp với khách hàng"],"ans":"C"}],"a":"E26-T04-59-61.mp3"},{"ns":[62,64],"script":[["M","Hi, Ms. Rossi. I understand you're concerned about a charge that appears on the statement for your business account.","Chào, bà Rossi. Tôi hiểu bà đang lo lắng về một khoản phí xuất hiện trên bảng kê khai tài khoản kinh doanh của bà."],["W","Yes, I have a question about the charge on May 3. I don't remember purchasing anything for that amount.","Vâng, tôi có câu hỏi về khoản phí vào ngày 3 tháng 5. Tôi không nhớ mua bất cứ thứ gì với số tiền đó."],["M","Let me review your statement now. Hmm. It looks like that purchase was made abroad. So an international transaction fee was added to the purchase amount.","Để tôi xem lại bảng kê của bà ngay. Hmm. Có vẻ như giao dịch đó được thực hiện ở nước ngoài. Vì vậy phí giao dịch quốc tế đã được thêm vào số tiền mua."],["W","Oh, yes—I was out of the country at that time. Thanks for clarifying. Can you provide me with a list of all the bank fees for transactions made abroad?","Ồ, vâng—Tôi đã ra khỏi nước lúc đó. Cảm ơn vì đã làm rõ. Ông có thể cung cấp cho tôi danh sách tất cả các phí ngân hàng cho các giao dịch thực hiện ở nước ngoài không?"],["M","Yes, of course. Here's a document that lists all the information.","Vâng, tất nhiên. Đây là tài liệu liệt kê tất cả thông tin."]],"qs":[{"n":62,"q":"Where does the man most likely work?","qvi":"Người đàn ông có khả năng làm việc ở đâu?","opts":["At an airport","At a bank","At a real estate agency","At a department store"],"vi":["Sân bay","Ngân hàng","Đại lý bất động sản","Cửa hàng bách hóa"],"ans":"B"},{"n":63,"q":"Look at the graphic. Which amount does the woman ask about?","qvi":"Nhìn vào biểu đồ. Người phụ nữ hỏi về khoản tiền nào?","opts":["$203.00","$350.00","$75.50","$83.15"],"vi":["$203.00","$350.00","$75.50","$83.15"],"ans":"A"},{"n":64,"q":"What does the man give the woman?","qvi":"Người đàn ông đưa cho người phụ nữ cái gì?","opts":["An updated statement","A list of fees","A discount card","A brochure"],"vi":["Sao kê đã cập nhật","Danh sách các khoản phí","Thẻ giảm giá","Tờ rơi"],"ans":"B"}],"a":"E26-T04-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["M","Magali, were you able to reserve the performing arts center for the piano concert?","Magali, bạn có thể đặt chỗ trung tâm nghệ thuật biểu diễn cho buổi hòa nhạc piano không?"],["W","Yes. I booked their main auditorium for that day. They're sending me the contract.","Vâng. Tôi đã đặt hội trường chính của họ cho ngày đó. Họ đang gửi hợp đồng cho tôi."],["M","Thanks for doing that.","Cảm ơn vì đã làm điều đó."],["W","No problem. Hopefully, it'll be as successful as last year.","Không vấn đề. Hy vọng sẽ thành công như năm ngoái."],["M","We sold 2,000 tickets last year, but we had three celebrity performers. I'm worried we won't sell as many tickets this year.","Chúng ta bán 2.000 vé năm ngoái, nhưng chúng ta có ba nghệ sĩ nổi tiếng. Tôi lo lắng chúng ta sẽ không bán được nhiều vé năm nay."],["W","Well, Xinyu Gu is a very popular pianist. And she's staying after the concert to sign autographs. Which reminds me, where should we set up the table for that?","Chà, Xinyu Gu là một nghệ sĩ piano rất nổi tiếng. Và cô ấy ở lại sau buổi hòa nhạc để ký tặng. Điều đó nhắc tôi, chúng ta nên đặt bàn cho việc đó ở đâu?"],["M","Good question. Hmm. The café should be closed by then. Let's set it up next to the café.","Câu hỏi hay. Hmm. Quán cà phê nên đóng cửa lúc đó. Hãy đặt nó bên cạnh quán cà phê."]],"qs":[{"n":65,"q":"What does the man thank the woman for doing?","qvi":"Người đàn ông cảm ơn người phụ nữ vì điều gì?","opts":["Printing programs","Setting up lighting","Reserving a venue","Paying a performer"],"vi":["In chương trình","Lắp đặt hệ thống ánh sáng","Đặt chỗ địa điểm","Trả tiền cho người biểu diễn"],"ans":"C"},{"n":66,"q":"What does the man say he is worried about?","qvi":"Người đàn ông nói rằng anh ấy lo lắng về điều gì?","opts":["Reviews from critics","Ticket sales","A performance schedule","The cost of merchandise"],"vi":["Bài đánh giá từ giới phê bình","Doanh số bán vé","Lịch diễn","Chi phí hàng hóa"],"ans":"B"},{"n":67,"q":"Look at the graphic. Where will a table be set up?","qvi":"Nhìn vào biểu đồ. Bàn sẽ được đặt ở vị trí nào?","opts":["At location 1","At location 2","At location 3","At location 4"],"vi":["Vị trí 1","Vị trí 2","Vị trí 3","Vị trí 4"],"ans":"D"}],"a":"E26-T04-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["M","Welcome to the garden center. Can I help you?","Chào mừng đến với trung tâm vườn. Tôi có thể giúp gì cho bạn?"],["W","Hi. I've started growing rose bushes, and I've heard they require special care. Are there any products you can recommend?","Chào. Tôi đã bắt đầu trồng bụi hoa hồng, và tôi nghe chúng cần chăm sóc đặc biệt. Có sản phẩm nào bạn có thể khuyến nghị không?"],["M","Yes! But first, I'd like to show you a great resource on our Web site. Have you seen our blog?","Vâng! Nhưng trước tiên, tôi muốn cho bạn xem một tài nguyên tuyệt vời trên trang web của chúng tôi. Bạn đã xem blog của chúng tôi chưa?"],["W","No, I haven't.","Không, chưa."],["M","We have monthly posts on many gardening topics, and there's a recent one about growing roses.","Chúng tôi có bài đăng hàng tháng về nhiều chủ đề làm vườn, và có một bài gần đây về trồng hoa hồng."],["W","I'll check it out! Thanks so much.","Tôi sẽ kiểm tra! Cảm ơn rất nhiều."],["M","You're welcome. Now— let me show you our fertilizers. They're in aisle six.","Không có chi. Bây giờ— để tôi cho bạn xem phân bón của chúng tôi. Chúng ở lối đi sáu."]],"qs":[{"n":68,"q":"Why is the woman at the garden center?","qvi":"Tại sao người phụ nữ ở trung tâm làm vườn?","opts":["To enroll in a course","To join a gardening club","To buy some supplies","To return a purchase"],"vi":["Đăng ký một khóa học","Tham gia câu lạc bộ làm vườn","Mua một số vật dụng","Trả lại hàng"],"ans":"C"},{"n":69,"q":"Look at the graphic. Which month's post will the woman most likely read?","qvi":"Nhìn vào biểu đồ. Bài đăng của tháng nào người phụ nữ có khả năng đọc?","opts":["May's post","June's post","July's post","August's post"],"vi":["Bài đăng tháng 5","Bài đăng tháng 6","Bài đăng tháng 7","Bài đăng tháng 8"],"ans":"A"},{"n":70,"q":"What kind of products will the man show to the woman?","qvi":"Người đàn ông sẽ giới thiệu cho người phụ nữ loại sản phẩm nào?","opts":["Indoor plants","Plant fertilizers","Gardening tools","Irrigation systems"],"vi":["Cây trồng trong nhà","Phân bón cho cây trồng","Dụng cụ làm vườn","Hệ thống tưới tiêu"],"ans":"B"}],"a":"E26-T04-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Attention, Casella Transit customers. Maintenance work on the red and yellow lines will begin next week. You can expect some disruptions to regular service, so please plan ahead. Use the latest version of our mobile phone application for real-time updates. You can receive notifications regarding delays if your train is impacted. Want to save on commuter rides? Purchase your e-ticket through the mobile app as well. Printing a ticket at a kiosk is now subject to additional fees.","Khách hàng của Casella Transit chú ý. Công việc bảo trì trên tuyến đỏ và vàng sẽ bắt đầu vào tuần tới. Bạn có thể mong đợi một số gián đoạn đối với dịch vụ thông thường, vì vậy hãy lập kế hoạch trước. Sử dụng phiên bản mới nhất của ứng dụng điện thoại di động của chúng tôi để cập nhật thời gian thực. Bạn có thể nhận thông báo liên quan đến sự chậm trễ nếu tàu của bạn bị ảnh hưởng. Muốn tiết kiệm cho các chuyến đi làm? Mua vé điện tử qua ứng dụng di động cũng vậy. In vé tại ki-ốt bây giờ phải chịu phí bổ sung."]],"qs":[{"n":71,"q":"What field does the speaker most likely work in?","qvi":"Người nói có khả năng làm việc trong lĩnh vực nào?","opts":["Finance","Transportation","Construction","Robotics"],"vi":["Tài chính","Giao thông vận tải","Xây dựng","Người máy"],"ans":"B"},{"n":72,"q":"What does the speaker say the listeners can receive notifications about?","qvi":"Người nói cho biết người nghe có thể nhận thông báo về điều gì?","opts":["Route changes","Mobile app updates","New products","Schedule delays"],"vi":["Thay đổi tuyến đường","Cập nhật ứng dụng điện thoại","Sản phẩm mới","Trì hoãn lịch trình"],"ans":"D"},{"n":73,"q":"According to the speaker, how can the listeners reduce a cost?","qvi":"Theo người nói, người nghe có thể giảm chi phí bằng cách nào?","opts":["By purchasing a digital ticket","By reserving multiple permits","By traveling at less busy hours","By joining a loyalty program"],"vi":["Mua vé điện tử","Đặt nhiều giấy phép","Đi lại vào giờ ít đông","Tham gia chương trình khách hàng thân thiết"],"ans":"A"}],"a":"E26-T04-71-73.mp3"},{"ns":[74,76],"script":[["","Good morning, Glenman House Living Museum staff. Recently, researchers discovered the original plans for the house's gardens from the eighteenth century. So, we're going to restore the gardens based on those plans! Even though we have the original designs, making an authentic re-creation won't be an easy task. We don't know what specific varieties of plants were grown back then. That's why we're so lucky to have Vivek Hazarika consulting on this project. As a gardener who has managed the grounds of many historic estates, he has extensive expertise in what would have been planted at the time.","Chào buổi sáng, nhân viên Bảo tàng Glenman House Living. Gần đây, các nhà nghiên cứu đã phát hiện ra kế hoạch gốc cho khu vườn của ngôi nhà từ thế kỷ 18. Vì vậy, chúng ta sẽ khôi phục khu vườn dựa trên những kế hoạch đó! Mặc dù chúng ta có thiết kế gốc, việc tạo ra một bản sao chân thực sẽ không phải là nhiệm vụ dễ dàng. Chúng ta không biết những giống cây cụ thể nào được trồng lúc đó. Đó là lý do tại sao chúng ta may mắn có Vivek Hazarika tư vấn cho dự án này. Là một người làm vườn đã quản lý khuôn viên của nhiều bất động sản lịch sử, anh ấy có chuyên môn rộng lớn về những gì sẽ được trồng vào thời điểm đó."]],"qs":[{"n":74,"q":"What is the purpose of the meeting?","qvi":"Mục đích của cuộc họp là gì?","opts":["To explain a restoration project","To prepare for a public event","To train some new tour guides","To recruit some volunteers"],"vi":["Giải thích dự án trùng tu","Chuẩn bị cho một sự kiện công cộng","Huấn luyện một số hướng dẫn viên mới","Tuyển một số tình nguyện viên"],"ans":"A"},{"n":75,"q":"According to the speaker, why will a task be challenging?","qvi":"Theo người nói, tại sao một nhiệm vụ sẽ khó khăn?","opts":["Funding has not been secured.","Unfavorable weather is predicted.","Some permits have been delayed.","Some important information is missing."],"vi":["Kinh phí chưa được đảm bảo.","Dự báo thời tiết không thuận lợi.","Một số giấy phép bị chậm.","Một số thông tin quan trọng bị thiếu."],"ans":"D"},{"n":76,"q":"Who is Vivek Hazarika?","qvi":"Vivek Hazarika là ai?","opts":["An architect","A gardener","A salesperson","An archaeologist"],"vi":["Kiến trúc sư","Người làm vườn","Nhân viên bán hàng","Nhà khảo cổ"],"ans":"B"}],"a":"E26-T04-74-76.mp3"},{"ns":[77,79],"script":[["","Welcome, new sales representatives, to today's session on cold calling, a sales technique where we call potential clients who haven't heard of us yet. Toward the end of the session you'll each be given a list of prospective parties to call. Now, the people you're contacting are busy and may not be receptive. Your job's to persuade them that what you have to say is worth their while. Be friendly and avoid using scripts. Now we'll listen to some cold call recordings to learn what works and what doesn't.","Chào mừng, các đại diện bán hàng mới, đến buổi học hôm nay về cuộc gọi lạnh, một kỹ thuật bán hàng nơi chúng ta gọi cho các khách hàng tiềm năng chưa từng nghe về chúng ta. Vào cuối buổi học, mỗi người sẽ được đưa danh sách các bên tiềm năng để gọi. Bây giờ, những người bạn liên lạc đang bận rộn và có thể không tiếp nhận. Công việc của bạn là thuyết phục họ rằng những gì bạn nói đáng giá thời gian của họ. Hãy thân thiện và tránh sử dụng kịch bản. Bây giờ chúng ta sẽ nghe một số bản ghi cuộc gọi lạnh để học những gì hiệu quả và những gì không."]],"qs":[{"n":77,"q":"What is the purpose of the session?","qvi":"Mục đích của buổi họp là gì?","opts":["To discuss customer feedback","To explain an attendance policy","To discourage mobile phone use","To train new sales staff"],"vi":["Thảo luận phản hồi của khách hàng","Giải thích chính sách điểm danh","Hạn chế việc dùng điện thoại","Đào tạo nhân viên bán hàng mới"],"ans":"D"},{"n":78,"q":"What will be on a list that the listeners will receive?","qvi":"Danh sách người nghe nhận được sẽ bao gồm gì?","opts":["Potential clients to contact","Employees who have exceeded sales goals","Products offered by the company","Departments within the company"],"vi":["Khách hàng tiềm năng","Nhân viên đạt vượt chỉ tiêu","Sản phẩm công ty cung cấp","Các phòng ban trong công ty"],"ans":"A"},{"n":79,"q":"What will the listeners do next?","qvi":"Người nghe sẽ làm gì tiếp theo?","opts":["Memorize prepared scripts","Listen to recorded calls","Take a brief survey","Brainstorm conversational topics"],"vi":["Học thuộc bài nói mẫu","Nghe các cuộc gọi ghi âm","Làm khảo sát ngắn","Động não chủ đề hội thoại"],"ans":"B"}],"a":"E26-T04-77-79.mp3"},{"ns":[80,82],"script":[["","Ms. Stewart, this is Rodrigo Gomez, president of Gomez and Sons. I want to apologize personally for the problems your restaurant experienced using our patio umbrellas. At our company, we pride ourselves on doing everything in-house, from graphic design to production. This gives us greater control over the quality of our products. But we do use outside suppliers for parts. Apparently, we received some inferior metal components. We will send you a replacement set of umbrellas at no cost today, constructed with new metal parts.","Bà Stewart, đây là Rodrigo Gomez, chủ tịch của Gomez and Sons. Tôi muốn xin lỗi cá nhân về những vấn đề mà nhà hàng của bà gặp phải khi sử dụng ô dù sân hiên của chúng tôi. Tại công ty chúng tôi, chúng tôi tự hào về việc làm mọi thứ nội bộ, từ thiết kế đồ họa đến sản xuất. Điều này cho chúng tôi quyền kiểm soát lớn hơn về chất lượng sản phẩm. Nhưng chúng tôi sử dụng nhà cung cấp bên ngoài cho các bộ phận. Rõ ràng, chúng tôi đã nhận được một số thành phần kim loại kém chất lượng. Chúng tôi sẽ gửi cho bà một bộ ô dù thay thế miễn phí hôm nay, được xây dựng với các bộ phận kim loại mới."]],"qs":[{"n":80,"q":"What does the speaker's company sell?","qvi":"Công ty người nói bán gì?","opts":["Sound systems","Light fixtures","Umbrellas","Refrigerators"],"vi":["Hệ thống âm thanh","Đèn chiếu sáng","Ô dù","Tủ lạnh"],"ans":"C"},{"n":81,"q":"Why does the speaker say, “we do use outside suppliers for parts”?","qvi":"Tại sao người nói lại nói “chúng tôi có dùng nhà cung cấp bên ngoài cho linh kiện”?","opts":["To recommend a different company","To justify an increased price","To explain the source of a problem","To decline a proposal"],"vi":["Đề xuất một công ty khác","Giải thích giá tăng","Giải thích nguyên nhân của vấn đề","Từ chối một đề xuất"],"ans":"C"},{"n":82,"q":"What does the speaker say he will do today?","qvi":"Người nói nói rằng hôm nay ông ấy sẽ làm gì?","opts":["Interview some applicants","Send a shipment","Train some staff","Update a spreadsheet"],"vi":["Phỏng vấn ứng viên","Gửi một kiện hàng","Huấn luyện nhân viên","Cập nhật bảng tính"],"ans":"B"}],"a":"E26-T04-80-82.mp3"},{"ns":[83,85],"script":[["","Temp-Time Work Solutions has hundreds of qualified, temporary workers available to meet any of your staffing needs. Please call us to help your business fill open positions. We are the largest temp agency in the region, with branch offices in six locations. Let Temp-Time help you find the right person to complete just about any job! Call us at 555-0145 and mention this ad to get a twenty percent discount off our fee.","Temp-Time Work Solutions có hàng trăm công nhân tạm thời đủ điều kiện sẵn sàng để đáp ứng bất kỳ nhu cầu nhân sự nào của bạn. Vui lòng gọi cho chúng tôi để giúp doanh nghiệp của bạn lấp đầy các vị trí mở. Chúng tôi là cơ quan tạm thời lớn nhất trong khu vực, với văn phòng chi nhánh ở sáu địa điểm. Hãy để Temp-Time giúp bạn tìm người phù hợp để hoàn thành gần như bất kỳ công việc nào! Gọi cho chúng tôi tại 555-0145 và đề cập đến quảng cáo này để nhận giảm 20 phần trăm phí của chúng tôi."]],"qs":[{"n":83,"q":"What type of business is being advertised?","qvi":"Loại hình doanh nghiệp nào đang được quảng cáo?","opts":["An event planning company","A financial advising service","An attorney's office","A staffing agency"],"vi":["Công ty tổ chức sự kiện","Dịch vụ tư vấn tài chính","Văn phòng luật sư","Công ty cung ứng nhân sự"],"ans":"D"},{"n":84,"q":"What aspect of a business does the speaker emphasize?","qvi":"Người nói nhấn mạnh điều gì về doanh nghiệp?","opts":["Its large size","Its reasonable prices","Its business hours","Its long history"],"vi":["Quy mô lớn","Giá cả hợp lý","Giờ hoạt động","Lịch sử lâu đời"],"ans":"A"},{"n":85,"q":"How can the listeners receive a discount?","qvi":"Người nghe có thể nhận được giảm giá bằng cách nào?","opts":["By mentioning an advertisement","By referring friends","By paying with a credit card","By using a coupon"],"vi":["Nhắc đến quảng cáo","Giới thiệu bạn bè","Thanh toán bằng thẻ tín dụng","Dùng phiếu giảm giá"],"ans":"A"}],"a":"E26-T04-83-85.mp3"},{"ns":[86,88],"script":[["","I've just received details about this year's hospitality conference. It looks like it'll be particularly informative this year. It'll be held at the end of the month. Now, I know I've set your project due dates for the end of the month as well, but this is an important opportunity. The conference will feature an expo of vendors who serve hotel chains, which could be useful given that we'll be opening hotels in two new cities next year! Speaking of which, Thilo visited both of those construction sites last week and is now going to give us a progress report.","Tôi vừa nhận được chi tiết về hội nghị khách sạn năm nay. Có vẻ như năm nay sẽ đặc biệt hữu ích. Nó sẽ được tổ chức vào cuối tháng. Bây giờ, tôi biết tôi đã đặt ngày hạn dự án của bạn vào cuối tháng, nhưng đây là cơ hội quan trọng. Hội nghị sẽ có triển lãm của các nhà cung cấp phục vụ chuỗi khách sạn, điều này có thể hữu ích vì chúng ta sẽ mở khách sạn ở hai thành phố mới vào năm tới! Nói về điều đó, Thilo đã thăm cả hai công trường xây dựng đó tuần trước và bây giờ sẽ đưa ra báo cáo tiến độ cho chúng ta."]],"qs":[{"n":86,"q":"What does the speaker mean when he says, “this is an important opportunity”?","qvi":"Người nói muốn nói gì khi nói “đây là một cơ hội quan trọng”?","opts":["A new client has an urgent problem.","Some information is needed from the listeners.","Some deadlines are flexible.","The listeners have done a good job."],"vi":["Một khách hàng mới có vấn đề khẩn cấp.","Cần một số thông tin từ người nghe.","Một số thời hạn có thể linh hoạt.","Người nghe đã làm tốt."],"ans":"C"},{"n":87,"q":"What will the speaker's business do next year?","qvi":"Sang năm doanh nghiệp của người nói sẽ làm gì?","opts":["Redesign advertising materials","Open new locations","Hire a new vendor","Implement a security policy"],"vi":["Thiết kế lại tài liệu quảng cáo","Mở thêm chi nhánh","Thuê nhà cung cấp mới","Triển khai chính sách an ninh"],"ans":"B"},{"n":88,"q":"What will Thilo do next?","qvi":"Thilo sẽ làm gì tiếp theo?","opts":["Practice his conference presentation","Provide a construction update","Summarize some financial data","Contact a supply vendor"],"vi":["Luyện bài thuyết trình","Cung cấp cập nhật về xây dựng","Tóm tắt dữ liệu tài chính","Liên hệ với nhà cung cấp"],"ans":"B"}],"a":"E26-T04-86-88.mp3"},{"ns":[89,91],"script":[["","Welcome to the annual Soundtrack Music Awards show. This year, we're streaming this event live over the Internet for the very first time! Tonight's honoree, Olga Alabi, founded the I-Beat music label in 1996. She has worked tirelessly to bring original soundtrack music to film audiences around the world. Over the years, she has been responsible for discovering and developing some of today's leading composers. In fact, after Ms. Alabi receives her award, some of her most famous clients will perform for us.","Chào mừng đến với chương trình Giải thưởng Âm nhạc Soundtrack hàng năm. Năm nay, chúng tôi đang phát trực tiếp sự kiện này qua Internet lần đầu tiên! Người được vinh danh tối nay, Olga Alabi, đã thành lập nhãn hiệu âm nhạc I-Beat vào năm 1996. Bà ấy đã làm việc không mệt mỏi để mang nhạc nền gốc đến khán giả phim trên toàn thế giới. Qua nhiều năm, bà ấy chịu trách nhiệm phát hiện và phát triển một số nhà soạn nhạc hàng đầu ngày nay. Thực tế, sau khi bà Alabi nhận giải thưởng, một số khách hàng nổi tiếng nhất của bà sẽ biểu diễn cho chúng ta."]],"qs":[{"n":89,"q":"What does the speaker say is new about this year's event?","qvi":"Điều gì mới về sự kiện năm nay?","opts":["It takes place outdoors.","It is sponsored by a major publication.","It has been sold out for months.","It is being streamed live."],"vi":["Diễn ra ngoài trời","Được tài trợ bởi một tạp chí lớn","Cháy vé nhiều tháng","Được phát trực tiếp"],"ans":"D"},{"n":90,"q":"Why is Ms. Alabi being recognized?","qvi":"Tại sao bà Alabi được vinh danh?","opts":["She is a talented songwriter.","She invented a musical instrument.","She started a major record label.","She supports several charities."],"vi":["Bà ấy là nhạc sĩ tài năng","Bà ấy phát minh nhạc cụ","Bà ấy lập hãng thu âm lớn","Bà ấy hỗ trợ nhiều tổ chức từ thiện"],"ans":"C"},{"n":91,"q":"According to the speaker, what will happen after Ms. Alabi receives her award?","qvi":"Sau khi bà Alabi nhận giải sẽ có điều gì?","opts":["Photographs will be taken.","Dinner will be served.","Some musicians will perform.","Some interviews will be held."],"vi":["Chụp ảnh","Phục vụ bữa tối","Biểu diễn âm nhạc","Thực hiện phỏng vấn"],"ans":"C"}],"a":"E26-T04-89-91.mp3"},{"ns":[92,94],"script":[["","OK, team, let's discuss our first-quarter sales figures. Unfortunately, retail sales of our smartwatches and other products have continued to fall. Our president has proposed expanding the product line to include a virtual reality headset. And those have been popular lately. You can expect a lot more information at a future meeting. Next on the agenda, Raya will be demonstrating the new software we'll be using to track consumer purchasing trends.","OK, đội ngũ, hãy thảo luận về con số bán hàng quý đầu tiên của chúng ta. Thật không may, doanh số bán lẻ đồng hồ thông minh và các sản phẩm khác của chúng ta tiếp tục giảm. Chủ tịch của chúng ta đã đề xuất mở rộng dòng sản phẩm để bao gồm tai nghe thực tế ảo. Và những thứ đó rất phổ biến gần đây. Bạn có thể mong đợi nhiều thông tin hơn tại cuộc họp tương lai. Tiếp theo trên nghị trình, Raya sẽ trình diễn phần mềm mới mà chúng ta sẽ sử dụng để theo dõi xu hướng mua sắm của người tiêu dùng."]],"qs":[{"n":92,"q":"Which department does the speaker most likely work in?","qvi":"Người nói có khả năng làm việc trong bộ phận nào?","opts":["Sales","Accounting","Human resources","Information technology"],"vi":["Kinh doanh","Kế toán","Nhân sự","Công nghệ thông tin"],"ans":"A"},{"n":93,"q":"Why does the speaker say, “those have been popular lately”?","qvi":"Tại sao người nói nói “những thứ đó gần đây rất phổ biến”?","opts":["To express disbelief","To explain a shortage","To agree with a proposal","To make a correction"],"vi":["Để bày tỏ sự ngạc nhiên","Để giải thích việc thiếu hàng","Để đồng ý với đề xuất","Để sửa thông tin"],"ans":"C"},{"n":94,"q":"What will the listeners do next?","qvi":"Người nghe sẽ làm gì tiếp theo?","opts":["Take a lunch break","Ask questions about a policy","Read a report","View a demonstration"],"vi":["Nghỉ trưa","Hỏi về chính sách","Đọc báo cáo","Xem trình diễn"],"ans":"D"}],"a":"E26-T04-92-94.mp3"},{"ns":[95,97],"script":[["","Please follow me, and we'll begin today's tour. Now, I know not everyone who takes this all-access tour is a football fan. Many of our visitors are just curious about how a modern sports facility of this size operates. Well, you'll get to see that and much more. And fortunately, today's forecast shows a mix of sun and clouds, with no rain. That's just the right combination for spending some time outside on the field comfortably. Also, as a heads-up, a shuttle bus will meet us at the end of the tour to bring us all back to the parking lot.","Vui lòng theo tôi, và chúng ta sẽ bắt đầu tour hôm nay. Bây giờ, tôi biết không phải ai tham gia tour toàn quyền này cũng là fan bóng đá. Nhiều du khách của chúng tôi chỉ tò mò về cách một cơ sở thể thao hiện đại kích thước này hoạt động. Chà, bạn sẽ được thấy điều đó và nhiều hơn nữa. Và may mắn thay, dự báo hôm nay cho thấy sự kết hợp giữa nắng và mây, không mưa. Đó là sự kết hợp vừa phải để dành thời gian ngoài trời trên sân một cách thoải mái. Ngoài ra, như một lưu ý, một xe buýt đưa đón sẽ gặp chúng ta ở cuối tour để đưa tất cả chúng ta về bãi đậu xe."]],"qs":[{"n":95,"q":"Where are the listeners?","qvi":"Người nghe đang ở đâu?","opts":["At a farm","At a factory","At a museum","At a stadium"],"vi":["Trang trại","Nhà máy","Bảo tàng","Sân vận động"],"ans":"D"},{"n":96,"q":"Look at the graphic. When is the tour taking place?","qvi":"Theo biểu đồ, chuyến tham quan diễn ra vào ngày nào?","opts":["On Monday","On Tuesday","On Wednesday","On Thursday"],"vi":["Thứ Hai","Thứ Ba","Thứ Tư","Thứ Năm"],"ans":"A"},{"n":97,"q":"What will happen at the end of the tour?","qvi":"Điều gì sẽ xảy ra vào cuối chuyến tham quan?","opts":["Pictures will be taken.","Food will be served.","Gifts will be given out.","A shuttle bus will arrive."],"vi":["Chụp ảnh","Phục vụ đồ ăn","Tặng quà","Xe đưa đón sẽ đến"],"ans":"D"}],"a":"E26-T04-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","As you all know, we're hosting a large event tonight. It's a dinner party to celebrate the retirement of a longtime employee of Jalton Incorporated. The chefs are already prepping dinner, and I need you all to set up the ballroom. Here's the assignment list. There's just one change. Amanda couldn't make it, so Kota's covering for her and will take Amanda's assignment. Now, I have a meeting with a potential client at noon, but otherwise, I'll be available all day if anything comes up.","Như tất cả các bạn biết, chúng ta đang tổ chức một sự kiện lớn tối nay. Đó là bữa tiệc tối để kỷ niệm sự nghỉ hưu của một nhân viên lâu năm của Jalton Incorporated. Các đầu bếp đã chuẩn bị bữa tối, và tôi cần tất cả các bạn thiết lập phòng khiêu vũ. Đây là danh sách phân công. Chỉ có một thay đổi. Amanda không thể đến, vì vậy Kota đang thay thế cho cô ấy và sẽ đảm nhận phân công của Amanda. Bây giờ, tôi có cuộc họp với một khách hàng tiềm năng vào buổi trưa, nhưng ngoài ra, tôi sẽ sẵn sàng cả ngày nếu có gì xảy ra."]],"qs":[{"n":98,"q":"What type of event is being held tonight?","qvi":"Sự kiện diễn ra tối nay là gì?","opts":["A grand opening","A company anniversary","A retirement party","A wedding celebration"],"vi":["Khai trương","Kỷ niệm công ty","Tiệc nghỉ hưu","Lễ cưới"],"ans":"C"},{"n":99,"q":"Look at the graphic. Which assignment will Kota be responsible for?","qvi":"Theo bảng phân công, Kota sẽ chịu trách nhiệm cho việc gì?","opts":["Organizing the food-serving station","Hanging decorations","Creating flower arrangements","Setting up tables and chairs"],"vi":["Tổ chức khu phục vụ đồ ăn","Trang trí","Làm hoa trang trí","Sắp bàn ghế"],"ans":"B"},{"n":100,"q":"What does the speaker say she has to do at noon?","qvi":"Người nói nói rằng cô ấy phải làm gì vào buổi trưa?","opts":["Go to the airport","Pick up some tablecloths","Cook a meal","Attend a meeting"],"vi":["Ra sân bay","Lấy khăn trải bàn","Nấu ăn","Dự họp"],"ans":"D"}],"a":"E26-T04-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"Ms. Chiu recently announced that ------- is planning to retire in September.","opts":["her","hers","herself","she"],"ans":"D","xp":"she is planning to retire = cô ấy đang có kế hoạch nghỉ hưu\nher / hers: đại từ sở hữu, không làm chủ ngữ\nherself: đại từ phản thân\n→ Chọn (D)\nDịch: Bà Chiu gần đây thông báo rằng bà ấy dự định nghỉ hưu vào tháng 9."},{"n":102,"q":"Mr. Kashnitz will interview the applicants ------- the holiday.","opts":["above","before","among","along"],"ans":"B","xp":"before the holiday = trước kỳ nghỉ\nabove: phía trên\namong: giữa nhiều đối tượng\nalong: dọc theo\n→ Chọn (B)\nDịch: Ông Kashnitz sẽ phỏng vấn ứng viên trước kỳ nghỉ."},{"n":103,"q":"The real estate agent may ------- a buyer with a neighborhood analysis upon request.","opts":["providing","provide","provided","provides"],"ans":"B","xp":"may provide = có thể cung cấp (sau động từ khuyết thiếu “may” dùng động từ nguyên mẫu)\nproviding: V-ing\nprovided: quá khứ\nprovides: chia hiện tại cho chủ ngữ số ít\n→ Chọn (B)\nDịch: Môi giới có thể cung cấp bản phân tích khu vực cho người mua khi được yêu cầu."},{"n":104,"q":"The city’s development committee is looking for a ------- to plant a community garden.","opts":["flower","topic","location","show"],"ans":"C","xp":"a location to plant = địa điểm để trồng\nflower: hoa\ntopic: chủ đề\nshow: buổi diễn\n→ Chọn (C)\nDịch: Ủy ban phát triển của thành phố đang tìm địa điểm để trồng một khu vườn cộng đồng."},{"n":105,"q":"We hope our customer service team has answered your questions in a ------- manner.","opts":["satisfy","satisfactory","satisfaction","satisfactorily"],"ans":"B","xp":"in a satisfactory manner = một cách thỏa đáng (cần tính từ đứng trước danh từ “manner”)\nsatisfy: động từ\nsatisfaction: danh từ\nsatisfactorily: trạng từ (không đi với “manner”)\n→ Chọn (B)\nDịch: Chúng tôi hy vọng đội ngũ chăm sóc khách hàng đã trả lời câu hỏi của bạn theo cách thỏa đáng."},{"n":106,"q":"Mr. Hanley expressed interest in the position ------- held by Ms. Akello.","opts":["previously","slowly","widely","loosely"],"ans":"A","xp":"previously held = trước đây từng nắm giữ\nslowly / widely / loosely: sai nghĩa\n→ Chọn (A)\nDịch: Ông Hanley bày tỏ sự quan tâm đến vị trí trước đây do bà Akello đảm nhiệm."},{"n":107,"q":"Once Ms. Jeong ------- the contract, she will sign and return it to Allory Pharmaceuticals.","opts":["to receive","receives","was received","receiving"],"ans":"B","xp":"Once she receives the contract = mệnh đề thời gian, dùng hiện tại đơn (thay cho tương lai)\nto receive: nguyên mẫu\nwas received: bị động\nreceiving: V-ing\n→ Chọn (B)\nDịch: Khi nhận được hợp đồng, bà Jeong sẽ ký và gửi lại cho Allory Pharmaceuticals."},{"n":108,"q":"Ten board members plan to attend, which is just ------- to approve the proposal.","opts":["enough","several","most","those"],"ans":"A","xp":"just enough to approve = vừa đủ để phê duyệt\nseveral: vài\nmost: hầu hết\nthose: đại từ chỉ định\n→ Chọn (A)\nDịch: Mười thành viên hội đồng dự định tham dự, vừa đủ để thông qua đề xuất."},{"n":109,"q":"Mr. Aziz is often alone in the shop while his partner is out making a -------.","opts":["deliver","delivery","delivered","delivering"],"ans":"B","xp":"make a delivery = thực hiện giao hàng (sau mạo từ “a” cần danh từ)\ndeliver: động từ\ndelivered: quá khứ\ndelivering: V-ing\n→ Chọn (B)\nDịch: Ông Aziz thường ở một mình trong cửa hàng khi cộng sự của ông đi giao hàng."},{"n":110,"q":"The Pacific Coast Sunset Run has been ------- to August 31 because of bad weather.","opts":["canceled","combined","rescheduled","administered"],"ans":"C","xp":"been rescheduled to August 31 = được dời lịch sang ngày 31/8\ncanceled: hủy\ncombined: kết hợp\nadministered: quản lý\n→ Chọn (C)\nDịch: Cuộc chạy Pacific Coast Sunset Run đã được dời sang ngày 31/8 vì thời tiết xấu."},{"n":111,"q":"Graber hair and nail growth supplements come in ------- pill and liquid form.","opts":["these","both","almost","likely"],"ans":"B","xp":"come in both pill and liquid form = có ở cả hai dạng (both … and …)\nthese: những cái này\nalmost: gần như\nlikely: có khả năng\n→ Chọn (B)\nDịch: Thực phẩm bổ sung giúp mọc tóc và móng Graber có cả dạng viên và dạng lỏng."},{"n":112,"q":"The posters must be completed soon ------- they can be put up in advance of the gala.","opts":["so that","despite","whenever","as if"],"ans":"A","xp":"so that they can be put up = để mà\ndespite: mặc dù\nwhenever: bất cứ khi nào\nas if: như thể\n→ Chọn (A)\nDịch: Các áp phích phải được hoàn thành sớm để có thể được treo trước buổi dạ tiệc."},{"n":113,"q":"Mr. Olivero praised the film in his review, even though he ------- disliked its aesthetic style.","opts":["personal","personally","personals","person"],"ans":"B","xp":"personally disliked = cá nhân ông ấy không thích (trạng từ bổ nghĩa cho động từ)\npersonal: tính từ\npersonals: danh từ số nhiều\nperson: danh từ\n→ Chọn (B)\nDịch: Ông Olivero khen ngợi bộ phim trong bài đánh giá, mặc dù cá nhân ông ấy không thích phong cách thẩm mỹ của nó."},{"n":114,"q":"------- weeks of record-setting rain, expect only blue skies this weekend.","opts":["After","Besides","Opposite","Alongside"],"ans":"A","xp":"After weeks of rain = sau nhiều tuần mưa\nBesides: ngoài ra\nOpposite: đối diện\nAlongside: cùng với\n→ Chọn (A)\nDịch: Sau nhiều tuần mưa kỷ lục, cuối tuần này trời sẽ chỉ toàn nắng xanh."},{"n":115,"q":"The Serenica dining table comes with levelers ------- its stability on uneven surfaces.","opts":["ensure","ensures","to ensure","to be ensured"],"ans":"C","xp":"levelers to ensure stability = để đảm bảo (to V chỉ mục đích)\nensure / ensures: động từ chính (sai cấu trúc)\nto be ensured: bị động\n→ Chọn (C)\nDịch: Bàn ăn Serenica đi kèm chân cân bằng để đảm bảo độ ổn định trên bề mặt không bằng phẳng."},{"n":116,"q":"Applicants to any open position at Allcrest Engineering can expect a ------- within three business days.","opts":["degree","raise","change","response"],"ans":"D","xp":"expect a response = mong đợi phản hồi\ndegree: bằng cấp\nraise: tăng lương\nchange: thay đổi\n→ Chọn (D)\nDịch: Ứng viên cho bất kỳ vị trí nào đang tuyển tại Allcrest Engineering có thể mong đợi phản hồi trong vòng ba ngày làm việc."},{"n":117,"q":"------- prepares the patient’s medical records is required to maintain confidentiality.","opts":["Whoever","Who","Whose","What"],"ans":"A","xp":"Whoever prepares … is required = bất kỳ ai mà\nWho: thiếu tính bao quát\nWhose: sở hữu\nWhat: không chỉ người\n→ Chọn (A)\nDịch: Bất kỳ ai chuẩn bị hồ sơ bệnh án của bệnh nhân đều phải giữ bí mật."},{"n":118,"q":"Because of the high demand for our services, our office was ------- expanded last year.","opts":["significantly","tightly","remotely","identically"],"ans":"A","xp":"significantly expanded = mở rộng đáng kể\ntightly: chặt chẽ\nremotely: từ xa\nidentically: giống hệt\n→ Chọn (A)\nDịch: Do nhu cầu cao đối với dịch vụ của chúng tôi, văn phòng đã được mở rộng đáng kể vào năm ngoái."},{"n":119,"q":"The Terry Hoig Prize for ------- architecture was awarded to Ms. Helblon on Tuesday.","opts":["sustain","sustainable","sustainer","sustains"],"ans":"B","xp":"sustainable architecture = kiến trúc bền vững (tính từ bổ nghĩa cho danh từ)\nsustain: động từ\nsustainer: danh từ chỉ người\nsustains: động từ\n→ Chọn (B)\nDịch: Giải thưởng Terry Hoig về kiến trúc bền vững đã được trao cho bà Helblon vào thứ Ba."},{"n":120,"q":"We have been ------- problems with the thermostat in the western end of the warehouse.","opts":["experiencing","regarding","repurposing","establishing"],"ans":"A","xp":"have been experiencing problems = đang gặp vấn đề\nregarding: về việc\nrepurposing: tái sử dụng\nestablishing: thiết lập\n→ Chọn (A)\nDịch: Chúng tôi đã gặp vấn đề với bộ điều nhiệt ở đầu phía tây của nhà kho."},{"n":121,"q":"Two students from Wrisley University worked ------- on the design of the new library in Lorth Park.","opts":["collaborate","collaborative","collaboratively","collaborated"],"ans":"C","xp":"worked collaboratively = làm việc cùng nhau (trạng từ)\ncollaborate: động từ\ncollaborative: tính từ\ncollaborated: quá khứ\n→ Chọn (C)\nDịch: Hai sinh viên Đại học Wrisley đã hợp tác cùng nhau thiết kế thư viện mới ở Lorth Park."},{"n":122,"q":"The images displayed on our gallery’s Web site may not reflect the ------- colors of the artwork for sale.","opts":["loyal","smart","close","exact"],"ans":"D","xp":"exact colors = màu sắc chính xác\nloyal: trung thành\nsmart: thông minh\nclose: gần\n→ Chọn (D)\nDịch: Hình ảnh trên trang web của phòng tranh có thể không phản ánh màu sắc chính xác của tác phẩm đang bán."},{"n":123,"q":"At Beautyvale Cosmetics, our representatives answer customers’ ------- within 24 hours of receipt.","opts":["inquirers","inquired","to inquire","inquiries"],"ans":"D","xp":"answer customers’ inquiries = trả lời thắc mắc (sau sở hữu cách cần danh từ)\ninquirers: người hỏi\ninquired: quá khứ\nto inquire: nguyên mẫu\n→ Chọn (D)\nDịch: Tại Beautyvale Cosmetics, nhân viên của chúng tôi trả lời các thắc mắc của khách hàng trong vòng 24 giờ kể từ khi nhận được."},{"n":124,"q":"We would like to attend the retreat, but ------- we are unavailable on that date.","opts":["regrettably","scarcely","exceptionally","annually"],"ans":"A","xp":"regrettably = thật đáng tiếc là\nscarcely: hầu như không\nexceptionally: đặc biệt\nannually: hằng năm\n→ Chọn (A)\nDịch: Chúng tôi muốn tham dự buổi dã ngoại, nhưng thật đáng tiếc là chúng tôi không rảnh vào ngày đó."},{"n":125,"q":"In celebration of Ms. Tseng’s promotion, tea and cookies will be served ------- the meeting.","opts":["later","as soon as","following","in case of"],"ans":"C","xp":"served following the meeting = sau cuộc họp\nlater: sau đó (không đi trực tiếp với danh từ)\nas soon as: ngay khi\nin case of: trong trường hợp\n→ Chọn (C)\nDịch: Để chúc mừng bà Tseng được thăng chức, trà và bánh quy sẽ được phục vụ sau cuộc họp."},{"n":126,"q":"Beginning next month, all employees at Sartson Analytics will have the ------- of working from home two days per week.","opts":["place","combination","range","option"],"ans":"D","xp":"have the option of working = có lựa chọn\nplace: nơi chốn\ncombination: sự kết hợp\nrange: phạm vi\n→ Chọn (D)\nDịch: Bắt đầu từ tháng sau, tất cả nhân viên tại Sartson Analytics sẽ có lựa chọn làm việc tại nhà hai ngày mỗi tuần."},{"n":127,"q":"The accounting department’s new policy outlines the ------- process for the procurement of office equipment.","opts":["preferring","preferably","preferred","preferability"],"ans":"C","xp":"the preferred process = quy trình được ưu tiên\npreferring: V-ing\npreferably: trạng từ\npreferability: danh từ\n→ Chọn (C)\nDịch: Chính sách mới của phòng kế toán nêu rõ quy trình được ưu tiên cho việc mua sắm thiết bị văn phòng."},{"n":128,"q":"All documents ------- to the company merger will become available to the public within one year.","opts":["assigning","facilitating","pertaining","embarking"],"ans":"C","xp":"documents pertaining to = liên quan đến\nassigning: phân công\nfacilitating: tạo điều kiện\nembarking: bắt đầu\n→ Chọn (C)\nDịch: Tất cả các tài liệu liên quan đến việc sáp nhập công ty sẽ được công khai trong vòng một năm."},{"n":129,"q":"Granta Hospital has added several pediatric nurses to its staff as part of its new ------- with the Friel School of Nursing.","opts":["affiliation","affiliated","affiliating","affiliates"],"ans":"A","xp":"new affiliation with = mối liên kết với (sau tính từ “new” cần danh từ)\naffiliated: tính từ\naffiliating: V-ing\naffiliates: động từ\n→ Chọn (A)\nDịch: Bệnh viện Granta đã bổ sung một số y tá nhi khoa như một phần của mối liên kết mới với Trường Điều dưỡng Friel."},{"n":130,"q":"During checkout, cashiers must be able to scan purchased items accurately ------- field questions from customers.","opts":["but","for instance","although","as well as"],"ans":"D","xp":"accurately as well as field questions = vừa… vừa…\nbut: nhưng\nfor instance: ví dụ\nalthough: mặc dù\n→ Chọn (D)\nDịch: Khi thanh toán, thu ngân phải có khả năng quét hàng chính xác cũng như trả lời câu hỏi của khách hàng."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following article.","passage":"<h3>New Vietnamese Restaurant Opens</h3><p>SAN FRANCISCO (November 5)—Celebrity chef Eric Hoang <span class=\"blank\" data-n=\"131\">-------</span> his first restaurant, Ngon Mieng. It opened last week in the North Beach neighborhood. Ngon Mieng serves authentic Vietnamese cuisine and some innovative dishes developed by Chef Hoang. The restaurant took over the space once occupied by the restaurant Plantains, <span class=\"blank\" data-n=\"132\">-------</span> closed last year.</p><p>Chef Hoang won first place on the reality television show <i>Best Chefs in the U.S.</i> two years ago. <span class=\"blank\" data-n=\"133\">-------</span>. “After receiving the award, opening a restaurant became my dream,” he said. “I am excited to bring my culinary creations to the North Beach area.”</p><p>At the grand opening, diners echoed Chef Hoang’s enthusiasm for the <span class=\"blank\" data-n=\"134\">-------</span>. “Without a doubt, it was some of the best I’ve ever eaten,” said customer Judy Blackburn.</p>","vi":"NHÀ HÀNG VIỆT NAM MỚI KHAI TRƯƠNG\n\nSAN FRANCISCO (Ngày 5 tháng 11) — Đầu bếp nổi tiếng Eric Hoang đã khai trương nhà hàng đầu tiên của mình mang tên Ngon Mieng. Nhà hàng đã mở cửa vào tuần trước tại khu phố North Beach. Ngon Mieng phục vụ các món ăn Việt Nam thuần túy và một số món sáng tạo do Đầu bếp Hoang phát triển. Nhà hàng đã tiếp quản không gian từng được sử dụng bởi nhà hàng Plantains, nơi mà đã đóng cửa vào năm ngoái.\n\nĐầu bếp Hoang đã giành giải nhất trong chương trình truyền hình thực tế \"Đầu bếp xuất sắc nhất Hoa Kỳ\" (Best Chefs in the U.S.) cách đây hai năm. Anh ấy đã rất phấn khích khi giành chiến thắng trong cuộc thi đó. \"Sau khi nhận giải thưởng, việc mở một nhà hàng đã trở thành ước mơ của tôi,\" anh nói. \"Tôi rất hào hứng khi mang những sáng tạo ẩm thực của mình đến khu vực North Beach.\"\n\nTại buổi khai trương hoành tráng, các thực khách đã hưởng ứng sự nhiệt tình của Đầu bếp Hoang dành cho đồ ăn. \"Không còn nghi ngờ gì nữa, đó là một trong những món ngon nhất mà tôi từng được ăn,\" khách hàng Judy Blackburn cho biết.","qs":[{"n":131,"opts":["will launch","could launch","has launched","was launching"],"ans":"C","xp":"(A) will launch: sẽ khai trương\n(B) could launch: có thể khai trương\n(C) has launched: đã khai trương\n(D) was launching: đang khai trương\nGrammar: Thì hiện tại hoàn thành dùng để thông báo một sự việc vừa mới xảy ra và có kết quả ở hiện tại (câu sau: “It opened last week”).\n→ Chọn (C)\nDịch: Đầu bếp nổi tiếng Eric Hoang đã khai trương nhà hàng đầu tiên của mình, Ngon Mieng."},{"n":132,"opts":["they","this","where","which"],"ans":"D","xp":"(A) they: họ\n(B) this: cái này\n(C) where: nơi mà\n(D) which: cái mà\nGrammar: Đại từ quan hệ \"which\" thay thế cho tên nhà hàng \"Plantains\" đã đóng cửa trước đó (sau dấu phẩy, làm chủ ngữ cho “closed”).\n→ Chọn (D)\nDịch: ...không gian từng được sử dụng bởi nhà hàng Plantains, cái mà đã đóng cửa vào năm ngoái."},{"n":133,"opts":["San Francisco has many popular Vietnamese restaurants.","The restaurant may expand to other California cities next year.","The show is entering its fifth season.","He was thrilled to win that competition."],"ans":"D","xp":"(A) San Francisco có nhiều nhà hàng Việt Nam nổi tiếng.\n(B) Nhà hàng có thể mở rộng sang các thành phố khác của California vào năm tới.\n(C) Chương trình đang bước vào mùa thứ năm.\n(D) Anh ấy đã rất phấn khích khi giành chiến thắng trong cuộc thi đó.\nContext: Câu trước nói về việc đầu bếp Hoang giành giải nhất trong show \"Best Chefs in the U.S.\".\n→ Chọn (D)\nDịch: Anh ấy đã rất phấn khích khi giành chiến thắng trong cuộc thi đó."},{"n":134,"opts":["food","event","area","performance"],"ans":"A","xp":"(A) food: đồ ăn/ẩm thực\n(B) event: sự kiện\n(C) area: khu vực\n(D) performance: buổi biểu diễn\nContext: Thực khách đang nhận xét về chất lượng món ăn tại nhà hàng (“some of the best I’ve ever eaten”).\n→ Chọn (A)\nDịch: Tại buổi khai trương, các thực khách đã hưởng ứng sự nhiệt tình của đầu bếp Hoang đối với đồ ăn."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following notice.","passage":"<h3>Connelly’s Parking Garage</h3><p>Parking is $10 per hour unless you get your parking validated at a <span class=\"blank\" data-n=\"135\">-------</span> store. Stores that can validate your parking include Raymond’s Department Store, Lola’s Fine Dining, Monique’s Boutique, and Gretsch Chocolatiers. Just bring your entrance ticket to <span class=\"blank\" data-n=\"136\">-------</span> of these establishments. <span class=\"blank\" data-n=\"137\">-------</span>. You will get your first hour of parking at no charge. <span class=\"blank\" data-n=\"138\">-------</span>, the fee will be $5 per hour.</p>","vi":"BÃI ĐỖ XE CỦA CONNELLY\n\nPhí gửi xe là $10 mỗi giờ trừ khi bạn được xác nhận tại một cửa hàng có tham gia (participating). Các cửa hàng có thể xác nhận gửi xe cho bạn bao gồm: Cửa hàng bách hóa Raymond’s, Nhà hàng Lola’s Fine Dining, Monique’s Boutique và Gretsch Chocolatiers. Chỉ cần mang vé vào cửa của bạn đến bất kỳ (any) cơ sở nào trong số này. Nhân viên thu ngân sẽ vui lòng đóng dấu nó cho bạn (A cashier will gladly stamp it for you). Bạn sẽ được miễn phí giờ gửi xe đầu tiên. Nếu không (If not), mức phí sẽ là $5 mỗi giờ.","qs":[{"n":135,"opts":["participates","participated","participating","participation"],"ans":"C","xp":"(A) participates (v): tham gia\n(B) participated (v-ed): đã tham gia\n(C) participating (adj/participle): có tham gia\n(D) participation (n): sự tham gia\nCollocation: participating store = cửa hàng có tham gia (chương trình).\n→ Chọn (C)\nDịch: Phí đỗ xe là 10 đô la mỗi giờ trừ khi bạn được xác nhận đỗ xe tại một cửa hàng có tham gia."},{"n":136,"opts":["any","all","each","either"],"ans":"A","xp":"(A) any: bất kỳ\n(B) all: tất cả\n(C) each: mỗi\n(D) either: một trong hai\nGrammar: \"any of these establishments\" dùng để chỉ bất kỳ cơ sở nào trong số các cửa hàng đã liệt kê phía trước.\n→ Chọn (A)\nDịch: Chỉ cần mang vé vào cửa của bạn đến bất kỳ cơ sở nào trong số này."},{"n":137,"opts":["Park only in specified spots.","Make sure to lock your vehicle.","We cannot accept cash at this time.","A cashier will gladly stamp it for you."],"ans":"D","xp":"(A) Chỉ đỗ xe ở những vị trí quy định.\n(B) Hãy chắc chắn khóa xe của bạn.\n(C) Chúng tôi không thể chấp nhận tiền mặt vào lúc này.\n(D) Nhân viên thu ngân sẽ vui lòng đóng dấu nó cho bạn.\nContext: Để được miễn phí giờ đầu, khách hàng cần mang vé đến cửa hàng để được xác nhận (đóng dấu).\n→ Chọn (D)\nDịch: Nhân viên thu ngân sẽ vui lòng đóng dấu nó cho bạn. Bạn sẽ được miễn phí giờ đỗ xe đầu tiên."},{"n":138,"opts":["If not","Then","In that case","Nevertheless"],"ans":"A","xp":"(A) If not: Nếu không\n(B) Then: Sau đó\n(C) In that case: Trong trường hợp đó\n(D) Nevertheless: Tuy nhiên\nContext: \"If not\" dùng để chỉ trường hợp nếu vé không được đóng dấu xác nhận.\n→ Chọn (A)\nDịch: Nếu không, mức phí sẽ là 5 đô la mỗi giờ."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following announcement.","passage":"<p>Lost Ocean Theater is thrilled to announce a unique offering coming to its downtown location next week. The talented comedian Maddy Chang <span class=\"blank\" data-n=\"139\">-------</span> a one-person show based on her memoir, <i>That’s All I Wanted</i>. Chang’s book, filled with funny and engaging <span class=\"blank\" data-n=\"140\">-------</span>, is brought to life through this performance. Fans will enjoy experiencing Chang’s brilliance in person, while newcomers to her work will receive a <span class=\"blank\" data-n=\"141\">-------</span> introduction to her entertaining world.</p><p>Show times are Thursday through Sunday at 7:00 P.M., with an additional matinee on Saturday at 1:00 P.M. <span class=\"blank\" data-n=\"142\">-------</span>. Additional information can be found at www.lostoceantheater.com.</p>","vi":"Nhà hát Lost Ocean rất vui mừng thông báo về một chương trình độc đáo sắp có mặt tại cơ sở ở trung tâm thành phố vào tuần tới. Nghệ sĩ hài tài năng Maddy Chang sẽ biểu diễn (will perform) một chương trình độc diễn dựa trên cuốn hồi ký của cô mang tên That's All I Wanted. Cuốn sách của Chang, chứa đầy những nhân vật (characters) hài hước và lôi cuốn, được đưa vào cuộc sống thông qua buổi biểu diễn này. Những người hâm mộ sẽ thích thú khi được trải nghiệm sự tỏa sáng của Chang trực tiếp, trong khi những người mới biết đến tác phẩm của cô sẽ nhận được một lời giới thiệu thú vị (delightful) vào thế giới giải trí của cô.\n\nThời gian biểu diễn là từ Thứ Năm đến Chủ Nhật lúc 7:00 tối, với một buổi biểu diễn phụ (matinee) vào Thứ Bảy lúc 1:00 chiều. Hãy gọi cho nhà hát theo số 704-555-0138 để đặt vé (Call the theater at 704-555-0138 to reserve tickets). Thông tin bổ sung có thể được tìm thấy tại www.lostoceantheater.com.","qs":[{"n":139,"opts":["will perform","to perform","performed","performing"],"ans":"A","xp":"(A) will perform: sẽ biểu diễn\n(B) to perform: để biểu diễn\n(C) performed: đã biểu diễn\n(D) performing: đang biểu diễn\nGrammar: Thì tương lai đơn dùng cho một sự kiện đã được lên lịch sắp tới (\"next week\").\n→ Chọn (A)\nDịch: Diễn viên hài tài năng Maddy Chang sẽ biểu diễn một chương trình cá nhân..."},{"n":140,"opts":["reasons","structures","characters","signs"],"ans":"C","xp":"(A) reasons: lý do\n(B) structures: cấu trúc\n(C) characters: nhân vật\n(D) signs: dấu hiệu\nContext: Cuốn hồi ký (memoir) thường bao gồm các nhân vật thú vị và lôi cuốn.\n→ Chọn (C)\nDịch: Cuốn sách của Chang, chứa đầy những nhân vật vui nhộn và lôi cuốn..."},{"n":141,"opts":["delight","delights","delighted","delightful"],"ans":"D","xp":"(A) delight (v/n): sự vui thích\n(B) delights (v/n số nhiều): những điều thú vị\n(C) delighted (adj): cảm thấy vui mừng (dùng cho người)\n(D) delightful (adj): thú vị/đáng yêu (dùng cho vật/sự việc)\nGrammar: Cần một tính từ bổ nghĩa cho danh từ \"introduction\".\n→ Chọn (D)\nDịch: ...trong khi những người mới biết đến tác phẩm của cô sẽ nhận được một sự giới thiệu thú vị vào thế giới giải trí của cô."},{"n":142,"opts":["The theater will close for renovations.","Call the theater at 704-555-0138 to reserve tickets.","Chang’s memoir is available online and at local booksellers.","Chang was raised in Southern California and attended college in Minnesota."],"ans":"B","xp":"(A) Nhà hát sẽ đóng cửa để cải tạo.\n(B) Hãy gọi cho nhà hát theo số 704-555-0138 để đặt vé.\n(C) Hồi ký của Chang có sẵn trực tuyến và tại các hiệu sách địa phương.\n(D) Chang lớn lên ở Nam California và học đại học ở Minnesota.\nContext: Đây là thông báo về lịch diễn, nên câu kết hợp lý nhất là hướng dẫn cách mua vé.\n→ Chọn (B)\nDịch: Hãy gọi cho nhà hát theo số 704-555-0138 để đặt vé."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> tvargas@sandelleinn.com</p><p><b>From:</b> moira@petalsaplenty.com</p><p><b>Date:</b> November 2</p><p><b>Subject:</b> Floral arrangement</p></div><p>Dear Ms. Vargas,</p><p>I left a complimentary floral arrangement with your receptionist today, and she suggested that I contact you directly. I specialize in floral design. I created this bouquet for you, using bold colors that match the inn’s lobby, to give you an idea of how I <span class=\"blank\" data-n=\"143\">-------</span> my work.</p><p>I was told that you do not currently have a budget for décor. <span class=\"blank\" data-n=\"144\">-------</span>, perhaps we could still partner in some way. I see that you host small events, and your Web site has links to local DJs, caterers, and other service providers that you recommend. Would you consider including my company, Petals Aplenty, on your list of <span class=\"blank\" data-n=\"145\">-------</span>? I would be happy to reciprocate by promoting your inn on my own Web site. <span class=\"blank\" data-n=\"146\">-------</span>.</p><p>I look forward to hearing from you.</p><p>Moira Voss, Owner, Petals Aplenty</p>","vi":"Người nhận: tvargas@sandelleinn.com\nNgười gửi: moira@petalsaplenty.com\nNgày: 2 tháng 11\nTiêu đề: Lẵng hoa\n\nKính gửi cô Vargas,\n\nHôm nay tôi đã gửi một lẵng hoa tặng kèm cho nhân viên lễ tân của cô, và cô ấy đã gợi ý tôi nên liên hệ trực tiếp với cô. Tôi chuyên về thiết kế hoa. Tôi đã tạo ra bó hoa này cho cô, sử dụng những màu sắc đậm phù hợp với sảnh của nhà trọ, để giúp cô hình dung được cách tôi tiếp cận (approach) công việc của mình.\n\nTôi được biết rằng hiện tại cô không có ngân sách cho việc trang trí. Mặc dù vậy (Even so), có lẽ chúng ta vẫn có thể hợp tác theo một cách nào đó. Tôi thấy cô có tổ chức các sự kiện nhỏ, và trang web của cô có các liên kết dẫn đến các DJ địa phương, bên cung cấp dịch vụ tiệc và các nhà cung cấp dịch vụ khác mà cô khuyên dùng. Cô có cân nhắc đưa công ty của tôi, Petals Aplenty, vào danh sách các đơn vị được giới thiệu (referrals) của cô không? Tôi rất vui lòng đáp lễ bằng cách quảng bá nhà trọ của cô trên trang web của chính tôi. Tôi tin rằng sự sắp xếp này có thể mang lại lợi ích cho cả hai chúng ta (I believe this arrangement can benefit us both).\n\nTôi rất mong nhận được phản hồi từ cô.\n\nMoira Voss, Chủ sở hữu, Petals Aplenty","qs":[{"n":143,"opts":["document","approach","schedule","verify"],"ans":"B","xp":"(A) document (v): ghi chép lại\n(B) approach (v): tiếp cận (cũng là danh từ: cách tiếp cận/phương pháp)\n(C) schedule: lên lịch/lịch trình\n(D) verify (v): xác minh\nCollocation: how I approach my work = cách tôi tiếp cận/phong cách làm việc của tôi (sau chủ ngữ “I” cần động từ).\n→ Chọn (B)\nDịch: ...để cho bạn một ý niệm về cách tôi tiếp cận công việc của mình."},{"n":144,"opts":["Even so","For example","On the contrary","As you suggested"],"ans":"A","xp":"(A) Even so: Dẫu vậy/Tuy nhiên\n(B) For example: Ví dụ\n(C) On the contrary: Ngược lại\n(D) As you suggested: Như bạn đã gợi ý\nContext: Dùng để nối hai ý: dù không có ngân sách trang trí nhưng vẫn có thể hợp tác bằng cách khác.\n→ Chọn (A)\nDịch: Tôi được biết bạn hiện không có ngân sách cho việc trang trí. Dẫu vậy, có lẽ chúng ta vẫn có thể hợp tác theo cách nào đó."},{"n":145,"opts":["refers","referred","referrals","referable"],"ans":"C","xp":"(A) refers (v): tham khảo\n(B) referred (v-ed): đã tham khảo\n(C) referrals (n): sự giới thiệu/người được giới thiệu\n(D) referable (adj): có thể tham khảo\nCollocation: list of referrals = danh sách các đơn vị/đối tác được giới thiệu (sau giới từ “of” cần danh từ).\n→ Chọn (C)\nDịch: Bạn có cân nhắc việc đưa công ty tôi vào danh sách giới thiệu của bạn không?"},{"n":146,"opts":["I want to thank you again for the nomination.","I can certainly see the resemblance.","I think it was all just a misunderstanding.","I believe this arrangement can benefit us both."],"ans":"D","xp":"(A) Tôi muốn cảm ơn bạn một lần nữa vì sự đề cử.\n(B) Tôi chắc chắn có thể thấy sự tương đồng.\n(C) Tôi nghĩ tất cả chỉ là một sự hiểu lầm.\n(D) Tôi tin rằng sự sắp xếp này có thể mang lại lợi ích cho cả hai chúng ta.\nContext: Người gửi đề xuất một sự hợp tác đôi bên cùng có lợi (tôi quảng bá bạn, bạn giới thiệu tôi).\n→ Chọn (D)\nDịch: Tôi tin rằng sự sắp xếp này có thể mang lại lợi ích cho cả hai chúng ta."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following job posting.","passages":["<h3>Help Wanted</h3><p>Zestful Cuisine is looking for a server to join our restaurant’s team! We specialize in French and Spanish food.</p><p>This is a full-time or part-time position. Days and nights are available.</p><p>Candidate must have a positive attitude, excellent customer service skills, and the ability to multitask in a fast-paced environment.</p><p>Zestful Cuisine offers competitive pay rates based on job experience. All servers receive one meal during each shift. We provide a career path with promotion and increased pay.</p><p>Applications are available on our Web site, www.zestfulcuisine.com.</p>"],"vi":"Thông báo tuyển dụng\n\nZestful Cuisine đang tìm một nhân viên phục vụ (server) để gia nhập đội ngũ nhà hàng của chúng tôi! Chúng tôi chuyên về ẩm thực Pháp và Tây Ban Nha.\n\nĐây là vị trí toàn thời gian hoặc bán thời gian. Có ca làm ban ngày và ban đêm.\n\nỨng viên cần có thái độ tích cực, kỹ năng chăm sóc khách hàng xuất sắc và khả năng làm nhiều việc cùng lúc trong môi trường làm việc nhanh và áp lực cao.\n\nZestful Cuisine đưa ra mức lương cạnh tranh dựa trên kinh nghiệm làm việc. Tất cả nhân viên phục vụ đều được một bữa ăn trong mỗi ca làm. Chúng tôi cung cấp lộ trình nghề nghiệp với cơ hội thăng tiến và tăng lương.\n\nĐơn ứng tuyển có sẵn trên website của chúng tôi: www.zestfulcuisine.com.","qs":[{"n":147,"q":"What is suggested about Zestful Cuisine?","qvi":"Điều gì được gợi ý về Zestful Cuisine?","opts":["It offers shift flexibility to employees.","It pays all employees the same base salary.","It offers promotions after six months.","It requires staff to attend a training session."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"This is a full-time or part-time position. Days and nights are available.\" (Đây là vị trí toàn thời gian hoặc bán thời gian. Có ca ban ngày và ban đêm.) → nhân viên được linh hoạt chọn ca. (B) sai vì lương \"based on job experience\" (dựa theo kinh nghiệm); (C), (D) không được nhắc đến.\n(A) Công ty cho phép nhân viên linh hoạt ca làm việc.\n(B) Công ty trả cùng một mức lương cơ bản cho tất cả nhân viên.\n(C) Công ty đề bạt nhân viên sau sáu tháng làm việc.\n(D) Công ty yêu cầu nhân viên tham gia một buổi đào tạo."},{"n":148,"q":"According to the job posting, what is an essential quality for a candidate?","qvi":"Theo thông báo tuyển dụng, phẩm chất thiết yếu đối với một ứng viên là gì?","opts":["Knowledge of food safety regulations","Fluency in several languages","Previous experience at a restaurant","Ability to communicate with customers"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"Candidate must have ... excellent customer service skills\" (Ứng viên phải có kỹ năng chăm sóc khách hàng xuất sắc) → paraphrase: khả năng giao tiếp với khách hàng.\n(A) Kiến thức về các quy định an toàn thực phẩm\n(B) Thành thạo nhiều ngôn ngữ\n(C) Có kinh nghiệm làm việc tại nhà hàng\n(D) Khả năng giao tiếp với khách hàng"}]},{"ns":[149,151],"head":"Questions 149-151 refer to the following article.","passages":["<p>WINNIPEG (10 May)—Manitoba-based satellite manufacturer Alita Technology has been awarded a $9 million grant to develop an airborne sensing instrument to be used in the collection of climate data. The device will be engineered to calculate the density and depth of snowpack throughout Canada.</p><p>Alita Technology is collaborating with the Microwave Engineering Lab at the University of Southam on the initiative. Dr. Hugh Jaris, director of the lab’s Remote Sensing Unit, will lead the effort to test one or more prototypes by collecting and analysing data next winter.</p><p>Snowpack data is used to measure year-to-year snow trends and fluctuations as well as to help determine how much water from snowmelt will be available in key areas of the country.</p>"],"vi":"WINNIPEG (Ngày 10 tháng 5) — Nhà sản xuất vệ tinh có trụ sở tại Manitoba, Alita Technology, đã được trao khoản tài trợ 9 triệu đô la để phát triển một thiết bị cảm biến trên không dùng để thu thập dữ liệu về khí hậu. Thiết bị này sẽ được thiết kế để tính toán mật độ và độ sâu của lớp tuyết phủ trên khắp Canada.\n\nAlita Technology đang hợp tác với Phòng Thí nghiệm Kỹ thuật Vi sóng tại Đại học Southam trong dự án này. Tiến sĩ Hugh Jaris, giám đốc Đơn vị Cảm biến Từ xa của phòng thí nghiệm, sẽ dẫn dắt nỗ lực thử nghiệm một hoặc nhiều mẫu thử nghiệm bằng cách thu thập và phân tích dữ liệu vào mùa đông tới.\n\nDữ liệu lớp tuyết phủ được sử dụng để đo lường xu hướng và biến động tuyết từ năm này sang năm khác, cũng như giúp xác định lượng nước từ tuyết tan sẽ có sẵn ở các khu vực quan trọng của đất nước.","qs":[{"n":149,"q":"According to the article, who is responsible for engineering the device?","qvi":"Theo bài báo, ai là người chịu trách nhiệm thiết kế (chế tạo) thiết bị?","opts":["Dr. Jaris","Alita Technology","The University of Southam’s Microwave Engineering Lab","The government of Winnipeg"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"Alita Technology has been awarded a $9 million grant to develop an airborne sensing instrument ... The device will be engineered to ...\" → Alita Technology là bên phát triển/chế tạo thiết bị. Tiến sĩ Jaris và phòng thí nghiệm chỉ phụ trách thử nghiệm (test) mẫu.\n(A) Tiến sĩ Jaris\n(B) Công ty Alita Technology\n(C) Phòng thí nghiệm Kỹ thuật Vi sóng của Đại học Southam\n(D) Chính quyền thành phố Winnipeg"},{"n":150,"q":"The word \"initiative\" in paragraph 2, line 3, is closest in meaning to","qvi":"Từ \"initiative\" ở đoạn 2, dòng 3, có nghĩa gần nhất với từ nào?","opts":["motivation","technique","advantage","project"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"Alita Technology is collaborating with the Microwave Engineering Lab ... on the initiative.\" → \"initiative\" ở đây là chương trình/dự án phát triển thiết bị = project.\n(A) động lực\n(B) kỹ thuật\n(C) lợi thế\n(D) dự án"},{"n":151,"q":"What is indicated about Dr. Jaris?","qvi":"Điều gì được đề cập về Tiến sĩ Jaris?","opts":["He is employed by a university laboratory.","He has published a book on device design and development.","He assembles prototypes of sensing instruments.","He works as an engineer at Alita Technology."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"the Microwave Engineering Lab at the University of Southam ... Dr. Hugh Jaris, director of the lab’s Remote Sensing Unit\" → ông là giám đốc một đơn vị thuộc phòng thí nghiệm của trường đại học. (C) sai: ông thử nghiệm (test) chứ không lắp ráp nguyên mẫu.\n(A) Ông làm việc cho một phòng thí nghiệm thuộc trường đại học.\n(B) Ông đã xuất bản một cuốn sách về thiết kế và phát triển thiết bị.\n(C) Ông lắp ráp các nguyên mẫu của thiết bị cảm biến.\n(D) Ông làm kỹ sư tại công ty Alita Technology."}]},{"ns":[152,153],"head":"Questions 152-153 refer to the following receipt.","passages":["<h3>Stub Master—Your Ticket Source for Concerts, Sports, and Theater</h3><p>Hello, Mr. Sato,</p><p>Thanks for your purchase! Your mobile ticket is ready and available in the Stub Master account you created online. All Stub Master tickets contain a unique barcode and may not be printed, copied, or shared. Please use the Stub Master app on your phone to access your ticket so that it can be scanned electronically for entry to the event.</p><table><tr><th>Confirmation #:</th><td>9035768</td></tr><tr><th>Date:</th><td>Saturday, June 25</td></tr><tr><th>Time:</th><td>7 P.M.</td></tr><tr><th>Event:</th><td>Monterrey Medallions at Mayville Dodgers</td></tr><tr><th>Venue:</th><td>Alonso Reyes Stadium</td></tr><tr><th>Order:</th><td>1 ticket; bleachers – uncovered; regular season baseball</td></tr><tr><th>Total:</th><td>$25 (price includes a $3 building fee)</td></tr><tr><th>Notes:</th><td>Participate in the burger and hot dog buffet for $15 on-site.<br>For corporate ticket purchases, contact service@stubmaster.com.</td></tr></table>"],"vi":"Stub Master — Nguồn vé của bạn cho các buổi hòa nhạc, thể thao và sân khấu\n\nXin chào, Ông Sato,\n\nCảm ơn quý khách đã mua hàng! Vé điện tử của quý khách đã sẵn sàng và có trong tài khoản Stub Master mà quý khách đã tạo trực tuyến. Tất cả vé Stub Master đều có một mã vạch duy nhất và không được in, sao chép hoặc chia sẻ. Vui lòng sử dụng ứng dụng Stub Master trên điện thoại của quý khách để truy cập vé nhằm có thể quét điện tử khi vào sự kiện.\n\nSố xác nhận: 9035768\nNgày: Thứ Bảy, ngày 25 tháng 6\nGiờ: 7 giờ tối\nSự kiện: Monterrey Medallions gặp Mayville Dodgers (trên sân Mayville Dodgers)\nĐịa điểm: Sân vận động Alonso Reyes\nĐơn hàng: 1 vé; khu vực khán đài giá rẻ – không có mái che; mùa bóng chày thông thường\nTổng cộng: 25 đô la (giá bao gồm phí xây dựng 3 đô la)\nGhi chú: Tham gia tiệc buffet burger và hot dog với giá 15 đô la tại chỗ. Để mua vé doanh nghiệp, liên hệ service@stubmaster.com.","qs":[{"n":152,"q":"What is mentioned about Stub Master tickets?","qvi":"Điều gì được đề cập về vé Stub Master?","opts":["They are mailed to customers.","They include parking fees in the price.","They are discounted for corporate purchases.","They are saved electronically."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"Your mobile ticket is ready and available in the Stub Master account ... may not be printed ... use the Stub Master app on your phone to access your ticket\" → vé là vé điện tử, lưu trong tài khoản/ứng dụng. (B) sai: giá gồm phí xây dựng (building fee), không phải phí gửi xe; (C) chỉ nói liên hệ để mua vé doanh nghiệp, không nói giảm giá.\n(A) Vé được gửi qua đường bưu điện cho khách hàng.\n(B) Vé đã bao gồm phí gửi xe trong giá tiền.\n(C) Vé được giảm giá cho các đơn mua của doanh nghiệp.\n(D) Vé được lưu trữ dưới dạng điện tử."},{"n":153,"q":"What is true about the event Mr. Sato will attend?","qvi":"Điều gì đúng về sự kiện mà ông Sato sẽ tham dự?","opts":["It will take place on June 7.","It is a baseball game.","It will take place indoors.","It includes a free buffet."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"Order: 1 ticket; bleachers – uncovered; regular season baseball\" → đây là trận bóng chày. (A) sai: ngày 25/6 (7 P.M. là giờ); (C) sai: khán đài \"uncovered\" (không mái che); (D) sai: buffet tốn $15.\n(A) Sự kiện sẽ diễn ra vào ngày 7 tháng 6.\n(B) Đó là một trận đấu bóng chày.\n(C) Sự kiện sẽ được tổ chức trong nhà.\n(D) Sự kiện bao gồm tiệc buffet miễn phí."}]},{"ns":[154,156],"head":"Questions 154-156 refer to the following press release.","passages":["<h3>FOR IMMEDIATE RELEASE</h3><p><b>Contact:</b> Nadia Khumalo, nadia_khumalo@gulfbrookcreations.co.za</p><p>CAPE TOWN (20 August)—Gulfbrook Creations today announced the appointment of Ms. Candace Masondo as the company’s chief design officer (CDO), effective 1 September. — <span class=\"pos\">[1]</span> —. Most recently, Ms. Masondo headed the materials development division at Deavora Dynamix, based in Durban. — <span class=\"pos\">[2]</span> —. She was the driving force behind that company’s mission to develop accessibility products to enhance independent living in South Africa’s domestic market.</p><p>Mr. Jonathan Ngobeni, Gulfbrook’s president, acknowledges Ms. Masondo’s skills and resourcefulness. “In her three-decades-long design career, Ms. Masondo has designed numerous products that reflect inclusiveness and self-sufficiency. Throughout those years, she has emphasized and demonstrated the importance of collaboration between engineers, designers, and consumers. She has won several prestigious awards for her work. Her achievements demonstrate her commitment to colleagues and product users. We are excited that she will be joining our team.” — <span class=\"pos\">[3]</span> —.</p><p>“It is a tremendous honour and privilege to be appointed Gulfbrook’s CDO,” Ms. Masondo said. “I will do my best to advance the company’s mission and strengthen its industry presence.” — <span class=\"pos\">[4]</span> —.</p><p>Gulfbrook Creations is headquartered in Johannesburg. For 45 years, the company has been manufacturing equipment that facilitates independent living, including ergonomic furniture, audio- and visual-enhancement devices, and motorized mobility aids. Its products are marketed mainly in Africa.</p>"],"vi":"PHÁT HÀNH NGAY\n\nLiên hệ: Nadia Khumalo, nadia_khumalo@gulfbrookcreations.co.za\n\nCAPE TOWN (20 tháng 8) — Gulfbrook Creations hôm nay thông báo việc bổ nhiệm bà Candace Masondo làm Giám đốc Thiết kế (CDO) của công ty, có hiệu lực từ ngày 1 tháng 9. — [1] —. Gần đây nhất, bà Masondo đứng đầu bộ phận phát triển vật liệu tại Deavora Dynamix có trụ sở tại Durban. — [2] —. Bà là lực lượng chủ chốt đứng sau sứ mệnh của công ty đó nhằm phát triển các sản phẩm hỗ trợ khả năng tiếp cận để nâng cao khả năng sống độc lập tại thị trường nội địa Nam Phi.\n\nÔng Jonathan Ngobeni, chủ tịch Gulfbrook, ghi nhận kỹ năng và sự tháo vát của bà Masondo: “Trong sự nghiệp thiết kế kéo dài ba thập kỷ, bà Masondo đã thiết kế nhiều sản phẩm thể hiện tính bao trùm và khả năng tự chủ. Trong suốt những năm đó, bà đã nhấn mạnh và chứng minh tầm quan trọng của sự hợp tác giữa kỹ sư, nhà thiết kế và người tiêu dùng. Bà đã giành được nhiều giải thưởng danh giá cho công việc của mình. Những thành tựu của bà thể hiện cam kết của bà với đồng nghiệp và người sử dụng sản phẩm. Chúng tôi rất hào hứng khi bà sẽ gia nhập đội ngũ của chúng tôi.” — [3] —.\n\n“Đó là một vinh dự và đặc ân to lớn khi được bổ nhiệm làm CDO của Gulfbrook,” bà Masondo nói. “Tôi sẽ cố gắng hết sức để thúc đẩy sứ mệnh của công ty và củng cố sự hiện diện của công ty trong ngành.” — [4] —.\n\nGulfbrook Creations có trụ sở chính tại Johannesburg. Trong 45 năm qua, công ty đã sản xuất các thiết bị giúp hỗ trợ cuộc sống độc lập, bao gồm nội thất công thái học, thiết bị tăng cường âm thanh và hình ảnh, và các thiết bị hỗ trợ di chuyển có động cơ. Sản phẩm của công ty chủ yếu được tiếp thị tại châu Phi.","qs":[{"n":154,"q":"What is mentioned about Ms. Masondo?","qvi":"Điều gì được đề cập về bà Masondo?","opts":["She received some awards in August.","She regularly meets with consumers.","She frequently travels abroad for business.","She has been a product designer for 30 years."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"In her three-decades-long design career, Ms. Masondo has designed numerous products\" (Trong sự nghiệp thiết kế kéo dài ba thập kỷ...) → three decades = 30 năm. (A) sai: có giải thưởng nhưng không nói vào tháng 8 (20 August là ngày thông cáo).\n(A) Bà đã nhận được một số giải thưởng vào tháng Tám.\n(B) Bà thường xuyên gặp gỡ người tiêu dùng.\n(C) Bà thường xuyên đi công tác nước ngoài.\n(D) Bà đã làm nhà thiết kế sản phẩm trong 30 năm."},{"n":155,"q":"What do Gulfbrook Creations and Deavora Dynamix have in common?","qvi":"Điểm chung giữa Gulfbrook Creations và Deavora Dynamix là gì?","opts":["Their export markets","Their types of products","Their years of operation","Their headquarters location"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Deavora Dynamix: \"develop accessibility products to enhance independent living\"; Gulfbrook: \"manufacturing equipment that facilitates independent living\" → cả hai đều làm sản phẩm hỗ trợ cuộc sống độc lập. (D) sai: Durban khác Johannesburg.\n(A) Thị trường xuất khẩu của họ\n(B) Loại sản phẩm họ sản xuất\n(C) Số năm hoạt động\n(D) Vị trí trụ sở chính"},{"n":156,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“She served in that capacity for ten years, having joined Deavora Dynamix two years after it began operations.”","qvi":"Câu sau đây nên được đặt ở vị trí nào trong các vị trí được đánh dấu [1], [2], [3], và [4]?\n“Bà đã đảm nhiệm vị trí đó trong vòng mười năm, sau khi gia nhập Deavora Dynamix hai năm kể từ khi công ty bắt đầu hoạt động.”","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Câu cần điền nhắc đến \"that capacity\" (vị trí đó) và \"Deavora Dynamix\" → phải đứng ngay sau câu \"Ms. Masondo headed the materials development division at Deavora Dynamix, based in Durban.\" → vị trí [2]."}]},{"ns":[157,158],"head":"Questions 157-158 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Priya Gao (7:52 A.M.)</b></p><p>Hi, Luis. Are you working in the office today?</p></div><div class=\"msg\"><p><b>Luis Fuentes (7:53 A.M.)</b></p><p>I’m leaving the house now.</p></div><div class=\"msg\"><p><b>Priya Gao (7:54 A.M.)</b></p><p>Perfect! I’m wondering if you can do me a big favor.</p></div><div class=\"msg\"><p><b>Luis Fuentes (7:55 A.M.)</b></p><p>Absolutely! What do you need?</p></div><div class=\"msg\"><p><b>Priya Gao (7:56 A.M.)</b></p><p>I’m working from home today and have a call with the regional managers at 9 A.M. But the notes I need for the call are on my desk. They’re in a red folder next to my computer. I was hoping you could scan them and e-mail them to me since you usually get to the office early.</p></div><div class=\"msg\"><p><b>Luis Fuentes (7:58 A.M.)</b></p><p>I should be there by 8:30. I’ll do it first thing.</p></div><div class=\"msg\"><p><b>Priya Gao (7:59 A.M.)</b></p><p>Thank you so much! I’ll buy you lunch next time we’re in the office together.</p></div>"],"vi":"Priya Gao (7:52 sáng)\nChào Luis. Hôm nay anh có làm việc ở văn phòng không?\n\nLuis Fuentes (7:53 sáng)\nTôi đang rời khỏi nhà bây giờ.\n\nPriya Gao (7:54 sáng)\nTuyệt vời! Không biết anh có thể giúp tôi một việc lớn được không?\n\nLuis Fuentes (7:55 sáng)\nChắc chắn rồi! Việc gì vậy?\n\nPriya Gao (7:56 sáng)\nHôm nay tôi làm việc ở nhà và có cuộc gọi với các quản lý khu vực lúc 9 giờ sáng. Nhưng ghi chú tôi cần cho cuộc gọi đang nằm trên bàn làm việc của tôi. Chúng nằm trong một bìa hồ sơ màu đỏ bên cạnh máy tính của tôi. Tôi hy vọng anh có thể scan chúng và gửi email cho tôi vì anh thường đến văn phòng sớm.\n\nLuis Fuentes (7:58 sáng)\nTôi chắc sẽ đến đó trước 8:30. Tôi sẽ làm việc đó đầu tiên.\n\nPriya Gao (7:59 sáng)\nCảm ơn anh rất nhiều! Lần tới chúng ta cùng ở văn phòng, tôi sẽ mời anh ăn trưa.","qs":[{"n":157,"q":"At 7:53 A.M., what does Mr. Fuentes imply when he writes, “I’m leaving the house now”?","qvi":"Vào lúc 7:53 sáng, ông Fuentes ngụ ý điều gì khi viết: “I’m leaving the house now”?","opts":["He is late for work.","He will be home in time for lunch.","He is on his way to the office.","He already scanned a document."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Priya hỏi \"Are you working in the office today?\" → Luis trả lời \"I’m leaving the house now\" (tôi đang ra khỏi nhà) = đang trên đường đến văn phòng. Sau đó anh nói \"I should be there by 8:30\".\n(A) Ông ấy đang bị trễ giờ làm.\n(B) Ông ấy sẽ về nhà kịp giờ ăn trưa.\n(C) Ông ấy đang trên đường đến văn phòng.\n(D) Ông ấy đã scan một tài liệu rồi."},{"n":158,"q":"What problem does Ms. Gao have?","qvi":"Vấn đề mà cô Gao đang gặp phải là gì?","opts":["She mislabeled a folder.","She left important information in her office.","She needs help fixing her computer.","She forgot the number for a conference call."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"I’m working from home today ... But the notes I need for the call are on my desk.\" → ghi chú cần cho cuộc gọi lại để ở bàn làm việc tại văn phòng.\n(A) Cô ấy đã dán nhãn sai cho một bìa hồ sơ.\n(B) Cô ấy để quên thông tin quan trọng tại văn phòng.\n(C) Cô ấy cần được giúp sửa máy tính.\n(D) Cô ấy quên số điện thoại để tham gia cuộc gọi hội nghị."}]},{"ns":[159,161],"head":"Questions 159-161 refer to the following Web page.","passages":["<p>https://www.morrisville.gov.za/cityplanning/buildingpermits</p><h3>Requesting a Building Permit</h3><p>A city-issued building permit may be required before initiating construction work within Morrisville city limits. No city permit is required for work on a building’s interior systems, such as plumbing, electrical, or heating and cooling. A permit will be needed for adding to or expanding the size of a building, for changing the exterior appearance of a building, or for any brand-new construction project. Below are the steps for obtaining a permit and for ensuring full compliance with city policies.</p><ol><li>Check that the building is appropriately registered. See the Registration and Land Use page for more information.</li><li>Submit an application for a building permit. Please contact Ronald Abioye at the City Planning Office if you need assistance completing this application.</li><li>You will receive a letter, and if your application is approved, your official building permit will be enclosed. Work may commence once the permit is received and then posted in an easily visible location at the main entrance of the construction site.</li></ol>"],"vi":"https://www.morrisville.gov.za/cityplanning/buildingpermits\n\nYêu cầu Giấy phép Xây dựng\n\nGiấy phép xây dựng do thành phố cấp có thể được yêu cầu trước khi bắt đầu công việc xây dựng trong phạm vi thành phố Morrisville. Không cần giấy phép của thành phố đối với các công việc liên quan đến hệ thống bên trong tòa nhà, chẳng hạn như hệ thống ống nước, điện, hoặc sưởi ấm và làm mát. Giấy phép sẽ cần thiết để bổ sung hoặc mở rộng diện tích của một tòa nhà, để thay đổi vẻ ngoài bên ngoài của một tòa nhà, hoặc đối với bất kỳ dự án xây dựng mới nào. Dưới đây là các bước để xin giấy phép và đảm bảo tuân thủ đầy đủ các chính sách của thành phố.\n\n1. Kiểm tra xem tòa nhà có được đăng ký phù hợp hay không. Xem trang Đăng ký và Sử dụng Đất để biết thêm thông tin.\n2. Nộp đơn xin giấy phép xây dựng. Vui lòng liên hệ Ronald Abioye tại Văn phòng Quy hoạch Thành phố nếu bạn cần hỗ trợ hoàn thành đơn này.\n3. Bạn sẽ nhận được một bức thư, và nếu đơn của bạn được phê duyệt, giấy phép xây dựng chính thức của bạn sẽ được đính kèm. Công việc có thể bắt đầu sau khi nhận được giấy phép và sau đó giấy phép phải được treo ở vị trí dễ nhìn thấy tại lối vào chính của công trường xây dựng.","qs":[{"n":159,"q":"What type of project would require a permit?","qvi":"Loại dự án nào sẽ cần phải xin giấy phép?","opts":["Improving a building’s plumbing system","Installing an air-conditioning system","Upgrading the wiring in a residence","Enlarging an office building"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"A permit will be needed for adding to or expanding the size of a building\" → mở rộng tòa nhà cần giấy phép. (A), (B), (C) là hệ thống bên trong (plumbing, electrical, heating and cooling) → không cần giấy phép.\n(A) Cải thiện hệ thống ống nước của một tòa nhà\n(B) Lắp đặt hệ thống điều hòa không khí\n(C) Nâng cấp hệ thống dây điện trong nhà ở\n(D) Mở rộng một tòa nhà văn phòng"},{"n":160,"q":"According to the Web page, why should someone contact Mr. Abioye?","qvi":"Theo trang web, tại sao một người nên liên hệ với ông Abioye?","opts":["To make changes to a plan","To schedule building maintenance","To receive help when filling out a form","To check on the status of an application"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"Please contact Ronald Abioye ... if you need assistance completing this application.\" → paraphrase: assistance completing this application = help when filling out a form.\n(A) Để thay đổi một bản kế hoạch\n(B) Để sắp xếp việc bảo trì tòa nhà\n(C) Để được hỗ trợ khi điền vào một biểu mẫu\n(D) Để kiểm tra tình trạng của một đơn đăng ký"},{"n":161,"q":"What is indicated on the Web page as a step in the preconstruction process?","qvi":"Theo trang web, điều gì được nêu là một bước trong quy trình trước khi xây dựng?","opts":["A document is displayed.","The worksite is inspected.","A plan is signed by an engineer.","The building owner receives an e-mail."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"Work may commence once the permit is received and then posted in an easily visible location at the main entrance\" → trước khi thi công, giấy phép (một tài liệu) phải được treo ở nơi dễ thấy. (D) sai: nhận thư (letter), không phải email.\n(A) Một tài liệu được treo/trưng ra.\n(B) Công trường được kiểm tra.\n(C) Một bản kế hoạch được kỹ sư ký xác nhận.\n(D) Chủ sở hữu tòa nhà nhận được một email."}]},{"ns":[162,163],"head":"Questions 162-163 refer to the following schedule.","passages":["<h3>Millsberg Summer Festival</h3><p>Millsberg’s annual Summer Festival returns this June for its sixtieth year!</p><h4><u>Opening Parade</u></h4><p>June 20, 10:00 A.M.</p><p>This is the Summer Festival’s oldest and best-known event. The parade marks the official start of the festival and features elaborate floats and marching bands.</p><h4><u>Children’s Fun Fair</u></h4><p>June 20–26, noon–8:00 P.M.</p><p>Carnival rides and entertainment at Millsberg Park</p><h4><u>Outdoor Concert Series</u></h4><p>June 20–26, 7:00 P.M.</p><p>Live music, including folk, jazz, and classical, at Greenrow Park</p><p>Wood-fired pizza and other snacks will be available for purchase.</p><h4><u>Open-Air Art Studio</u></h4><p>June 26, 3:00 P.M.–9:00 P.M.</p><p>On the final day of the festival, local painters, photographers, and potters welcome the public to view their works at the park in front of the Riverside Art Complex.</p>"],"vi":"Lễ hội Mùa hè Millsberg\nLễ hội Mùa hè thường niên của Millsberg sẽ quay trở lại vào tháng Sáu này, đánh dấu năm thứ 60 được tổ chức!\n\nDiễu hành Khai mạc\nNgày 20 tháng 6, 10:00 sáng\nĐây là sự kiện lâu đời và nổi tiếng nhất của Lễ hội Mùa hè. Cuộc diễu hành đánh dấu sự khởi đầu chính thức của lễ hội và có các xe hoa được trang trí công phu cùng các ban nhạc diễu hành.\n\nHội chợ Vui chơi dành cho Trẻ em\nNgày 20–26 tháng 6, từ 12:00 trưa đến 8:00 tối\nCác trò chơi cảm giác và hoạt động giải trí tại Công viên Millsberg.\n\nChuỗi Hòa nhạc Ngoài trời\nNgày 20–26 tháng 6, 7:00 tối\nBiểu diễn nhạc sống, bao gồm nhạc dân gian, jazz và nhạc cổ điển, tại Công viên Greenrow.\nPizza nướng bằng lò củi và các món ăn nhẹ khác sẽ được bán cho khách.\n\nXưởng Nghệ thuật Ngoài trời\nNgày 26 tháng 6, từ 3:00 chiều đến 9:00 tối\nVào ngày cuối cùng của lễ hội, các họa sĩ, nhiếp ảnh gia và thợ gốm địa phương chào đón công chúng đến xem các tác phẩm của họ tại công viên phía trước Khu phức hợp Nghệ thuật Riverside.","qs":[{"n":162,"q":"What is indicated about the festival?","qvi":"Điều gì được đề cập về lễ hội?","opts":["It takes place several times a year.","It has activities for all ages.","Its events are held indoors.","Its events are held at a single location."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Lễ hội có \"Children’s Fun Fair\" (hội chợ cho trẻ em) cùng với diễu hành, hòa nhạc, triển lãm nghệ thuật cho công chúng → có hoạt động cho mọi lứa tuổi. (A) sai: \"annual\" (hằng năm); (C) sai: diễn ra ngoài trời ở các công viên; (D) sai: nhiều địa điểm (Millsberg Park, Greenrow Park, Riverside Art Complex).\n(A) Lễ hội được tổ chức nhiều lần trong năm.\n(B) Lễ hội có các hoạt động dành cho mọi lứa tuổi.\n(C) Các sự kiện của lễ hội được tổ chức trong nhà.\n(D) Các sự kiện của lễ hội được tổ chức tại một địa điểm duy nhất."},{"n":163,"q":"At what event can visitors purchase food?","qvi":"Tại sự kiện nào khách tham quan có thể mua đồ ăn?","opts":["Opening Parade","Children’s Fun Fair","Outdoor Concert Series","Open-Air Art Studio"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Ở mục Outdoor Concert Series: \"Wood-fired pizza and other snacks will be available for purchase.\" (Pizza nướng lò củi và đồ ăn nhẹ sẽ được bán.)\n(A) Lễ diễu hành khai mạc\n(B) Hội chợ vui chơi dành cho trẻ em\n(C) Chuỗi buổi hòa nhạc ngoài trời\n(D) Xưởng nghệ thuật ngoài trời"}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following information.","passages":["<h3>Watch the game you love for the price that’s right!</h3><p>Stream exciting, insightful content from the Total Basketball Channel (TBC) on your smartphone, tablet, or smart TV by subscribing to a TBC Plan! Download the TBC app or visit www.totalbasketballchannel.com to sign up for one of the following subscription options.</p><table><tr><th><i>TBC Platinum Plan<br>All live games, commercial-free</i></th><th><i>TBC Gold Plan<br>Most live games, commercial-free</i></th><th><i>TBC Silver Plan<br>Most live games played by a team of your choice</i></th><th><i>TBC Copper Plan<br>TBC game highlights</i></th></tr><tr><td><ul><li>Stream all games and commentary</li><li>Watch on up to three devices</li><li>Includes nationally televised games</li><li>$29/month or $149/year</li></ul></td><td><ul><li>Stream games for any team</li><li>Watch on up to three devices</li><li>Excludes nationally televised games</li><li>$19/month or $99/year</li></ul></td><td><ul><li>Stream games played by your favorite TBC team</li><li>Watch on up to two devices</li><li>Includes commercials</li><li>Excludes nationally televised games</li><li>$9/month or $49/year</li></ul></td><td><ul><li>Weekly replays of game highlights</li><li>Watch or download commentary shows</li><li>Includes commercials</li><li>Watch on one device</li><li>$5/month or $29/year</li></ul></td></tr></table>"],"vi":"Xem những trận đấu bạn yêu thích với mức giá hợp lý!\n\nPhát trực tuyến các nội dung hấp dẫn và sâu sắc từ Kênh Bóng rổ Toàn diện (Total Basketball Channel – TBC) trên điện thoại thông minh, máy tính bảng hoặc TV thông minh của bạn bằng cách đăng ký một gói TBC! Tải ứng dụng TBC hoặc truy cập www.totalbasketballchannel.com để đăng ký một trong các gói thuê bao sau.\n\nGói TBC Bạch kim (Platinum) – Tất cả các trận đấu trực tiếp, không có quảng cáo\n- Phát trực tuyến tất cả các trận đấu và phần bình luận\n- Xem trên tối đa ba thiết bị\n- Bao gồm các trận đấu được truyền hình trên toàn quốc\n- 29 đô la/tháng hoặc 149 đô la/năm\n\nGói TBC Vàng (Gold) – Hầu hết các trận đấu trực tiếp, không có quảng cáo\n- Phát trực tuyến các trận của bất kỳ đội nào\n- Xem trên tối đa ba thiết bị\n- Không bao gồm các trận được truyền hình toàn quốc\n- 19 đô la/tháng hoặc 99 đô la/năm\n\nGói TBC Bạc (Silver) – Hầu hết các trận đấu trực tiếp của đội bạn chọn\n- Phát trực tuyến các trận của đội TBC yêu thích của bạn\n- Xem trên tối đa hai thiết bị\n- Có quảng cáo\n- Không bao gồm các trận được truyền hình toàn quốc\n- 9 đô la/tháng hoặc 49 đô la/năm\n\nGói TBC Đồng (Copper) – Các điểm nổi bật (highlight) của trận đấu TBC\n- Phát lại hàng tuần các điểm nổi bật của trận đấu\n- Xem hoặc tải xuống các chương trình bình luận\n- Có quảng cáo\n- Xem trên một thiết bị\n- 5 đô la/tháng hoặc 29 đô la/năm","qs":[{"n":164,"q":"Where would the information most likely be found?","qvi":"Thông tin này có khả năng cao được tìm thấy ở đâu?","opts":["In a journal for sports psychologists","In a manual of basketball rules","In a sports magazine","In a basketball player’s biography"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Đây là quảng cáo các gói xem bóng rổ trực tuyến (\"Watch the game you love ... subscribing to a TBC Plan\") → phù hợp nhất để đăng trên tạp chí thể thao.\n(A) Trong một tạp chí dành cho các nhà tâm lý học thể thao\n(B) Trong sách hướng dẫn luật bóng rổ\n(C) Trong một tạp chí thể thao\n(D) Trong tiểu sử của một cầu thủ bóng rổ"},{"n":165,"q":"What is unique about the TBC Platinum Plan?","qvi":"Điều gì là điểm đặc biệt (chỉ có ở) gói TBC Platinum?","opts":["It has no advertisements.","It does not have a monthly payment option.","It allows streaming on up to three devices.","It includes nationally televised games."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Chỉ gói Platinum có \"Includes nationally televised games\"; Gold và Silver đều \"Excludes nationally televised games\". (A) và (C) gói Gold cũng có (commercial-free, up to three devices); (B) sai: có $29/month.\n(A) Gói này không có quảng cáo.\n(B) Gói này không có tùy chọn thanh toán theo tháng.\n(C) Gói này cho phép phát trực tuyến trên tối đa ba thiết bị.\n(D) Gói này bao gồm các trận đấu được truyền hình trên toàn quốc."},{"n":166,"q":"What plan is designed for a subscriber who is only interested in a single team?","qvi":"Gói nào được thiết kế dành cho người đăng ký chỉ quan tâm đến một đội duy nhất?","opts":["The TBC Platinum Plan","The TBC Gold Plan","The TBC Silver Plan","The TBC Copper Plan"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Gói Silver: \"Most live games played by a team of your choice\" và \"Stream games played by your favorite TBC team\" → dành cho người chỉ theo dõi một đội.\n(A) Gói TBC Platinum\n(B) Gói TBC Gold\n(C) Gói TBC Silver\n(D) Gói TBC Copper"},{"n":167,"q":"How much is the TBC Gold Plan?","qvi":"Giá của gói TBC Gold là bao nhiêu?","opts":["$9 per month","$19 per month","$29 per year","$49 per year"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Gói Gold: \"$19/month or $99/year\" → 19 đô la mỗi tháng. ($9/month và $49/year là gói Silver; $29/year là gói Copper.)\n(A) 9 đô la mỗi tháng\n(B) 19 đô la mỗi tháng\n(C) 29 đô la mỗi năm\n(D) 49 đô la mỗi năm"}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following blog post.","passages":["<h3>Regina’s Art World Blog</h3><p>As regular readers of my blog know, over the past few weeks, I have concentrated on the revitalization of the Brentler Heights waterfront district by developer and former architect David Greeley. — <span class=\"pos\">[1]</span> —. By far, the most impressive result of this program is the renovation of a former industrial building on Paxton Street. The building’s first floor now houses a popular coffee shop and bookstore, and its beautifully landscaped gardens include creative metal sculptures. — <span class=\"pos\">[2]</span> —. I am pleased to report that the second floor will be occupied by the Brentler Heights Gallery.</p><p>The gallery will be run by Francine Skandar, a Brentler Heights artist I met years ago at a jewelry-making workshop. I always admired her work, and I obtained many of her creations to sell at my shop. I was delighted to learn that she will be managing this high-profile gallery. On a media tour, Ms. Skandar highlighted how Mr. Greeley retained nearly all of the Paxton Street building’s original features to give it a vintage character. — <span class=\"pos\">[3]</span> —. This makes it an ideal backdrop for all types of art.</p><p>The gallery’s inaugural exhibit will showcase Ms. Skandar’s work. — <span class=\"pos\">[4]</span> —. The grand opening will occur on June 8 and 9 from 2:00 P.M. to 7:00 P.M. For more information, visit www.brentlerheightsgallery.org.</p><p>—Regina Nguyen, May 2</p>"],"vi":"Blog Thế giới Nghệ thuật của Regina\n\nNhư các độc giả thường xuyên của blog tôi đã biết, trong vài tuần qua, tôi đã tập trung viết về việc hồi sinh khu vực bờ sông Brentler Heights do nhà phát triển kiêm cựu kiến trúc sư David Greeley thực hiện. — [1] —. Cho đến nay, kết quả ấn tượng nhất của chương trình này chính là việc cải tạo một tòa nhà công nghiệp cũ trên phố Paxton. Tầng một của tòa nhà hiện có một quán cà phê và hiệu sách rất được yêu thích, và các khu vườn được thiết kế cảnh quan đẹp mắt có những tác phẩm điêu khắc kim loại sáng tạo. — [2] —. Tôi rất vui được thông báo rằng tầng hai sẽ là nơi đặt Phòng trưng bày Brentler Heights (Brentler Heights Gallery).\n\nPhòng trưng bày sẽ do Francine Skandar điều hành – một nghệ sĩ ở Brentler Heights mà tôi đã gặp nhiều năm trước trong một buổi hội thảo làm trang sức. Tôi luôn ngưỡng mộ tác phẩm của cô ấy, và tôi đã nhập nhiều sản phẩm sáng tạo của cô để bán tại cửa hàng của mình. Tôi rất vui khi biết rằng cô ấy sẽ quản lý phòng trưng bày danh tiếng này. Trong một chuyến tham quan dành cho truyền thông, bà Skandar đã nhấn mạnh cách ông Greeley giữ lại gần như toàn bộ các đặc điểm nguyên bản của tòa nhà trên phố Paxton để tạo nên nét cổ điển. — [3] —. Điều này khiến nó trở thành phông nền lý tưởng cho mọi loại hình nghệ thuật.\n\nTriển lãm khai mạc của phòng trưng bày sẽ trưng bày tác phẩm của bà Skandar. — [4] —. Lễ khai trương chính thức sẽ diễn ra vào ngày 8 và 9 tháng 6, từ 2:00 chiều đến 7:00 tối. Để biết thêm thông tin, hãy truy cập www.brentlerheightsgallery.org.\n\n— Regina Nguyen, ngày 2 tháng 5","qs":[{"n":168,"q":"What topic is reported on in the blog post?","qvi":"Bài đăng trên blog đề cập đến chủ đề nào?","opts":["The transformation of a city district","The new publication released by a local architect","An art class given at the Brentler Heights Gallery","A grant given to Brentler Heights artists"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"I have concentrated on the revitalization of the Brentler Heights waterfront district\" → paraphrase: revitalization of ... district = transformation of a city district.\n(A) Sự chuyển mình của một khu vực trong thành phố\n(B) Một ấn phẩm mới được phát hành bởi một kiến trúc sư địa phương\n(C) Một lớp học nghệ thuật được tổ chức tại Phòng trưng bày Brentler Heights\n(D) Một khoản tài trợ được trao cho các nghệ sĩ tại Brentler Heights"},{"n":169,"q":"What is indicated about Ms. Skandar?","qvi":"Điều gì được đề cập về bà Skandar?","opts":["She teaches jewelry-making classes at a university.","She was a supplier for Ms. Nguyen’s business.","She has lived in Brentler Heights for most of her life.","She creates large metal sculptures for gardens."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Regina Nguyen viết: \"I obtained many of her creations to sell at my shop.\" (Tôi đã nhập nhiều sản phẩm của cô ấy để bán tại cửa hàng của tôi.) → bà Skandar là nhà cung cấp cho cửa hàng của bà Nguyen.\n(A) Bà dạy các lớp chế tác trang sức tại một trường đại học.\n(B) Bà từng là nhà cung cấp cho doanh nghiệp của bà Nguyen.\n(C) Bà đã sống ở Brentler Heights trong phần lớn cuộc đời mình.\n(D) Bà tạo ra các tác phẩm điêu khắc kim loại cỡ lớn cho khu vườn."},{"n":170,"q":"What is true about the Brentler Heights Gallery?","qvi":"Điều gì đúng về Phòng trưng bày Brentler Heights?","opts":["It opened five years ago in another location.","It is located in an older, refurbished space.","It occupies two floors of a building.","It will be managed by Mr. Greeley."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"the renovation of a former industrial building on Paxton Street ... the second floor will be occupied by the Brentler Heights Gallery\" → phòng trưng bày nằm trong tòa nhà công nghiệp cũ đã được cải tạo. (C) sai: chỉ tầng hai; (D) sai: do bà Skandar quản lý.\n(A) Nó được mở cách đây năm năm tại một địa điểm khác.\n(B) Nó tọa lạc trong một không gian cũ đã được cải tạo lại.\n(C) Nó chiếm hai tầng của một tòa nhà.\n(D) Nó sẽ do ông Greeley quản lý."},{"n":171,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“In the future, Ms. Skandar plans to feature collections from other local artists.”","qvi":"Câu sau đây nên được đặt ở vị trí nào trong các vị trí được đánh dấu [1], [2], [3], và [4]?\n“Trong tương lai, bà Skandar dự định sẽ trưng bày các bộ sưu tập của những nghệ sĩ địa phương khác.”","opts":["[1]","[2]","[3]","[4]"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Câu trước vị trí [4]: \"The gallery’s inaugural exhibit will showcase Ms. Skandar’s work.\" (Triển lãm đầu tiên trưng bày tác phẩm của bà Skandar) → câu cần điền nối tiếp tự nhiên: \"Trong tương lai, bà sẽ trưng bày tác phẩm của các nghệ sĩ địa phương khác\" (other local artists đối lập với tác phẩm của chính bà)."}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Liz Yuen (8:58 A.M.)</b></p><p>Hi, all. Thank you for your prompt feedback on the Web site content I sent out in the group e-mail. Everyone agrees that the photos and the accompanying content do not seem to market the calendars strongly enough.</p></div><div class=\"msg\"><p><b>Helen Black (8:59 A.M.)</b></p><p>Right. But, to confirm that we’re looking at the same material—there are several photos showing our desktop calendar each with the caption “The promise of a new year with a calendar from Stenmex Stationery.”</p></div><div class=\"msg\"><p><b>Liz Yuen (9:01 A.M.)</b></p><p>That’s correct. But the main problem is that the photos and the content that accompanies them need to be more engaging and interactive.</p></div><div class=\"msg\"><p><b>Jeff Spina (9:02 A.M.)</b></p><p>I agree. What if we ask customers to send us their written comments on how they use our calendars to help them organize their home offices? They could also send us a picture of their home office with our calendar in the image.</p></div><div class=\"msg\"><p><b>Helen Black (9:04 A.M.)</b></p><p>I’d be happy to share a photo of my own setup—from one of the days that I’m working from home. And I could write an explanation of how using the calendar helps me keep track of things. We could use that as an example for customers to follow.</p></div><div class=\"msg\"><p><b>Liz Yuen (9:05 A.M.)</b></p><p>Great idea. And what about the problems with the functionality of the Web site?</p></div><div class=\"msg\"><p><b>Jeff Spina (9:06 A.M.)</b></p><p>That would be great, Helen.</p></div><div class=\"msg\"><p><b>Helen Black (9:07 A.M.)</b></p><p>I saw those.</p></div><div class=\"msg\"><p><b>Jeff Spina (9:08 A.M.)</b></p><p>I’ll speak with Ryeo Jee about that. Her team should be able to get the pop-up window and social media links working again soon.</p></div><div class=\"msg\"><p><b>Liz Yuen (9:09 A.M.)</b></p><p>Thanks, Jeff. Once the site is functional and we have our content finalized, her team can update the home page with what we have decided.</p></div>"],"vi":"Liz Yuen (8:58 sáng)\nChào mọi người. Cảm ơn các bạn đã phản hồi nhanh về nội dung trang web mà tôi đã gửi trong e-mail nhóm. Mọi người đều đồng ý rằng các bức ảnh và nội dung đi kèm dường như chưa quảng bá cho các cuốn lịch đủ mạnh.\n\nHelen Black (8:59 sáng)\nĐúng vậy. Nhưng để chắc rằng chúng ta đang xem cùng một tài liệu — có mấy bức ảnh cho thấy lịch để bàn của chúng ta, mỗi bức kèm chú thích “Lời hứa về một năm mới cùng cuốn lịch từ Văn phòng phẩm Stenmex”.\n\nLiz Yuen (9:01 sáng)\nĐúng rồi. Nhưng vấn đề chính là các bức ảnh và nội dung đi kèm cần hấp dẫn và tương tác hơn.\n\nJeff Spina (9:02 sáng)\nTôi đồng ý. Hay là chúng ta đề nghị khách hàng gửi cho chúng ta nhận xét bằng văn bản về cách họ dùng lịch của chúng ta để sắp xếp văn phòng tại nhà? Họ cũng có thể gửi cho chúng ta một bức ảnh văn phòng tại nhà của họ có cuốn lịch của chúng ta trong ảnh.\n\nHelen Black (9:04 sáng)\nTôi rất vui được chia sẻ ảnh góc làm việc của mình — chụp vào một trong những ngày tôi làm việc tại nhà. Và tôi có thể viết một đoạn giải thích về cách dùng lịch giúp tôi theo dõi công việc. Chúng ta có thể dùng nó làm ví dụ để khách hàng làm theo.\n\nLiz Yuen (9:05 sáng)\nÝ tưởng hay. Còn các vấn đề về chức năng của trang web thì sao?\n\nJeff Spina (9:06 sáng)\nVậy thì tuyệt quá, Helen.\n\nHelen Black (9:07 sáng)\nTôi đã thấy những lỗi đó.\n\nJeff Spina (9:08 sáng)\nTôi sẽ nói với Ryeo Jee về việc đó. Nhóm của cô ấy sẽ sớm làm cho cửa sổ bật lên và các liên kết mạng xã hội hoạt động trở lại.\n\nLiz Yuen (9:09 sáng)\nCảm ơn, Jeff. Khi trang web đã hoạt động bình thường và chúng ta đã hoàn thiện nội dung, nhóm của cô ấy có thể cập nhật trang chủ với những gì chúng ta đã quyết định.","qs":[{"n":172,"q":"What are the chat participants discussing?","qvi":"Những người tham gia cuộc trò chuyện đang thảo luận về điều gì?","opts":["Changes to a Web site","Feedback from customers","How to order new stationery","What marketing firm to select"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Liz mở đầu: \"Thank you for your prompt feedback on the Web site content ...\"; cả nhóm bàn cách sửa ảnh/nội dung và lỗi chức năng của trang web, cuối cùng \"her team can update the home page\" → thay đổi trang web. (B) sai: feedback là của đồng nghiệp, không phải khách hàng.\n(A) Những thay đổi đối với một trang web\n(B) Phản hồi từ khách hàng\n(C) Cách đặt mua văn phòng phẩm mới\n(D) Việc lựa chọn một công ty tiếp thị"},{"n":173,"q":"What is indicated about Ms. Black?","qvi":"Điều gì được đề cập về bà Black?","opts":["She is a freelance photographer.","She sometimes works from home.","She designed a popular office calendar.","She bought new office furniture recently."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Helen Black (9:04): \"a photo of my own setup—from one of the days that I’m working from home\" → bà có những ngày làm việc tại nhà = sometimes works from home.\n(A) Bà là một nhiếp ảnh gia tự do.\n(B) Bà thỉnh thoảng làm việc tại nhà.\n(C) Bà đã thiết kế một cuốn lịch văn phòng được ưa chuộng.\n(D) Bà gần đây đã mua đồ nội thất văn phòng mới."},{"n":174,"q":"At 9:07 A.M., what does Ms. Black imply when she writes, “I saw those”?","qvi":"Vào lúc 9:07 sáng, bà Black ngụ ý điều gì khi viết: “I saw those”?","opts":["She has selected some photographs.","She accepted Ms. Yuen’s meeting request.","She received several e-mails from Mr. Spina.","She knows that a Web site is not working correctly."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Liz (9:05) hỏi: \"what about the problems with the functionality of the Web site?\" → Helen: \"I saw those\" (tôi đã thấy những lỗi đó) → bà biết trang web đang hoạt động không đúng. Sau đó Jeff nói sẽ nhờ nhóm sửa pop-up và các liên kết mạng xã hội.\n(A) Bà đã chọn một số bức ảnh.\n(B) Bà đã chấp nhận lời mời họp của bà Yuen.\n(C) Bà đã nhận được một số email từ ông Spina.\n(D) Bà biết rằng một trang web đang gặp sự cố."},{"n":175,"q":"What does Ms. Yuen thank Mr. Spina for?","qvi":"Bà Yuen cảm ơn ông Spina vì điều gì?","opts":["Offering to contact a colleague","Finalizing an employee contract","Reviewing Ms. Jee’s performance","Taking photographs of a workspace"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Jeff Spina (9:08): \"I’ll speak with Ryeo Jee about that.\" → Liz (9:09): \"Thanks, Jeff.\" → cảm ơn vì ông đề nghị liên hệ với một đồng nghiệp (Ryeo Jee).\n(A) Đề nghị liên hệ với một đồng nghiệp\n(B) Hoàn tất hợp đồng cho một nhân viên\n(C) Đánh giá hiệu suất làm việc của bà Jee\n(D) Chụp ảnh không gian làm việc"}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following article and e-mail.","passages":["<h3>Hillside House Is Ready for Business</h3><p>AUCKLAND (2 April)—Hillside House, Auckland’s newest and most spectacular event space, is now open. This unique venue is a secluded haven only minutes away from the city centre. Its glass walls give guests an enchanted view of green gardens and bright flowers, while multiple windows in the ceiling make the sky part of the interior decoration.</p><p>Hillside House is the perfect setting for weddings and other social gatherings, as well as corporate events. The kitchen is under the direction of Chef Bashu Malik, a two-time Franklin Heard Foundation winner. Chef Malik oversees Hillside House’s menus, whether the event hosts choose eclectic small plates, a family-style dinner, or a buffet brunch.</p><p>“Choosing the right venue is the key to success,” says Hillside House Managing Director Russell Isley. “We offer everything—a beautiful setting, an experienced staff, and great food. Our events coordinator will work with you to make your wedding or corporate function an occasion to remember.”</p>","<div class=\"hdr\"><p><b>To:</b> Hayley Colling &lt;hcolling@kitchendesigns.co.nz&gt;</p><p><b>From:</b> Reka Taimona &lt;rtaimona@hillsidehouse.co.nz&gt;</p><p><b>Date:</b> 10 May</p><p><b>Subject:</b> Information</p><p><b>Attachment:</b> Hillside House options</p></div><p>Dear Ms. Colling:</p><p>Thank you for reaching out to Hillside House about your upcoming product launch! Yes, 16 June is available; your Kitchen Designs corporate celebration is now on our schedule.</p><p>In preparation for the event, please note that we offer several unique branding opportunities. For example, we can display your company’s logo in neon lights and hang up banners. Chef Malik and his staff can also work with you to include logos on food items or a cake. I am attaching information about the menu options and pricing. We have a state-of-the-art sound system and audiovisual equipment for speeches and presentations. If you would like entertainment for your event, I can also supply you with a list of bands and musicians.</p><p>Please let me know if you have any other questions. We at Hillside House look forward to hosting your event.</p><p>Sincerely,</p><p>Reka Taimona, Events Coordinator<br>Hillside House</p>"],"vi":"BÀI BÁO\nHillside House Sẵn Sàng Đi Vào Hoạt Động Kinh Doanh\n\nAUCKLAND (ngày 2 tháng 4) — Hillside House, địa điểm tổ chức sự kiện mới nhất và ấn tượng nhất của Auckland, hiện đã chính thức mở cửa. Địa điểm độc đáo này là một không gian yên tĩnh, tách biệt nhưng chỉ cách trung tâm thành phố vài phút di chuyển. Những bức tường kính cho phép khách mời chiêm ngưỡng khung cảnh đầy mê hoặc của các khu vườn xanh mướt và hoa cỏ rực rỡ, trong khi các cửa sổ lớn trên trần nhà khiến bầu trời trở thành một phần của thiết kế nội thất.\n\nHillside House là bối cảnh hoàn hảo cho các đám cưới và các buổi tụ họp xã hội khác, cũng như các sự kiện doanh nghiệp. Việc ẩm thực được phụ trách bởi Bếp trưởng Bashu Malik, người từng hai lần giành giải thưởng Franklin Heard Foundation. Bếp trưởng Malik giám sát các thực đơn của Hillside House, dù sự kiện là những bữa tiệc nhỏ mang phong cách đa dạng, bữa tối dùng chung theo kiểu gia đình hay tiệc buffet brunch.\n\n“Lựa chọn địa điểm phù hợp là chìa khóa của thành công,” ông Russell Isley, Giám đốc Điều hành của Hillside House, cho biết. “Chúng tôi mang đến mọi thứ — một khung cảnh tuyệt đẹp, đội ngũ nhân viên giàu kinh nghiệm và ẩm thực tuyệt vời. Đội ngũ tổ chức sự kiện của chúng tôi sẽ phối hợp chặt chẽ với bạn để biến đám cưới hay sự kiện doanh nghiệp của bạn thành một dịp đáng nhớ.”\n\nEMAIL\nNgười nhận: Hayley Colling <hcolling@kitchendesigns.co.nz>\nNgười gửi: Reka Taimona <rtaimona@hillsidehouse.co.nz>\nNgày: 10 tháng 5\nChủ đề: Thông tin\nTệp đính kèm: Các lựa chọn tại Hillside House\n\nKính gửi bà Colling,\n\nCảm ơn bà đã liên hệ với Hillside House về sự kiện ra mắt sản phẩm sắp tới của bà. Vâng, ngày 16 tháng 6 vẫn còn trống; và buổi tiệc kỷ niệm của công ty Kitchen Designs hiện đã được đưa vào lịch của chúng tôi.\n\nĐể chuẩn bị cho sự kiện, xin bà lưu ý rằng chúng tôi cung cấp nhiều cơ hội xây dựng thương hiệu độc đáo. Ví dụ, chúng tôi có thể trưng bày logo công ty của bà trên đèn neon và treo băng rôn. Bếp trưởng Malik và đội ngũ của ông cũng có thể in logo của bà lên các món ăn hoặc trên bánh. Tôi xin đính kèm thông tin về các lựa chọn thực đơn và giá cả. Chúng tôi có hệ thống âm thanh hiện đại và thiết bị nghe nhìn phục vụ cho các bài phát biểu và phần thuyết trình. Nếu bà muốn có chương trình giải trí cho sự kiện, chúng tôi cũng có thể sắp xếp danh sách các ban nhạc và nhạc sĩ.\n\nXin hãy cho tôi biết nếu bà còn bất kỳ câu hỏi nào khác. Chúng tôi tại Hillside House rất mong được tổ chức sự kiện cho bà.\n\nTrân trọng,\nReka Taimona\nĐiều phối viên sự kiện\nHillside House","qs":[{"n":176,"q":"What is indicated in the article about Hillside House?","qvi":"Theo bài báo, điều gì được đề cập về Hillside House?","opts":["It is far from downtown Auckland.","It is located in a recently renovated building.","It features a view of the outdoors.","It will be purchased by Mr. Isley."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Bài báo, đoạn 1: \"Its glass walls give guests an enchanted view of green gardens and bright flowers, while multiple windows in the ceiling make the sky part of the interior decoration.\" (Tường kính cho khách ngắm vườn xanh và hoa, cửa sổ trên trần đưa bầu trời vào nội thất) → có tầm nhìn ra ngoài trời. (A) sai vì \"only minutes away from the city centre\" (chỉ cách trung tâm vài phút).\n(A) Nó nằm xa trung tâm thành phố Auckland.\n(B) Nó nằm trong một tòa nhà vừa được cải tạo.\n(C) Nó có tầm nhìn ra không gian ngoài trời.\n(D) Nó sẽ được ông Isley mua lại."},{"n":177,"q":"In the article, the word “function” in paragraph 3, line 7, is closest in meaning to","qvi":"Trong bài viết, từ “function” ở đoạn 3, dòng 7, gần nghĩa nhất với từ nào?","opts":["occupation","use","organization","gathering"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"to make your wedding or corporate function an occasion to remember\" — \"corporate function\" = sự kiện/buổi tiệc của doanh nghiệp, đặt cạnh \"wedding\" → \"function\" ở đây nghĩa là buổi tụ họp, sự kiện = gathering.\n(A) Nghề nghiệp\n(B) Công dụng\n(C) Tổ chức\n(D) Buổi tụ họp"},{"n":178,"q":"What is one purpose of the e-mail?","qvi":"Mục đích của email là gì?","opts":["To offer a discount on a service","To request feedback on a menu","To provide a reminder about a deadline","To confirm a reservation for a party"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Email, đoạn 1: \"Yes, 16 June is available; your Kitchen Designs corporate celebration is now on our schedule.\" (Ngày 16/6 còn trống; buổi tiệc của Kitchen Designs đã được đưa vào lịch) → xác nhận đặt chỗ cho bữa tiệc.\n(A) Đề nghị giảm giá một dịch vụ\n(B) Yêu cầu phản hồi về thực đơn\n(C) Nhắc nhở về một thời hạn\n(D) Xác nhận việc đặt chỗ cho một bữa tiệc"},{"n":179,"q":"What did Ms. Taimona send with the e-mail?","qvi":"Bà Taimona đã gửi kèm gì trong email?","opts":["Images of decorations","A list of musicians","Details about food and costs","Designs for a corporate logo"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Email, đoạn 2: \"I am attaching information about the menu options and pricing.\" (Tôi đính kèm thông tin về các lựa chọn thực đơn và giá cả) → menu options and pricing = food and costs. (B) sai: danh sách ban nhạc chỉ được đề nghị gửi nếu bà Colling muốn (\"I can also supply you with...\").\n(A) Hình ảnh trang trí\n(B) Danh sách nhạc sĩ\n(C) Thông tin chi tiết về đồ ăn và chi phí\n(D) Các bản thiết kế cho logo công ty"},{"n":180,"q":"What can be concluded about Ms. Colling’s corporate event?","qvi":"Có thể kết luận điều gì về sự kiện doanh nghiệp của bà Colling?","opts":["It will feature food prepared by an award-winning chef.","It will be attended by more than 100 people.","It will conclude with a presentation of awards to Kitchen Designs staff.","It will include music performed by a live band."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Kết hợp 2 bài: Email: sự kiện của bà Colling được tổ chức tại Hillside House, và \"Chef Malik and his staff can also work with you to include logos on food items\". Bài báo: \"The kitchen is under the direction of Chef Bashu Malik, a two-time Franklin Heard Foundation winner. Chef Malik oversees Hillside House’s menus\" (Bếp trưởng Malik hai lần đoạt giải Franklin Heard Foundation và giám sát thực đơn) → đồ ăn do đầu bếp từng đoạt giải chuẩn bị. (D) sai vì ban nhạc chỉ là lựa chọn nếu bà muốn.\n(A) Sự kiện sẽ có các món ăn do một đầu bếp đạt giải thưởng chuẩn bị.\n(B) Sự kiện sẽ có hơn 100 người tham dự.\n(C) Sự kiện sẽ kết thúc bằng lễ trao giải cho nhân viên của Kitchen Designs.\n(D) Sự kiện sẽ có phần biểu diễn âm nhạc trực tiếp."}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following e-mails.","passages":["<div class=\"hdr\"><p><b>To:</b> Customer Service &lt;customerservice@takembootcompany.com&gt;</p><p><b>From:</b> Bella Meyers &lt;b.meyers@leadmail.com&gt;</p><p><b>Date:</b> 15 August</p><p><b>Subject:</b> Order 13783</p></div><p>Hello,</p><p>I recently ordered a pair of your Western boots in style Erin, size 40, in the chocolate colour. The boots arrived yesterday, but unfortunately, their actual colour is different from the colour pictured on your Web site. I had been hoping to wear the boots to a special event next month, but they are much darker than expected and do not match my planned outfit.</p><p>I would like to exchange the boots for another pair of the same style and size but in the terracotta colour. Please let me know how to proceed. I have purchased several pairs of boots from your company in the past and have always been pleased with their durability and comfort.</p><p>Bella Meyers</p>","<div class=\"hdr\"><p><b>To:</b> Bella Meyers &lt;b.meyers@leadmail.com&gt;</p><p><b>From:</b> Customer Service &lt;customerservice@takembootcompany.com&gt;</p><p><b>Date:</b> 16 August</p><p><b>Subject:</b> RE: Order 13783</p></div><p>Dear Ms. Meyers,</p><p>Thank you for your e-mail. I am sorry you were disappointed with your order. We are happy to arrange an exchange as long as the boots you wish to return have not been worn.</p><p>At the moment, boots in the size, style, and colour you are requesting are out of stock. Because we are a small company, our inventory is not always fully available. Other than what you have purchased, we currently have the Erin boots of your size in the following colours: sand and forest. Since you are interested in a paler colour, I recommend sand. It is a warm shade and very versatile. Additionally, we have other styles available in your preferred colour, including Viola boots, our most popular style.</p><p>Please let me know if you would like to exchange your boots for any of the above options. If so, I can send you a postage-paid return label via e-mail for you to print at home.</p><p>Thank you for your business. If you have not signed up for our newsletter yet, I suggest you do. We offer discounts on discontinued styles.</p><p>Sincerely,</p><p>Brendan Stephens, Customer Service Representative<br>Takem Boot Company</p>"],"vi":"EMAIL 1\nNgười nhận: Bộ phận Chăm sóc Khách hàng <customerservice@takembootcompany.com>\nNgười gửi: Bella Meyers <b.meyers@leadmail.com>\nNgày: 15 tháng 8\nChủ đề: Đơn hàng 13783\n\nXin chào,\n\nTôi vừa đặt mua một đôi bốt Western mẫu Erin, size 40, màu sô-cô-la của công ty bạn. Đôi bốt đã được giao ngày hôm qua, nhưng thật không may, màu sắc thực tế khác với màu được hiển thị trên trang web của bạn. Tôi đã hy vọng sẽ mang đôi bốt này trong một sự kiện đặc biệt vào tháng tới, nhưng chúng sẫm màu hơn tôi mong đợi và không phù hợp với trang phục mà tôi đã dự định.\n\nTôi muốn đổi đôi bốt này sang một đôi khác cùng mẫu và cùng kích cỡ, nhưng màu đất nung (terracotta). Xin vui lòng cho tôi biết cách thức tiến hành. Trước đây tôi đã mua nhiều đôi bốt từ công ty bạn và luôn hài lòng với độ bền cũng như sự thoải mái của sản phẩm.\n\nBella Meyers\n\nEMAIL 2\nNgười nhận: Bella Meyers <b.meyers@leadmail.com>\nNgười gửi: Bộ phận Chăm sóc Khách hàng <customerservice@takembootcompany.com>\nNgày: 16 tháng 8\nChủ đề: RE: Đơn hàng 13783\n\nKính gửi bà Meyers,\n\nCảm ơn bà đã gửi email. Chúng tôi rất tiếc khi biết bà đã thất vọng về đơn hàng của mình. Chúng tôi sẵn sàng sắp xếp việc đổi hàng, miễn là đôi bốt bà muốn trả lại chưa qua sử dụng.\n\nHiện tại, mẫu, kích cỡ và màu sắc mà bà yêu cầu đang hết hàng. Vì chúng tôi là một công ty nhỏ, nên lượng hàng tồn kho không phải lúc nào cũng đầy đủ. Ngoài sản phẩm bà đã mua, hiện chúng tôi có bốt Erin cùng kích cỡ của bà với các màu sau: màu cát (sand) và màu xanh rừng (forest). Do bà quan tâm đến màu sáng hơn, tôi khuyến nghị màu cát, vì đây là tông màu ấm và rất dễ phối. Ngoài ra, chúng tôi còn có các mẫu khác sẵn có với màu sắc bà ưa thích, bao gồm bốt Viola, mẫu được ưa chuộng nhất của chúng tôi.\n\nXin vui lòng cho tôi biết nếu bà muốn đổi bốt sang bất kỳ lựa chọn nào nêu trên. Nếu có, tôi có thể gửi nhãn trả hàng đã thanh toán phí bưu điện qua email để bà in tại nhà.\n\nCảm ơn bà đã tin tưởng mua sắm với chúng tôi. Nếu bà chưa đăng ký nhận bản tin, tôi khuyên bà nên đăng ký. Chúng tôi có chương trình giảm giá cho các mẫu đã ngừng sản xuất.\n\nTrân trọng,\nBrendan Stephens\nNhân viên Chăm sóc Khách hàng\nTakem Boot Company","qs":[{"n":181,"q":"What problem is explained in the first e-mail?","qvi":"Vấn đề nào được nêu trong email đầu tiên?","opts":["An order was received later than expected.","A product’s color on a Web site is inaccurate.","Some boots were not as comfortable as previous pairs were.","An item was accidentally ordered in the wrong size."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Email 1, đoạn 1: \"their actual colour is different from the colour pictured on your Web site\" (màu thực tế khác với màu hiển thị trên trang web) → màu sản phẩm trên web không chính xác.\n(A) Một đơn hàng được nhận muộn hơn dự kiến.\n(B) Màu sắc của sản phẩm trên trang web không chính xác.\n(C) Một số đôi bốt không thoải mái như những đôi trước đây.\n(D) Một món hàng đã vô tình được đặt sai kích cỡ."},{"n":182,"q":"What does Ms. Meyers indicate?","qvi":"Bà Meyers cho biết điều gì?","opts":["She has been a frequent customer of Takem Boot Company.","She still needs to buy an outfit for an event.","She had difficulty navigating a Web site.","She prefers dark-colored boots."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Email 1, đoạn 2: \"I have purchased several pairs of boots from your company in the past\" (Trước đây tôi đã mua nhiều đôi bốt từ công ty bạn) → khách hàng thường xuyên. (B) sai vì bà đã có \"planned outfit\"; (D) sai vì bà chê bốt \"much darker than expected\".\n(A) Bà là khách hàng thường xuyên của công ty Takem Boot.\n(B) Bà vẫn cần mua trang phục cho một sự kiện.\n(C) Bà gặp khó khăn khi sử dụng một trang web.\n(D) Bà thích những đôi bốt có màu tối."},{"n":183,"q":"What color is currently NOT available for boots in the Erin style?","qvi":"Màu nào hiện không có sẵn cho mẫu bốt Erin?","opts":["Sand","Forest","Chocolate","Terracotta"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Bà Meyers muốn đổi sang Erin màu terracotta (email 1). Email 2: \"boots in the size, style, and colour you are requesting are out of stock\" (mẫu, cỡ, màu bà yêu cầu đang hết hàng) → terracotta hết hàng. \"Other than what you have purchased (chocolate), we currently have the Erin boots ... sand and forest\" → (A), (B), (C) vẫn còn.\n(A) Màu cát (Sand)\n(B) Màu xanh rừng (Forest)\n(C) Màu nâu sô-cô-la (Chocolate)\n(D) Màu đất nung (Terracotta)"},{"n":184,"q":"What does the second e-mail suggest about Takem Boot Company?","qvi":"Email thứ hai gợi ý điều gì về công ty Takem Boot?","opts":["It has stores in several locations.","It charges a shipping fee for returns.","It sells a lot of Viola boots.","It is the most popular boot company in the region."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Email 2, đoạn 2: \"Viola boots, our most popular style\" (bốt Viola, mẫu được ưa chuộng nhất của chúng tôi) → công ty bán được rất nhiều bốt Viola. (B) sai vì nhãn trả hàng \"postage-paid\" (đã trả phí bưu điện); (D) sai vì \"most popular\" nói về mẫu giày, không phải công ty.\n(A) Công ty có cửa hàng tại nhiều địa điểm.\n(B) Công ty tính phí vận chuyển cho việc đổi/trả hàng.\n(C) Công ty bán rất nhiều giày mẫu Viola.\n(D) Công ty là hãng giày được ưa chuộng nhất trong khu vực."},{"n":185,"q":"What does Mr. Stephens offer to do?","qvi":"Ông Stephens đề nghị làm điều gì?","opts":["Print a document","E-mail a shipping label","Send a product catalog","Give a discount on new-style boots"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Email 2, đoạn 3: \"I can send you a postage-paid return label via e-mail for you to print at home.\" (Tôi có thể gửi nhãn trả hàng đã trả phí qua email để bà in tại nhà) → gửi nhãn vận chuyển qua email. (A) sai vì người in là bà Meyers; (D) sai vì giảm giá dành cho mẫu đã ngừng sản xuất (discontinued styles).\n(A) In một tài liệu\n(B) Gửi nhãn vận chuyển qua email\n(C) Gửi danh mục sản phẩm\n(D) Giảm giá cho các mẫu giày mới"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following e-mail, article, and Web page.","passages":["<div class=\"hdr\"><p><b>To:</b> Jessica Marpone &lt;jmarpone@halecityca.gov&gt;</p><p><b>From:</b> Greg Tanner &lt;gtanner@halecitynews.com&gt;</p><p><b>Date:</b> July 1</p><p><b>Subject:</b> Community comments</p></div><p>Dear Ms. Marpone,</p><p>My last article about East Core Park attracted quite a few online comments. The comments were from residents complaining about overgrown weeds and fallen branches on the Blue Trail. They say the Red Trail is in good condition, but maintenance issues have persisted on the Blue Trail for quite some time.</p><p>As the newest member of the city council, you might not have heard many complaints yet. However, if you do get briefings regarding the situation, I would be grateful for any updates you can pass along. I reached out to parks commissioner Oscar Lunes for comments about this, but he hasn’t responded. Someone mentioned he might be busy preparing for retirement.</p><p>Sincerely,</p><p>Greg Tanner<br>Hale City News</p>","<h3>City Parks Department Launches Volunteer Initiative</h3><p>By Greg Tanner</p><p>Hale City (July 12)—In response to residents’ concerns about conditions on the hiking paths at East Core Park, the Hale City Parks Department offers an explanation and an outline of its plans for trail upkeep.</p><p>“Trail maintenance is transitioning from being performed by city employees to an all-volunteer model,” said newly appointed parks commissioner Helen Yancey. “Before my predecessor stepped down after twenty years of service to the city, he began this shift. The result was a temporary suspension of maintenance on the Blue Trail.”</p><p>Ms. Yancey added that the volunteer model will save money and allow residents greater involvement with the park system. Accordingly, the Hale City Parks Department has scheduled its first volunteer cleanup event, Trail Cleanup Day, on August 12, from 9:00 A.M. to 2:00 P.M. Those interested in volunteering may register online at www.halecityparks.org/events.</p>","<h3>Hale City Parks Department</h3><h4>August Announcements</h4><p>The Hale City Parks Department’s inaugural Trail Cleanup Day, held on August 8, was a great success. An enthusiastic group of volunteers cleared debris and weeds from the Blue Trail at East Core Park and had the path clean and usable just before noon on the bright, warm day.</p><p>Special thanks go to the following participants.</p><ul><li>Amy Harris, for coordinating volunteer efforts and bringing beverages</li><li>Jason Skoda, resident of the adjacent East Heights neighborhood, for lending his power trimmer, pruning shears, and rakes to our crew of volunteers</li></ul><p>We encourage residents to visit this page often to learn about upcoming volunteer events.</p>"],"vi":"EMAIL\nNgười nhận: Jessica Marpone <jmarpone@halecityca.gov>\nNgười gửi: Greg Tanner <gtanner@halecitynews.com>\nNgày: 1 tháng 7\nChủ đề: Ý kiến từ cộng đồng\n\nKính gửi bà Marpone,\n\nBài báo gần đây nhất của tôi về Công viên East Core đã thu hút khá nhiều bình luận trực tuyến. Những bình luận này đến từ các cư dân phàn nàn về cỏ dại mọc um tùm và cành cây gãy đổ trên Đường mòn Blue Trail. Họ cho biết Red Trail đang ở trong tình trạng tốt, nhưng các vấn đề về bảo trì trên Blue Trail đã tồn tại trong một thời gian khá dài.\n\nVì bà là thành viên mới nhất của hội đồng thành phố, có thể bà chưa nghe nhiều khiếu nại về vấn đề này. Tuy nhiên, nếu bà có nhận được các báo cáo tóm tắt liên quan đến tình hình trên, tôi sẽ rất biết ơn nếu bà có thể chia sẻ bất kỳ thông tin cập nhật nào. Tôi đã liên hệ với Ủy viên công viên Oscar Lunes để xin ý kiến, nhưng ông ấy vẫn chưa phản hồi. Có người cho rằng ông ấy có thể đang bận chuẩn bị cho việc nghỉ hưu.\n\nTrân trọng,\nGreg Tanner\nHale City News\n\nBÀI BÁO\nSở Công viên Thành phố Khởi động Sáng kiến Tình nguyện\nBởi Greg Tanner\n\nHale City (ngày 12 tháng 7) — Trước những lo ngại của người dân về tình trạng các lối đi bộ đường dài tại Công viên East Core, Sở Công viên Thành phố Hale đã đưa ra giải thích và phác thảo kế hoạch của mình cho việc bảo trì các tuyến đường mòn.\n\n“Việc bảo dưỡng đường mòn đang được chuyển đổi từ hình thức do nhân viên thành phố thực hiện sang mô hình hoàn toàn dựa vào tình nguyện viên,” bà Helen Yancey, Ủy viên Công viên mới được bổ nhiệm, cho biết. “Trước khi người tiền nhiệm của tôi từ chức sau 20 năm phục vụ thành phố, ông ấy đã bắt đầu sự chuyển đổi này. Kết quả là việc tạm thời ngừng công tác bảo trì trên tuyến Blue Trail.”\n\nBà Yancey cho biết thêm rằng mô hình tình nguyện sẽ giúp tiết kiệm chi phí và cho phép người dân tham gia nhiều hơn vào hệ thống công viên. Theo đó, Sở Công viên Thành phố Hale đã lên lịch cho sự kiện dọn dẹp công viên đầu tiên dành cho tình nguyện viên, mang tên Trail Cleanup Day, vào ngày 12 tháng 8, từ 9:00 sáng đến 2:00 chiều. Những ai quan tâm đến việc tham gia tình nguyện có thể đăng ký trực tuyến tại www.halecityparks.org/events.\n\nTRANG WEB\nSở Công viên Thành phố Hale\nThông báo tháng Tám\n\nNgày Dọn dẹp Đường mòn đầu tiên do Sở Công viên Thành phố Hale tổ chức, diễn ra vào ngày 8 tháng 8, đã thành công tốt đẹp. Một nhóm tình nguyện viên đầy nhiệt huyết đã dọn sạch rác và cỏ dại trên tuyến đường mòn Blue Trail tại Công viên East Core, và con đường đã sạch sẽ, có thể sử dụng được ngay trước buổi trưa trong một ngày thời tiết sáng sủa, ấm áp.\n\nXin gửi lời cảm ơn đặc biệt đến những người tham gia sau:\n• Amy Harris, vì đã điều phối các hoạt động tình nguyện và chuẩn bị đồ uống\n• Jason Skoda, cư dân của khu East Heights lân cận, vì đã cho mượn máy cắt điện, kéo cắt tỉa và cào cho nhóm tình nguyện viên sử dụng\n\nChúng tôi khuyến khích người dân thường xuyên truy cập trang này để tìm hiểu về các sự kiện tình nguyện sắp tới.","qs":[{"n":186,"q":"Why did Mr. Tanner write the e-mail?","qvi":"Tại sao ông Tanner viết email này?","opts":["To inform his supervisor of an upcoming event","To ask for information about trail maintenance","To discuss enlarging a city park","To congratulate a new city council member"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Email: cư dân phàn nàn \"maintenance issues have persisted on the Blue Trail\", và ông Tanner viết \"if you do get briefings regarding the situation, I would be grateful for any updates you can pass along\" (nếu bà nhận được báo cáo về tình hình, tôi rất biết ơn nếu bà chia sẻ thông tin cập nhật) → hỏi thông tin về việc bảo trì đường mòn.\n(A) Để thông báo cho cấp trên về một sự kiện sắp diễn ra\n(B) Để hỏi thông tin về việc bảo trì đường mòn\n(C) Để thảo luận về việc mở rộng một công viên trong thành phố\n(D) Để chúc mừng một thành viên mới của hội đồng thành phố"},{"n":187,"q":"What is suggested about Ms. Yancey?","qvi":"Điều gì được gợi ý về bà Yancey?","opts":["She is a replacement for Mr. Lunes.","She lives near East Core Park.","She trains new park volunteers.","She is a fund-raising specialist."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Kết hợp 2 bài: Email: \"parks commissioner Oscar Lunes ... might be busy preparing for retirement\" (Ủy viên công viên Oscar Lunes có thể đang chuẩn bị nghỉ hưu). Bài báo: \"newly appointed parks commissioner Helen Yancey\" và \"Before my predecessor stepped down after twenty years...\" (bà Yancey là ủy viên công viên mới, người tiền nhiệm đã nghỉ) → bà Yancey thay thế ông Lunes.\n(A) Bà là người thay thế cho ông Lunes.\n(B) Bà sống gần công viên East Core.\n(C) Bà huấn luyện các tình nguyện viên mới.\n(D) Bà là chuyên gia gây quỹ."},{"n":188,"q":"What interrupted the maintenance of the Blue Trail?","qvi":"Điều gì đã làm gián đoạn việc bảo trì đường mòn Blue Trail?","opts":["An expansion of the Red Trail","A departmental policy change","A large gathering held at a park","An extended period of wet weather"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Bài báo, đoạn 2: \"Trail maintenance is transitioning from being performed by city employees to an all-volunteer model ... The result was a temporary suspension of maintenance on the Blue Trail.\" (Việc bảo trì chuyển từ nhân viên thành phố sang mô hình hoàn toàn tình nguyện ... kết quả là tạm ngừng bảo trì Blue Trail) → nguyên nhân là thay đổi chính sách của Sở Công viên.\n(A) Việc mở rộng đường mòn Red Trail\n(B) Một thay đổi trong chính sách của bộ phận\n(C) Một sự kiện đông người được tổ chức tại công viên\n(D) Một khoảng thời gian mưa kéo dài"},{"n":189,"q":"What most likely is true about Trail Cleanup Day?","qvi":"Điều nào sau đây có khả năng đúng nhất về Ngày Dọn Dẹp Đường Mòn (Trail Cleanup Day)?","opts":["Mr. Tanner initially planned it.","The work took two days to complete.","Volunteers attended a training session before the event.","The date of the trail cleanup was changed."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Kết hợp 2 bài: Bài báo: \"Trail Cleanup Day, on August 12\" (lên lịch ngày 12/8). Trang web: \"inaugural Trail Cleanup Day, held on August 8\" (thực tế diễn ra ngày 8/8) → ngày dọn dẹp đã bị đổi. (B) sai vì đường mòn sạch \"just before noon\" trong một ngày.\n(A) Ông Tanner là người lên kế hoạch ban đầu.\n(B) Công việc mất hai ngày để hoàn thành.\n(C) Các tình nguyện viên đã tham gia một buổi huấn luyện trước sự kiện.\n(D) Ngày dọn dẹp đường mòn đã bị thay đổi."},{"n":190,"q":"According to the Web page, what did one nearby resident provide volunteers with?","qvi":"Theo trang web, một cư dân gần đó đã cung cấp gì cho các tình nguyện viên?","opts":["Breakfast foods","Advice on hiking for health","Landscaping tools","Transportation to a park"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Trang web: \"Jason Skoda, resident of the adjacent East Heights neighborhood, for lending his power trimmer, pruning shears, and rakes\" (cư dân khu lân cận cho mượn máy cắt, kéo tỉa và cào) → dụng cụ làm vườn (landscaping tools).\n(A) Thức ăn sáng\n(B) Lời khuyên về việc đi bộ đường dài vì sức khỏe\n(C) Dụng cụ làm vườn\n(D) Phương tiện đưa đón đến công viên"}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following e-mails and chart.","passages":["<div class=\"hdr\"><p><b>To:</b> All Staff</p><p><b>From:</b> Miranda Noonan</p><p><b>Date:</b> June 26</p><p><b>Subject:</b> Art auction</p><p><b>Attachment:</b> Donations</p></div><p>Dear Employees,</p><p>Ogunsanya and Bolden Law Firm is hosting our annual art auction, with all proceeds going to building a community garden. Many local artists plan to donate pieces for our auction, and as always, we encourage all amateur artists in our firm to donate work as well. Get out those paintbrushes and pencils and unleash your creativity. It is always a treat to see our colleagues’ art hanging alongside pieces by professional artists!</p><p>This year’s auction will be at Seven Gates Hotel and Restaurant on Friday, July 27, at 7:00 P.M. Our event will be held in the hotel restaurant, which has excellent lighting for our purposes.</p><p>I have attached a chart listing the professional art that has been donated so far. If you are interested in contributing this year, please e-mail me the details about your submission. Keep in mind that photographs, paintings, and drawings are the most popular mediums. However, one local artist donated a large sculpture, which will be the auction’s centerpiece. Apart from that piece, we will only accept sculptures under 50 centimeters tall.</p><p>Best regards,</p><p>Miranda Noonan, Auction Chairperson</p>","<h3>Ogunsanya and Bolden Art Auction: Local Artist Donations</h3><table><tr><th>Name</th><th>Name of piece and medium</th><th>Dimensions</th></tr><tr><td>Brian Healey</td><td><i>Surface of the Moon</i> (photograph)</td><td>45 cm x 76 cm</td></tr><tr><td>Michaela Green</td><td><i>Streetlight</i> (sculpture)</td><td>90 cm</td></tr><tr><td>Shinji Hasegawa</td><td><i>Shuki—Artist’s Dog</i> (drawing)</td><td>30 cm x 45 cm</td></tr><tr><td>Kim Cheung</td><td><i>Cornfield Sunrise</i> (painting)</td><td>40 cm x 70 cm</td></tr></table>","<div class=\"hdr\"><p><b>To:</b> Miranda Noonan</p><p><b>From:</b> Omonuwa Orou</p><p><b>Date:</b> June 29</p><p><b>Subject:</b> Re: Art auction</p></div><p>Hello, Ms. Noonan,</p><p>I am planning to contribute a piece of art again this year, but I’ve noticed its subject is very similar to that of another piece listed in your e-mail attachment. I’ve painted an orchard near my parents’ house as it looks just when the sun is rising above it. Could I ask that my painting be placed away from the similar artwork?</p><p>Thanks,</p><p>Omonuwa Orou</p>"],"vi":"EMAIL 1\nNgười nhận: Toàn thể nhân viên\nNgười gửi: Miranda Noonan\nNgày: 26 tháng 6\nChủ đề: Đấu giá nghệ thuật\nTệp đính kèm: Danh sách tác phẩm quyên góp\n\nKính gửi các nhân viên,\n\nCông ty luật Ogunsanya and Bolden sẽ tổ chức buổi đấu giá nghệ thuật thường niên, với toàn bộ số tiền thu được dùng để xây dựng một khu vườn cộng đồng. Nhiều nghệ sĩ địa phương dự định sẽ quyên góp tác phẩm cho buổi đấu giá, và như mọi năm, chúng tôi cũng khuyến khích tất cả các nghệ sĩ nghiệp dư trong công ty đóng góp tác phẩm của mình. Hãy lấy cọ vẽ và bút chì ra và thỏa sức sáng tạo. Việc được xem các tác phẩm của đồng nghiệp trưng bày cùng với những tác phẩm của các nghệ sĩ chuyên nghiệp luôn là một điều rất thú vị.\n\nBuổi đấu giá năm nay sẽ được tổ chức tại Khách sạn và Nhà hàng Seven Gates vào thứ Sáu, ngày 27 tháng 7, lúc 7:00 tối. Sự kiện sẽ diễn ra trong nhà hàng của khách sạn, nơi có hệ thống chiếu sáng rất tốt, phù hợp với mục đích của chúng ta.\n\nTôi đã đính kèm một bảng liệt kê các tác phẩm nghệ thuật chuyên nghiệp đã được quyên góp cho đến thời điểm hiện tại. Nếu bạn quan tâm đến việc đóng góp trong năm nay, vui lòng gửi email cho tôi với thông tin chi tiết về tác phẩm dự định nộp. Xin lưu ý rằng ảnh chụp, tranh vẽ và tranh phác họa là những loại hình nghệ thuật được ưa chuộng nhất. Tuy nhiên, một nghệ sĩ địa phương đã quyên góp một tác phẩm điêu khắc lớn, tác phẩm này sẽ là tác phẩm trung tâm của buổi đấu giá. Ngoài tác phẩm đó ra, chúng tôi chỉ chấp nhận các tác phẩm điêu khắc cao dưới 50 cm.\n\nTrân trọng,\nMiranda Noonan\nChủ tịch Ban tổ chức Đấu giá\n\nBẢNG\nBuổi đấu giá nghệ thuật Ogunsanya and Bolden: Các tác phẩm quyên góp của nghệ sĩ địa phương\nTên nghệ sĩ | Tên tác phẩm và loại hình | Kích thước\nBrian Healey | Surface of the Moon (Ảnh chụp) | 45 cm × 76 cm\nMichaela Green | Streetlight (Điêu khắc) | 90 cm\nShinji Hasegawa | Shuki—Artist’s Dog (Tranh vẽ) | 30 cm × 45 cm\nKim Cheung | Cornfield Sunrise (Tranh sơn) | 40 cm × 70 cm\n\nEMAIL 2\nNgười nhận: Miranda Noonan\nNgười gửi: Omonuwa Orou\nNgày: 29 tháng 6\nChủ đề: RE: Đấu giá nghệ thuật\n\nXin chào bà Noonan,\n\nTôi đang dự định đóng góp một tác phẩm nghệ thuật cho buổi đấu giá năm nay như mọi năm, nhưng tôi nhận thấy chủ đề của tác phẩm này rất giống với một tác phẩm khác được liệt kê trong tệp đính kèm của email bà gửi. Tôi đã vẽ một khu vườn cây ăn trái gần nhà bố mẹ tôi, khung cảnh trông giống như thời điểm mặt trời vừa mọc phía trên. Tôi xin hỏi liệu bức tranh của tôi có thể được trưng bày ở vị trí cách xa tác phẩm tương tự đó hay không?\n\nCảm ơn,\nOmonuwa Orou","qs":[{"n":191,"q":"What is the purpose of the first e-mail?","qvi":"Mục đích của email đầu tiên là gì?","opts":["To commission a work of art","To stress the importance of community gardens","To inform employees about an upcoming event","To share information about local artists"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Email 1 gửi \"All Staff\": \"Ogunsanya and Bolden Law Firm is hosting our annual art auction\" và \"This year’s auction will be at Seven Gates Hotel and Restaurant on Friday, July 27\" (công ty tổ chức buổi đấu giá nghệ thuật thường niên, diễn ra ngày 27/7) → thông báo cho nhân viên về sự kiện sắp tới.\n(A) Đặt hàng một tác phẩm nghệ thuật\n(B) Nhấn mạnh tầm quan trọng của các khu vườn cộng đồng\n(C) Thông báo cho nhân viên về một sự kiện sắp diễn ra\n(D) Chia sẻ thông tin về các nghệ sĩ địa phương"},{"n":192,"q":"Why does Ms. Noonan comment on the event venue?","qvi":"Tại sao bà Noonan lại đề cập đến địa điểm tổ chức sự kiện?","opts":["To reassure employees that the space will not be too crowded","To explain why the location is appropriate for the event","To ensure guests dress accordingly","To explain why the firm is donating money"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Email 1, đoạn 2: \"Our event will be held in the hotel restaurant, which has excellent lighting for our purposes.\" (nhà hàng có hệ thống chiếu sáng rất tốt, phù hợp với mục đích của chúng ta — trưng bày tranh) → giải thích vì sao địa điểm phù hợp.\n(A) Để trấn an nhân viên rằng không gian sẽ không quá đông\n(B) Để giải thích vì sao địa điểm đó phù hợp cho sự kiện\n(C) Để đảm bảo khách mời ăn mặc phù hợp\n(D) Để giải thích lý do công ty quyên góp tiền"},{"n":193,"q":"What artist donated the centerpiece of the auction?","qvi":"Nghệ sĩ nào đã quyên tặng tác phẩm trung tâm của buổi đấu giá?","opts":["Brian Healey","Michaela Green","Shinji Hasegawa","Kim Cheung"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Kết hợp 2 bài: Email 1: \"one local artist donated a large sculpture, which will be the auction’s centerpiece\" (một nghệ sĩ địa phương tặng một tác phẩm điêu khắc lớn, sẽ là tác phẩm trung tâm). Bảng: tác phẩm điêu khắc duy nhất là \"Streetlight (sculpture) — 90 cm\" của Michaela Green.\n(A) Brian Healey\n(B) Michaela Green\n(C) Shinji Hasegawa\n(D) Kim Cheung"},{"n":194,"q":"What is indicated about Mr. Orou?","qvi":"Điều gì được nhắc đến về ông Orou?","opts":["He has donated art in the past.","He wants his art to be hung near the entrance.","He usually paints every morning.","He has invited his parents to the event."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Email 2: \"I am planning to contribute a piece of art again this year\" (Tôi dự định đóng góp một tác phẩm nữa trong năm nay) → \"again\" cho thấy ông đã từng quyên góp trước đây. (B) sai vì ông chỉ muốn tranh đặt xa tác phẩm tương tự.\n(A) Ông từng quyên góp tác phẩm nghệ thuật trước đây.\n(B) Ông muốn tác phẩm của mình được treo gần lối vào.\n(C) Ông thường vẽ tranh vào mỗi buổi sáng.\n(D) Ông đã mời cha mẹ mình đến sự kiện."},{"n":195,"q":"What piece of art is similar in subject to Mr. Orou’s painting?","qvi":"Tác phẩm nghệ thuật nào có chủ đề tương tự với bức tranh của ông Orou?","opts":["Surface of the Moon","Streetlight","Shuki—Artist’s Dog","Cornfield Sunrise"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Kết hợp 2 bài: Email 2: \"I’ve painted an orchard near my parents’ house as it looks just when the sun is rising above it.\" (Tôi vẽ một vườn cây ăn trái lúc mặt trời đang mọc). Bảng: \"Cornfield Sunrise (painting)\" (Bình minh trên cánh đồng ngô) — cũng là tranh vẽ cánh đồng lúc mặt trời mọc → chủ đề tương tự.\n(A) Surface of the Moon\n(B) Streetlight\n(C) Shuki—Artist’s Dog\n(D) Cornfield Sunrise"}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following e-mails and sign.","passages":["<div class=\"hdr\"><p><b>To:</b> Haruka Maeda &lt;hmaeda@frantaexports.co.uk&gt;</p><p><b>From:</b> Jerome Lennox &lt;j.lennox@silkmail.co.uk&gt;</p><p><b>Date:</b> 7 May</p><p><b>Subject:</b> Job 3723</p><p><b>Attachment:</b> lennox_résumé</p></div><p>Dear Ms. Maeda,</p><p>I am writing regarding the open office manager position (job 3723) at Franta Exports here in my hometown of Liverpool. With eight years of experience in office management and administration, I am confident that I have the skills and expertise required to excel in this role. In my current position as office manager at Wyler International, I am responsible for managing all aspects of office operations, including budgeting, scheduling, and staff management. My résumé is attached.</p><p>I am excited about the possibility of bringing my skills and experience to Franta Exports. I look forward to hearing from you soon.</p><p>Sincerely,</p><p>Jerome Lennox</p>","<div class=\"hdr\"><p><b>To:</b> Jerome Lennox &lt;j.lennox@silkmail.co.uk&gt;</p><p><b>From:</b> Haruka Maeda &lt;hmaeda@frantaexports.co.uk&gt;</p><p><b>Date:</b> 23 May</p><p><b>Subject:</b> Upcoming interview</p></div><p>Dear Mr. Lennox,</p><p>Please respond to this e-mail to verify your intention to participate in a telephone interview with Franta Exports. You are scheduled for an interview with Alisha Scott at 11 A.M. on 28 May for the office manager position.</p><p>Your initial interview is scheduled as an online telephone appointment. You may call from a smartphone or a computer. However, please ensure that you have a stable Internet connection. We will send you a text message 30 minutes before your scheduled interview with further instructions.</p><p>Within two days following your online interview, we will inform you whether we would like to schedule a follow-up in-person appointment at our headquarters in Portsmouth.</p><p>Sincerely,</p><p>Haruka Maeda, Human Resources Associate</p>","<h3>Welcome to the Franta Exports Liverpool Office!</h3><p><b>Office hours:</b> Monday to Saturday from 8 A.M. to 4 P.M.</p><p><b>Office manager:</b> Jerome Lennox</p><p>Franta Exports has eighteen offices worldwide, including five in the United Kingdom at the following convenient locations.</p><ul><li>732 Park Avenue, Portsmouth PO5 3QQ (U.K. Headquarters)</li><li>10 Donegal Lane, Belfast BT1 3JF</li><li>660 Richmond Avenue, Cardiff CF24 2PX</li><li>42 Church Road, Edinburgh EH4 6DU</li><li>9233 Victoria Street, Liverpool CH44 6PX</li></ul>"],"vi":"EMAIL 1\nNgười nhận: Haruka Maeda <hmaeda@frantaexports.co.uk>\nNgười gửi: Jerome Lennox <j.lennox@silkmail.co.uk>\nNgày: 7 tháng 5\nChủ đề: Công việc 3723\nTệp đính kèm: Sơ yếu lý lịch của Lennox\n\nKính gửi bà Maeda,\n\nTôi viết thư này liên quan đến vị trí Quản lý Văn phòng đang tuyển (mã công việc 3723) tại Franta Exports ở thành phố quê hương tôi là Liverpool. Với tám năm kinh nghiệm trong lĩnh vực quản lý và điều hành văn phòng, tôi tin rằng mình có đầy đủ kỹ năng và chuyên môn cần thiết để hoàn thành tốt vai trò này. Trong vị trí hiện tại là Quản lý Văn phòng tại Wyler International, tôi chịu trách nhiệm quản lý toàn bộ hoạt động văn phòng, bao gồm lập ngân sách, sắp xếp lịch làm việc và quản lý nhân sự. Sơ yếu lý lịch của tôi được đính kèm theo email này.\n\nTôi rất mong chờ cơ hội được mang kỹ năng và kinh nghiệm của mình đến Franta Exports. Tôi mong sớm nhận được phản hồi từ bà.\n\nTrân trọng,\nJerome Lennox\n\nEMAIL 2\nNgười nhận: Jerome Lennox <j.lennox@silkmail.co.uk>\nNgười gửi: Haruka Maeda <hmaeda@frantaexports.co.uk>\nNgày: 23 tháng 5\nChủ đề: Cuộc phỏng vấn sắp tới\n\nKính gửi ông Lennox,\n\nVui lòng phản hồi email này để xác nhận ý định tham gia buổi phỏng vấn qua điện thoại với công ty Franta Exports. Ông đã được xếp lịch phỏng vấn với Alisha Scott vào lúc 11 giờ sáng ngày 28 tháng 5 cho vị trí Quản lý Văn phòng.\n\nBuổi phỏng vấn ban đầu của ông sẽ được tổ chức dưới hình thức phỏng vấn trực tuyến qua điện thoại. Ông có thể tham gia bằng điện thoại thông minh hoặc máy tính. Tuy nhiên, xin hãy đảm bảo rằng kết nối Internet của ông ổn định. Chúng tôi sẽ gửi cho ông một tin nhắn văn bản trước 30 phút so với thời gian phỏng vấn đã lên lịch, kèm theo hướng dẫn chi tiết.\n\nTrong vòng hai ngày sau buổi phỏng vấn trực tuyến, chúng tôi sẽ thông báo cho ông biết liệu chúng tôi có muốn sắp xếp một buổi phỏng vấn trực tiếp tiếp theo tại trụ sở chính của công ty ở Portsmouth hay không.\n\nTrân trọng,\nHaruka Maeda\nChuyên viên Nhân sự\n\nTẤM BIỂN\nChào mừng đến với Văn phòng Franta Exports tại Liverpool!\n\nGiờ làm việc: Từ thứ Hai đến thứ Bảy, 8:00 sáng – 4:00 chiều\nQuản lý văn phòng: Jerome Lennox\n\nFranta Exports hiện có 18 văn phòng trên toàn thế giới, trong đó có 5 văn phòng tại Vương quốc Anh ở các địa điểm thuận tiện sau:\n• 732 Park Avenue, Portsmouth PO5 3QQ (Trụ sở chính tại Vương quốc Anh)\n• 10 Donegal Lane, Belfast BT1 3JF\n• 660 Richmond Avenue, Cardiff CF24 2PX\n• 42 Church Road, Edinburgh EH4 6DU\n• 9233 Victoria Street, Liverpool CH44 6PX","qs":[{"n":196,"q":"What is the purpose of the first e-mail?","qvi":"Mục đích của email đầu tiên là gì?","opts":["To express interest in an open position","To answer a question about an office job","To provide notice of a planned meeting","To request a transfer to another office"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Email 1: \"I am writing regarding the open office manager position (job 3723) at Franta Exports\" và \"My résumé is attached.\" (Tôi viết thư về vị trí quản lý văn phòng đang tuyển ... sơ yếu lý lịch đính kèm) → bày tỏ sự quan tâm/ứng tuyển vào vị trí đang tuyển.\n(A) Bày tỏ sự quan tâm đến một vị trí đang tuyển\n(B) Trả lời một câu hỏi về công việc văn phòng\n(C) Thông báo về một cuộc họp sắp tới\n(D) Yêu cầu chuyển công tác sang văn phòng khác"},{"n":197,"q":"In the second e-mail, what does Ms. Maeda request of Mr. Lennox?","qvi":"Trong email thứ hai, bà Maeda yêu cầu ông Lennox điều gì?","opts":["That he travel to Ms. Scott’s office","That he reschedule a telephone conference call","That he complete an online survey","That he confirm an interview appointment"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Email 2, đoạn 1: \"Please respond to this e-mail to verify your intention to participate in a telephone interview\" (Vui lòng trả lời email để xác nhận ý định tham gia buổi phỏng vấn qua điện thoại) → verify = confirm: xác nhận lịch phỏng vấn.\n(A) Đến văn phòng của bà Scott\n(B) Dời lịch cuộc gọi hội nghị qua điện thoại\n(C) Hoàn thành một bản khảo sát trực tuyến\n(D) Xác nhận lịch hẹn phỏng vấn"},{"n":198,"q":"What is indicated on the sign?","qvi":"Tấm biển cho biết điều gì?","opts":["The Franta Exports Liverpool office is open on Sundays until 4 P.M.","Franta Exports is currently hiring an office manager.","Franta Exports has offices in multiple countries.","Franta Exports has eighteen offices in the United Kingdom."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Tấm biển: \"Franta Exports has eighteen offices worldwide, including five in the United Kingdom\" (18 văn phòng trên toàn thế giới, trong đó 5 ở Anh) → có văn phòng ở nhiều quốc gia. (A) sai: mở cửa thứ Hai–thứ Bảy; (B) sai: đã có quản lý Jerome Lennox; (D) sai: chỉ 5 văn phòng ở Anh.\n(A) Văn phòng Franta Exports tại Liverpool mở cửa đến 4 giờ chiều Chủ nhật\n(B) Franta Exports đang tuyển quản lý văn phòng\n(C) Franta Exports có văn phòng ở nhiều quốc gia\n(D) Franta Exports có 18 văn phòng tại Vương quốc Anh"},{"n":199,"q":"What can be concluded about Mr. Lennox?","qvi":"Có thể kết luận điều gì về ông Lennox?","opts":["He interviewed for a managerial position in Cardiff.","He was hired to work at an office in his hometown.","He is required to travel throughout the United Kingdom.","He works at the same location as Ms. Scott does."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Kết hợp 2 bài: Email 1: \"the open office manager position ... at Franta Exports here in my hometown of Liverpool\" (quê ông là Liverpool). Tấm biển: \"Welcome to the Franta Exports Liverpool Office! ... Office manager: Jerome Lennox\" → ông đã được tuyển làm quản lý văn phòng ở quê nhà Liverpool.\n(A) Ông đã phỏng vấn cho vị trí quản lý tại Cardiff.\n(B) Ông được tuyển dụng làm việc tại văn phòng ở quê nhà.\n(C) Ông phải đi công tác khắp Vương quốc Anh.\n(D) Ông làm việc cùng địa điểm với bà Scott."},{"n":200,"q":"Where was Mr. Lennox’s follow-up meeting held?","qvi":"Cuộc họp tiếp theo của ông Lennox được tổ chức ở đâu?","opts":["At 732 Park Avenue","At 10 Donegal Lane","At 660 Richmond Avenue","At 42 Church Road"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Kết hợp 2 bài: Email 2: \"a follow-up in-person appointment at our headquarters in Portsmouth\" (buổi gặp trực tiếp tiếp theo tại trụ sở chính ở Portsmouth). Tấm biển: \"732 Park Avenue, Portsmouth PO5 3QQ (U.K. Headquarters)\" → cuộc gặp diễn ra tại 732 Park Avenue (ông được tuyển nên đã qua vòng gặp trực tiếp này).\n(A) 732 Park Avenue\n(B) 10 Donegal Lane\n(C) 660 Richmond Avenue\n(D) 42 Church Road"}]}]}};
